fn clean_join_page(
    path: &str,
    kind: ManagedTextKind,
    preamble: Option<&str>,
    outline: &[(usize, &str, Option<u128>)],
) -> CleanJoinUserPage {
    CleanJoinUserPage {
        path: path.to_owned(),
        kind,
        preamble: preamble.map(str::to_owned),
        outline: outline
            .iter()
            .map(|(depth, content, uuid)| {
                (
                    *depth,
                    (*content).to_owned(),
                    uuid.map(|value| LogseqUuid::from_uuid(Uuid::from_u128(value))),
                )
            })
            .collect(),
        projected_ids: outline
            .iter()
            .map(|(_, _, uuid)| uuid.map(|value| LogseqUuid::from_uuid(Uuid::from_u128(value))))
            .collect(),
    }
}

