/// The startup contract for discovered pre-0.7 state: a typed
/// self-resolving status, not an error string. The Tauri layer archives
/// the private root and reopens the graph in Direct Files.
#[test]
fn pre_07_discovery_supersedes_instead_of_refusing_in_production_builds() {
    let source = include_str!("sync_runtime.rs");
    let arm = source
        .find("DiscoveryClassification::ExistingLocalActive(_)")
        .expect("the discovery classification arm must exist");
    let window = &source[arm..arm + 1200];
    assert!(
        window.contains("SyncRuntimeOpenStatus::SupersededLegacyState"),
        "discovered pre-0.7 state must map to SupersededLegacyState, never to a refusal"
    );
    // Blank-slate ruling: damaged, blocked, mid-import, and
    // schema-incompatible pre-0.7 state supersedes exactly like intact
    // state — the layout is written by no current version, so damage here
    // is damage to an unsupported format.
    for damaged_arm in [
        "DiscoveryClassification::ExistingNonActive(_)",
        "DiscoveryClassification::Blocked(_)",
        "DiscoveryClassification::UnsupportedOrIncompatible(_, _)",
        "DiscoveryClassification::CorruptOrUnreadable(_, _)",
    ] {
        let position = window
            .find(damaged_arm)
            .expect("every damaged pre-0.7 shape must be in the superseding arm");
        assert!(
            position
                < window
                    .find("SyncRuntimeOpenStatus::SupersededLegacyState")
                    .unwrap(),
            "{damaged_arm} must share the superseding arm"
        );
    }
    // The two deliberate refusals survive: unsafe filesystem shapes
    // (symlink/special file — attack or misconfiguration, not age) and
    // transient I/O (retiring on a mount failure could archive healthy
    // state).
    assert!(
        window.contains("ManagedStorageRefusalScenario::UnsafeFilesystemKind"),
        "unsafe filesystem shapes must stay loud refusals"
    );
    assert!(
        !window.contains("#[cfg(test)]"),
        "supersession is unconditional: no build may keep a pre-0.7 actor start here"
    );
}

/// Plant the state the (c) §6 gate calls for: a live page name missing with
/// its valid claim twin beside it. `Graph::open_checked`'s publication
/// recovery restores exactly this shape, so it is what proves the claim
/// precheck ran BEFORE any graph mutation could begin.
fn plant_pending_publication_artifact(graph_root: &Path) -> (PathBuf, PathBuf, Vec<u8>) {
    let live = graph_root.join("pages").join("Precheck.md");
    fs::create_dir_all(live.parent().unwrap()).unwrap();
    let claim = live
        .parent()
        .unwrap()
        .join(".Precheck.md.4242.1.editor-recovery");
    let bytes = b"- pending publication\n".to_vec();
    fs::write(&claim, &bytes).unwrap();
    assert!(!live.exists());
    (live, claim, bytes)
}

fn store_claim_path(request: &SyncLocalActivationRequest) -> PathBuf {
    request.receipt_root.join("projection-receipts.claim")
}

/// A store this build cannot serve is refused at the HEAD of the clean cold
/// open, before `Graph::open_checked` can rename a single graph file.
///
/// In-scope scenario: an honest pre-(c) private store meets a (c) build.
/// Recovery is re-activation; the user's Markdown is untouched, and this
/// asserts that literally -- the whole graph tree is byte-identical after
/// the refused open.
#[test]
fn a_pre_c_private_store_is_refused_before_any_graph_mutation() {
    let fixture = ActivationFixture::nested_unicode("precheck-pre-c-store", 0xc1a0);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("precheck fixture activates");
    drive_initial_feed(&handle);
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    // The immediately previous claim family must be recognized and refused.
    let claim_path = store_claim_path(&fixture.request);
    let mut claim = Vec::new();
    claim.extend_from_slice(b"TINEPR6\0");
    claim.extend_from_slice(&6_u32.to_be_bytes());
    claim.extend_from_slice(&[0_u8; 32]);
    claim.extend_from_slice(fixture.request.identities.workspace_id.as_uuid().as_bytes());
    claim.extend_from_slice(&[0_u8; 1 + 16 + 16 + 32 + 5 * 32]);
    fs::write(&claim_path, &claim).unwrap();

    let (live, artifact, artifact_bytes) = plant_pending_publication_artifact(&fixture.graph_root);
    let before = user_graph_bytes(&fixture.graph_root);

    let result = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert!(result.handle.is_none());
    let SyncRuntimeOpenStatus::OpenRefused { detail } = &result.status else {
        panic!("a pre-(c) store must surface a managed-open refusal: {result:?}");
    };
    assert_eq!(
        serde_json::from_str::<serde_json::Value>(detail).unwrap(),
        serde_json::json!({
            "kind": "clean-open",
            "reason_code": "clean_open.projection_store",
            "detail": { "scenario": "MS-REF-PROTOCOL-INCOMPATIBLE" },
        }),
        "the low-level refusal carries only its typed source and scenario codes"
    );
    assert_eq!(
        result.status.durable_refusal_scenario(),
        Some(ManagedStorageRefusalScenario::ProtocolIncompatible),
        "a refused pre-(c) store is a durable refusal, not a retryable one"
    );
    assert!(
        !matches!(result.status, SyncRuntimeOpenStatus::SupersededLegacyState),
        "the (c) refusal must never become a silent Direct-Files fall-through"
    );

    assert_eq!(
        user_graph_bytes(&fixture.graph_root),
        before,
        "a refused open must not change one byte of the user's graph"
    );
    assert!(
        !live.exists(),
        "publication recovery must not have run: the live name is still absent"
    );
    assert_eq!(fs::read(&artifact).unwrap(), artifact_bytes);
    assert_eq!(fs::read(&claim_path).unwrap(), claim);
}

/// R21-C1: a current-magic header on a truncated claim body must not pass.
/// A magic-only precheck would let it through, and graph publication
/// recovery would then run before the in-place length check ever fired.
#[test]
fn a_torn_store_claim_is_refused_before_any_graph_mutation() {
    let fixture = ActivationFixture::nested_unicode("precheck-torn-claim", 0xc1a1);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("precheck fixture activates");
    drive_initial_feed(&handle);
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let claim_path = store_claim_path(&fixture.request);
    let full = fs::read(&claim_path).unwrap();
    assert!(full.len() > 12, "a current claim is longer than its header");
    let torn = full[..full.len() - 1].to_vec();
    fs::write(&claim_path, &torn).unwrap();

    let (live, artifact, artifact_bytes) = plant_pending_publication_artifact(&fixture.graph_root);
    let before = user_graph_bytes(&fixture.graph_root);

    let result = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert!(result.handle.is_none());
    assert!(
        matches!(result.status, SyncRuntimeOpenStatus::OpenRefused { .. }),
        "a torn claim must surface a managed-open refusal: {result:?}"
    );
    assert_eq!(
        user_graph_bytes(&fixture.graph_root),
        before,
        "a refused open must not change one byte of the user's graph"
    );
    assert!(!live.exists());
    assert_eq!(fs::read(&artifact).unwrap(), artifact_bytes);
    assert_eq!(fs::read(&claim_path).unwrap(), torn);
}

/// The claim provably predates the activation authority marker, so a
/// populated claimless private store on an authoritative graph is broken,
/// not initializable. It is refused before any graph mutation too.
#[test]
fn a_claimless_populated_private_store_is_refused_before_any_graph_mutation() {
    let fixture = ActivationFixture::nested_unicode("precheck-claimless", 0xc1a2);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("precheck fixture activates");
    drive_initial_feed(&handle);
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    fs::remove_file(store_claim_path(&fixture.request)).unwrap();
    let (live, _, _) = plant_pending_publication_artifact(&fixture.graph_root);
    let before = user_graph_bytes(&fixture.graph_root);

    let result = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert!(result.handle.is_none());
    assert!(
        matches!(result.status, SyncRuntimeOpenStatus::OpenRefused { .. }),
        "a claimless populated store must be refused: {result:?}"
    );
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);
    assert!(!live.exists());
}

/// The precheck is not a new gate on ordinary use: a fresh store has no
/// claim to check, activation initializes it exactly as before, and the
/// next cold open serves normally.
#[test]
fn the_claim_precheck_leaves_fresh_activation_and_ordinary_reopen_unaffected() {
    let fixture = ActivationFixture::nested_unicode("precheck-fresh", 0xc1a3);
    assert!(!store_claim_path(&fixture.request).exists());
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("fresh activation is unaffected");
    drive_initial_feed(&handle);
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let claim = fs::read(store_claim_path(&fixture.request)).unwrap();
    assert!(
        claim.starts_with(b"TINEPR7\0"),
        "a freshly initialized store carries the current claim magic"
    );

    let reopened = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
    assert!(matches!(
        reopened.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// Behavior half of the blank-slate ruling: damaged pre-0.7 residue
/// supersedes into Direct Files (the Tauri layer archives it aside and
/// reopens fresh), while an unsafe filesystem shape at the same location
/// stays a loud refusal — hostile-shaped sync residue or
/// misconfiguration, not age, and retiring it could follow a link out of
/// the private root.
#[test]
fn pre_07_residue_supersedes_and_unsafe_shapes_still_refuse() {
    let fixture = ActivationFixture::empty("pre07-residue-supersedes", 0xd0b1);
    fs::create_dir_all(&fixture.request.archive_root).unwrap();
    let result = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert!(result.handle.is_none());
    assert!(
        matches!(result.status, SyncRuntimeOpenStatus::SupersededLegacyState),
        "pre-0.7 archive residue must supersede, got {:?}",
        result.status
    );

    #[cfg(unix)]
    {
        let fixture = ActivationFixture::empty("pre07-unsafe-refuses", 0xd0b2);
        let target = fixture.request.archive_root.with_file_name("elsewhere");
        fs::create_dir_all(&target).unwrap();
        std::os::unix::fs::symlink(&target, &fixture.request.archive_root).unwrap();
        let result = SyncRuntimeHandle::open(reopen_request(&fixture.request));
        assert!(result.handle.is_none());
        assert!(
            matches!(
                result.status,
                SyncRuntimeOpenStatus::AmbiguousOrForeignResidue {
                    scenario: ManagedStorageRefusalScenario::UnsafeFilesystemKind,
                    ..
                }
            ),
            "an unsafe archive-root shape must stay a refusal, got {:?}",
            result.status
        );
    }
}

/// The pre-0.7 activation stack is deleted, not merely unreachable. Each
/// identifier below named a constructor of the promoted generation; a
/// reappearance would revive an actor the clean baseline+manifest runtime
/// no longer knows how to own, so the oracle refuses the name itself.
#[test]
fn pre_07_activation_oracle_is_absent_from_the_source() {
    let source = include_str!("sync_runtime.rs");
    // The needles are assembled from fragments: a literal spelling of a
    // deleted identifier would itself satisfy the search and make this
    // oracle report its own text as a revival.
    for deleted_entry in [
        concat!("struct ", "SameProcessActivationHandoff"),
        concat!("fn ", "activate_non_active_local("),
        concat!("fn ", "activation_open_same_process_runtime("),
        concat!("fn ", "actor_thread("),
        concat!("fn ", "actor_thread_from_same_process_activation("),
        concat!("fn ", "open_from_same_process_activation("),
        concat!("fn ", "from_proven_resources("),
        concat!("fn ", "prepare_shared_legacy("),
        concat!("fn ", "join_shared_legacy("),
    ] {
        assert!(
            !source.contains(deleted_entry),
            "a deleted pre-0.7 activation entry point came back: {deleted_entry}"
        );
    }
}

/// H2 1b: the retired JSON shared-enrollment lifecycle is no longer decoded.
/// Its raw fixture is classified as protocol-incompatible, the one refusal the
/// application layer answers by preserving the private root and rebuilding
/// from Direct Files.
#[test]
fn pre_07_shared_descriptor_fixture_routes_to_preserve_and_rebuild() {
    let fixture = br#"{"schema_version":6,"lifecycle":{"state":"shared_active","descriptor":{"schema_version":1}}}"#;
    let error = crate::oplog::enrollment::decode_enrollment_record_for_test(fixture)
        .expect_err("the retired shared descriptor lifecycle must not decode");
    assert!(matches!(
        error,
        EnrollmentError::FutureUnsupportedLifecycle(ref state) if state == "shared_active"
    ));
    assert!(matches!(
        classify_enrollment_error(error),
        DiscoveryClassification::UnsupportedOrIncompatible(
            DiscoveryComponent::Enrollment,
            ManagedStorageRefusalScenario::ProtocolIncompatible,
        )
    ));

    let enrollment = include_str!("oplog/enrollment.rs");
    let runtime = include_str!("sync_runtime.rs");
    assert!(!enrollment.contains(&["struct SharedEnrollmentDescriptor", "V1",].concat()));
    assert!(!runtime.contains(&["Legacy", "(SharedEnrollmentDescriptor", "V1)"].concat()));
}

