#[test]
fn clean_generation_refusal_stems_are_pinned_to_in_scope_scenarios() {
    let runtime = include_str!("sync_runtime.rs");
    let contract = include_str!("../../../docs/storage-sync-contract.md");
    for (stem, scenario) in [
        (
            "clean authority orphan is not a private directory",
            "MS-REF-UNSAFE-FS-KIND",
        ),
        (
            "clean shared join generation destination already exists",
            "MS-REF-STALE-GENERATION",
        ),
    ] {
        assert!(
            runtime.contains(stem),
            "production refusal stem drifted: {stem}"
        );
        let row = contract
            .lines()
            .find(|line| line.contains(stem))
            .unwrap_or_else(|| panic!("I-8: refusal '{stem}' has no §3.1 scenario row"));
        assert!(
            row.contains(scenario),
            "I-8: refusal '{stem}' must name its in-scope {scenario} scenario"
        );
    }
}

#[test]
fn every_public_durable_open_and_activation_class_has_a_scenario() {
    let open = [
        SyncRuntimeOpenStatus::Blocked {
            reason_code: "shared.descriptor-conflict".into(),
        },
        SyncRuntimeOpenStatus::UnsupportedOrIncompatible {
            component: SyncRuntimeComponent::Enrollment,
            scenario: ManagedStorageRefusalScenario::ProtocolIncompatible,
        },
        SyncRuntimeOpenStatus::CorruptOrUnreadable {
            component: SyncRuntimeComponent::Archive,
            scenario: ManagedStorageRefusalScenario::DiskCorrupt,
        },
        SyncRuntimeOpenStatus::AmbiguousOrForeignResidue {
            evidence: SyncAmbiguousEvidence::ArchiveBinding,
            scenario: ManagedStorageRefusalScenario::SyncConflict,
        },
        SyncRuntimeOpenStatus::OpenRefused {
            detail: "reconciliation baseline refused (MS-REF-UNSAFE-FS-KIND)".into(),
        },
    ];
    assert!(
        open.iter()
            .all(|status| status.durable_refusal_scenario().is_some()),
        "every durable public open refusal must identify its scenario"
    );

    let activation = [
        SyncLocalActivationStatus::Blocked {
            reason_code: "explicit_identity_binding_mismatch".into(),
        },
        SyncLocalActivationStatus::UnsupportedOrIncompatible {
            component: SyncRuntimeComponent::Enrollment,
            scenario: ManagedStorageRefusalScenario::ProtocolIncompatible,
        },
        SyncLocalActivationStatus::CorruptOrUnreadable {
            component: SyncRuntimeComponent::Archive,
            scenario: ManagedStorageRefusalScenario::DiskCorrupt,
        },
        SyncLocalActivationStatus::AmbiguousOrForeignResidue {
            evidence: SyncAmbiguousEvidence::EnrollmentResidue,
            scenario: ManagedStorageRefusalScenario::CrashTruncated,
        },
    ];
    assert!(
        activation
            .iter()
            .all(|status| status.durable_refusal_scenario().is_some()),
        "every durable public activation refusal must identify its scenario"
    );
}

#[test]
fn every_blocked_reason_literal_is_in_the_refusal_contract_vocabulary() {
    let production_sources = [
        include_str!("oplog/enrollment.rs"),
        include_str!("sync_runtime.rs"),
    ];
    let emitted = production_sources
        .into_iter()
        .flat_map(|source| source.split('"').skip(1).step_by(2))
        .filter(|literal| {
            literal.starts_with("shared.")
                || *literal == "explicit_identity_binding_mismatch"
                || *literal == "proof.failed"
        })
        .collect::<BTreeSet<_>>();
    let registered = crate::oplog::BLOCKED_REASON_SCENARIOS
        .into_iter()
        .map(|(reason, _)| reason)
        .collect::<BTreeSet<_>>();
    assert_eq!(
        emitted, registered,
        "adding or removing a durable blocked reason requires an explicit scenario mapping"
    );
}

#[test]
fn application_search_lane_epoch_cancels_only_the_older_same_lane_request() {
    let lanes = Mutex::new(HashMap::new());
    let first = begin_application_search_cancellation(&lanes, "ctrl-k");
    let independent = begin_application_search_cancellation(&lanes, "block-picker");
    assert!(!first.cancelled());
    assert!(!independent.cancelled());

    let second = begin_application_search_cancellation(&lanes, "ctrl-k");
    assert!(first.cancelled());
    assert!(!second.cancelled());
    assert!(!independent.cancelled());
}

fn install_shared_join_pause(
    workspace_id: WorkspaceId,
    point: SharedJoinTestPausePoint,
) -> (Receiver<()>, SyncSender<()>) {
    let (entered_sender, entered_receiver) = mpsc::sync_channel(0);
    let (resume_sender, resume_receiver) = mpsc::sync_channel(0);
    assert!(
        SHARED_JOIN_TEST_PAUSES
            .lock()
            .unwrap()
            .insert(
                workspace_id,
                SharedJoinTestPause {
                    point,
                    entered: entered_sender,
                    resume: resume_receiver,
                },
            )
            .is_none(),
        "shared join test pause was already installed"
    );
    (entered_receiver, resume_sender)
}

#[test]
fn clean_join_generation_crash_cuts_recover_to_the_marker_named_pair() {
    for (index, (point, marker_committed, baseline_published, operations_published)) in [
        (
            SharedJoinTestPausePoint::AfterBaselineSwap,
            false,
            true,
            false,
        ),
        (
            SharedJoinTestPausePoint::AfterOperationSwap,
            false,
            true,
            true,
        ),
        (
            SharedJoinTestPausePoint::AfterAuthorityDirectorySync,
            false,
            true,
            true,
        ),
        (
            SharedJoinTestPausePoint::AfterMarkerReplacement,
            true,
            true,
            true,
        ),
    ]
    .into_iter()
    .enumerate()
    {
        let (_initiator, joiner, handle, descriptor) = pending_generation_join_fixture(
            &format!("join-generation-cut-{point:?}"),
            0xc100_0000 + index as u128 * 0x100,
        );
        let workspace_id = joiner.request.identities.workspace_id;
        let (entered, resume) = install_shared_join_pause(workspace_id, point);
        let joining_handle = handle.clone();
        let joining = std::thread::spawn(move || joining_handle.join_shared(descriptor));
        entered
            .recv_timeout(Duration::from_secs(30))
            .unwrap_or_else(|_| panic!("clean join did not reach {point:?}"));

        let observed_marker = read_activation_marker(&joiner.request.enrollment_root)
            .unwrap()
            .expect("the join cut retains an authority marker");
        assert_eq!(
            observed_marker.generation(),
            u64::from(marker_committed),
            "{point:?}"
        );
        let prior_observed = clean_authority_directories(&joiner.request.archive_root, 0);
        let candidate_observed = clean_authority_directories(&joiner.request.archive_root, 1);
        assert!(prior_observed.baseline.is_dir(), "{point:?}");
        assert!(prior_observed.operations.is_dir(), "{point:?}");
        assert_eq!(
            candidate_observed.baseline.is_dir(),
            baseline_published,
            "{point:?}"
        );
        assert_eq!(
            candidate_observed.operations.is_dir(),
            operations_published,
            "{point:?}"
        );
        resume.send(()).unwrap();
        assert!(
            joining.join().unwrap().is_ok(),
            "the real join did not resume after {point:?}"
        );
        assert!(matches!(
            handle.clean_shutdown(),
            Ok(SyncShutdownOutcome::Safe(_))
        ));

        // Apply the same next-open resolver to an exact filesystem shape for
        // the interrupted cut. The live join above proves the cut mapping;
        // this isolated shape proves recovery without disturbing its actor.
        let root = std::env::temp_dir().join(format!(
            "tine-clean-join-generation-cut-{point:?}-{}",
            Uuid::new_v4().simple()
        ));
        let archive = root.join("archive");
        let enrollment = root.join("enrollment");
        fs::create_dir_all(&archive).unwrap();
        let workspace = WorkspaceId::from_uuid(Uuid::from_u128(0xc101));
        let lineage = LineageDigest::of(b"clean-join-generation-cut");
        let marker = |generation| {
            LazyGenesisActivationMarkerV1::new_for_generation(
                workspace,
                lineage,
                generation,
                ContentDigest::of(format!("baseline-{generation}").as_bytes()),
                BlobDescription::of(b"source-capture"),
                ContentDigest::of(format!("frontier-{generation}").as_bytes()),
                generation,
            )
            .unwrap()
        };
        let prior = marker(0);
        let prior_directories = clean_authority_directories(&archive, 0);
        fs::create_dir_all(&prior_directories.baseline).unwrap();
        fs::create_dir_all(&prior_directories.operations).unwrap();
        crate::oplog::lazy_genesis::publish_activation_marker(&enrollment, prior).unwrap();

        let candidate_directories = clean_authority_directories(&archive, 1);
        if baseline_published {
            fs::create_dir_all(&candidate_directories.baseline).unwrap();
        }
        if operations_published {
            fs::create_dir_all(&candidate_directories.operations).unwrap();
        }
        fs::create_dir_all(archive.join(".clean-join-uncommitted")).unwrap();
        if marker_committed {
            replace_activation_marker_for_join(&enrollment, prior, marker(1)).unwrap();
        }

        let resolved = resolve_clean_authority_directories(
            &archive,
            &enrollment,
            &root.join("projection.sqlite"),
        )
        .unwrap()
        .expect("the marker retains one authority generation");
        let expected = if marker_committed {
            &candidate_directories
        } else {
            &prior_directories
        };
        let orphan = if marker_committed {
            &prior_directories
        } else {
            &candidate_directories
        };
        assert_eq!(resolved.baseline, expected.baseline, "{point:?}");
        assert_eq!(resolved.operations, expected.operations, "{point:?}");
        assert!(expected.baseline.is_dir(), "{point:?}");
        assert!(expected.operations.is_dir(), "{point:?}");
        assert!(!orphan.baseline.exists(), "{point:?}");
        assert!(!orphan.operations.exists(), "{point:?}");
        assert!(!archive.join(".clean-join-uncommitted").exists());
        fs::remove_dir_all(root).unwrap();
    }

    let source = include_str!("sync_runtime.rs");
    let start = source
        .find("    fn install_clean_join_candidate(")
        .expect("join installation remains present");
    let end = source[start..]
        .find("\n    fn join_shared_clean(")
        .map(|offset| start + offset)
        .expect("join installation remains bounded");
    let install = &source[start..end];
    assert_eq!(
        install
            .matches("replace_activation_marker_for_join(")
            .count(),
        1
    );
    assert!(!install.contains(".prior"));
    assert!(!install.contains("canonical_baseline"));
}

fn empty_request(profile: SyncStorageProfile) -> (PathBuf, SyncRuntimeOpenRequest) {
    let root = std::env::temp_dir().join(format!("tine-sync-runtime-empty-{}", Uuid::new_v4()));
    let graph_root = root.join("graph");
    fs::create_dir_all(&graph_root).unwrap();
    (
        root.clone(),
        SyncRuntimeOpenRequest {
            profile,
            clean_identities: None,
            graph_root,
            enrollment_root: root.join("enrollment"),
            archive_root: root.join("archive"),
            receipt_root: root.join("receipts"),
            database_path: root.join("projection.sqlite"),
            application_runtime_root: root.join("application-runtime"),
            provider_root: root.join("graph/.tine-sync/v2/shared"),
            provider_journal_root: root.join("application-runtime/provider/device/journal"),
        },
    )
}

#[test]
fn handle_is_cloneable_send_and_sync_while_actor_is_not_send_or_sync() {
    fn assert_send_sync_clone<T: Send + Sync + Clone>() {}
    assert_send_sync_clone::<SyncRuntimeHandle>();
    let _public_submit: fn(
        &SyncRuntimeHandle,
        OperationTransaction,
    ) -> Result<SyncLocalMutationOutcome, SyncLocalMutationRequestError> =
        SyncRuntimeHandle::submit_local_mutation;

    trait AmbiguousIfSend<Marker> {
        fn assert_not_send() {}
    }
    impl<T: ?Sized> AmbiguousIfSend<()> for T {}
    impl<T: ?Sized + Send> AmbiguousIfSend<u8> for T {}
    <RuntimeActor as AmbiguousIfSend<_>>::assert_not_send();

    trait AmbiguousIfSync<Marker> {
        fn assert_not_sync() {}
    }
    impl<T: ?Sized> AmbiguousIfSync<()> for T {}
    impl<T: ?Sized + Sync> AmbiguousIfSync<u8> for T {}
    <RuntimeActor as AmbiguousIfSync<_>>::assert_not_sync();
}

#[test]
fn managed_save_refusal_codes_are_bounded_and_render_through_application_error() {
    const STAGE: &str = "committing the semantic page transaction";
    let codes = [
        SyncEditorRefusalCode::TrustedLocalMissingBaseRevision,
        SyncEditorRefusalCode::TrustedLocalPreparationBindings,
        SyncEditorRefusalCode::TrustedLocalPreparationPlanning,
        SyncEditorRefusalCode::TrustedLocalPreparationDraft,
        SyncEditorRefusalCode::TrustedLocalPreparationCapture,
        SyncEditorRefusalCode::TrustedLocalPreparationFinalize,
        SyncEditorRefusalCode::TrustedLocalPreparationPublication,
        SyncEditorRefusalCode::TrustedLocalPreparationArchiveStage,
        SyncEditorRefusalCode::TrustedLocalPreparationSqliteDrain,
        SyncEditorRefusalCode::TrustedLocalPreparationProjectionDrain,
        SyncEditorRefusalCode::TrustedLocalEngineAuthority,
        SyncEditorRefusalCode::TrustedLocalCommitInvalidPreparedInput,
        SyncEditorRefusalCode::TrustedLocalCommitManagedRecord,
        SyncEditorRefusalCode::TrustedLocalCommitPrecommitGraph,
        SyncEditorRefusalCode::FallbackReadmission,
        SyncEditorRefusalCode::PostCommitCurrentPageLookup,
        SyncEditorRefusalCode::TrustedOutcomeDeclined,
        SyncEditorRefusalCode::ManagedSequenceOverflow,
        SyncEditorRefusalCode::ManagedQueueMonotonicity,
        SyncEditorRefusalCode::ManagedRecordDecode,
    ];
    let mut unique = BTreeSet::new();
    for code in codes {
        assert!(unique.insert(code.as_str()), "refusal codes must be unique");
        assert!(
            code.as_str().bytes().all(|byte| {
                byte.is_ascii_lowercase() || byte.is_ascii_digit() || matches!(byte, b'.' | b'_')
            }),
            "refusal codes must remain bounded identifiers: {code}"
        );
        assert!(code.as_str().len() <= 48);

        let staged = editor_refusal_at(SyncEditorRequestError::ActorRefusedWithCode(code), STAGE);
        assert_eq!(
            staged,
            SyncEditorRequestError::ActorRefusedAtWithCode { stage: STAGE, code }
        );
        let application = map_editor_application_error(staged);
        assert_eq!(
            application,
            SyncApplicationPageRequestError::ActorRefusedAtWithCode { stage: STAGE, code }
        );
        assert_eq!(
            application.to_string(),
            format!("sync actor refused application page intent at {STAGE} (reason code: {code})")
        );
    }

    assert_eq!(
        SyncApplicationPageRequestError::ActorRefusedAt(STAGE).to_string(),
        "sync actor refused application page intent at committing the semantic page transaction",
        "uncoded refusal rendering remains unchanged"
    );
}

