#[test]
fn clean_actor_core_retains_one_manifested_save_until_projection_finishes() {
    let fixture = ActivationFixture::nested_unicode("clean-actor-save", 0xa175);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let CleanRuntimeResources {
        graph,
        receipts,
        runtime,
        managed_local,
        projection_turns,
        sweeps,
        recovered_provider_batches: _,
    } = resources;
    drop(managed_local);
    let mut projection_turns = projection_turns;
    let mut actor = CleanRuntimeActorCore::new(runtime, sweeps, false);
    let root_path = ManagedPath::parse("Root.md".to_owned()).unwrap();
    let owner = actor
        .runtime
        .database()
        .materialized_read()
        .unwrap()
        .pages_by_path(&root_path, 2)
        .unwrap()
        .pop()
        .expect("clean SQLite names Root.md");
    let current = actor
        .load_current_editor_page(owner.page_id)
        .unwrap()
        .expect("clean actor loads Root.md from SQLite");
    let first = current.blocks.first().expect("Root.md has one block");
    let block_id = first.block_id;
    let home_document_id = first.home_document_id;
    let transaction = OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
        block: BlockLocation {
            block_id,
            home_document_id,
        },
        content: "clean actor exact save".into(),
    }])
    .unwrap();
    let before = fs::read(fixture.graph_root.join("Root.md")).unwrap();

    fail_once_at(OperationalFaultPoint::AfterManifest);
    let pending = actor
        .execute_local(&graph, &receipts, &transaction, &mut projection_turns)
        .unwrap();
    let pending_batch = match pending {
        CleanActorMutationOutcome::DurablePending { batch_id, phase } => {
            assert_eq!(phase, OperationalPhase::Publication);
            batch_id
        }
        CleanActorMutationOutcome::Durable(_)
        | CleanActorMutationOutcome::RetainedPriorPending { .. }
        | CleanActorMutationOutcome::DurableStuck { .. } => {
            panic!("fault must retain this submission's own durable work")
        }
    };
    assert_eq!(
        fs::read(fixture.graph_root.join("Root.md")).unwrap(),
        before,
        "manifest commit must not pretend Markdown projection completed"
    );
    // A second submission while a continuation is retained is NOT this
    // submission's own pending work: it never executed. The distinct
    // outcome is what stops a caller settling the earlier batch and then
    // reporting the second request as saved.
    let same_pending = actor
        .execute_local(&graph, &receipts, &transaction, &mut projection_turns)
        .unwrap();
    assert!(matches!(
        same_pending,
        CleanActorMutationOutcome::RetainedPriorPending { batch_id, .. }
            if batch_id == pending_batch
    ));
    assert_eq!(
        actor.retry_pending_with_turns(&graph, &receipts, &mut projection_turns),
        Some(CleanActorMutationOutcome::Durable(pending_batch))
    );
    assert!(fs::read_to_string(fixture.graph_root.join("Root.md"))
        .unwrap()
        .contains("clean actor exact save"));
    let saved = actor
        .load_current_editor_page(owner.page_id)
        .unwrap()
        .expect("clean actor reloads the saved page");
    assert_eq!(saved.blocks[0].content, "clean actor exact save");
    drop(actor);
    drop(projection_turns);

    let reopened = open_clean_runtime_resources(&reopen_request(&fixture.request))
        .unwrap()
        .expect("clean actor save cold-reopens");
    assert_eq!(reopened.runtime.engine().accepted_batch_count().unwrap(), 1);
    assert_eq!(
        reopened
            .runtime
            .database()
            .materialized_read()
            .unwrap()
            .acceptance_sequence(),
        1
    );
}

/// A publication cut between object write and manifest commit is the
/// exact on-disk state a crash there leaves behind. The orphaned objects
/// must not make the graph unopenable, must have no semantic effect, and
/// a fresh session must complete the same edit.
#[test]
fn clean_object_only_publication_cut_reopens_without_semantic_effect() {
    let fixture = ActivationFixture::nested_unicode("clean-object-cut-reopen", 0xa176);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let CleanRuntimeResources {
        graph,
        receipts,
        runtime,
        managed_local,
        projection_turns,
        sweeps,
        recovered_provider_batches: _,
    } = resources;
    drop(managed_local);
    let mut projection_turns = projection_turns;
    let accepted_before = runtime.engine().accepted_batch_count().unwrap();
    let mut actor = CleanRuntimeActorCore::new(runtime, sweeps, false);
    let root_path = ManagedPath::parse("Root.md".to_owned()).unwrap();
    let owner = actor
        .runtime
        .database()
        .materialized_read()
        .unwrap()
        .pages_by_path(&root_path, 2)
        .unwrap()
        .pop()
        .expect("clean SQLite names Root.md");
    let current = actor
        .load_current_editor_page(owner.page_id)
        .unwrap()
        .expect("clean actor loads Root.md from SQLite");
    let first = current.blocks.first().expect("Root.md has one block");
    let transaction = OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
        block: BlockLocation {
            block_id: first.block_id,
            home_document_id: first.home_document_id,
        },
        content: "edit cut after objects".into(),
    }])
    .unwrap();
    let before_bytes = fs::read(fixture.graph_root.join("Root.md")).unwrap();

    crate::oplog::object_store::fail_next_publish_after_objects();
    let cut = actor.execute_local(&graph, &receipts, &transaction, &mut projection_turns);
    assert!(
        !matches!(cut, Ok(CleanActorMutationOutcome::Durable(_))),
        "the armed object-only cut must not report a durable save: {cut:?}"
    );
    assert_eq!(
        fs::read(fixture.graph_root.join("Root.md")).unwrap(),
        before_bytes,
        "an unpublished batch must not project Markdown"
    );
    drop(actor);
    drop(projection_turns);

    let reopened = open_clean_runtime_resources(&reopen_request(&fixture.request))
        .unwrap()
        .expect("an object-only publication cut must not make the graph unopenable");
    let CleanRuntimeResources {
        graph,
        receipts,
        runtime,
        managed_local,
        projection_turns,
        sweeps,
        recovered_provider_batches: _,
    } = reopened;
    drop(managed_local);
    let mut projection_turns = projection_turns;
    assert_eq!(
        runtime.engine().accepted_batch_count().unwrap(),
        accepted_before,
        "orphaned objects must not enter accepted history"
    );
    assert_eq!(
        fs::read(fixture.graph_root.join("Root.md")).unwrap(),
        before_bytes,
        "reopen must not project the cut batch"
    );

    let mut actor = CleanRuntimeActorCore::new(runtime, sweeps, false);
    let current = actor
        .load_current_editor_page(owner.page_id)
        .unwrap()
        .expect("reopened clean actor loads Root.md");
    let first = current.blocks.first().expect("Root.md still has one block");
    let retry = OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
        block: BlockLocation {
            block_id: first.block_id,
            home_document_id: first.home_document_id,
        },
        content: "edit cut after objects".into(),
    }])
    .unwrap();
    assert!(
        matches!(
            actor.execute_local(&graph, &receipts, &retry, &mut projection_turns),
            Ok(CleanActorMutationOutcome::Durable(_))
        ),
        "a fresh session must complete the same edit after the cut"
    );
    assert!(fs::read_to_string(fixture.graph_root.join("Root.md"))
        .unwrap()
        .contains("edit cut after objects"));
}

/// Locate the one directory with `name` below `root`, so a crash-repair
/// test can tear real on-disk bytes without hard-coding the private
/// managed layout.
fn find_single_named_directory(root: &Path, name: &str) -> Option<PathBuf> {
    let mut found = None;
    let mut pending = vec![root.to_path_buf()];
    while let Some(directory) = pending.pop() {
        let Ok(entries) = fs::read_dir(&directory) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if !path.is_dir() {
                continue;
            }
            if path.file_name().and_then(|value| value.to_str()) == Some(name) {
                assert!(
                    found.is_none(),
                    "expected exactly one {name} directory below the fixture"
                );
                found = Some(path);
            } else {
                pending.push(path);
            }
        }
    }
    found
}

/// A batched archive publication has one data barrier. Strict callers take
/// it before every final-name install. The managed-local drain may install
/// object names first while its exact journal frame remains undrained, then
/// takes the same barrier before installing the manifest and before the
/// caller may checkpoint.
///
/// This is the crash-safety contract in `docs/storage-sync-contract.md`,
/// "Durability barriers and the batch commit point": a pre-barrier object
/// final may be torn only while the undrained journal still supplies its
/// exact repair authority. After the barrier every surviving name has
/// durable, byte-correct content, and the manifest remains absent until
/// then.
///
/// In-scope scenario: crash or power loss during a batched publication.
#[test]
fn clean_batched_archive_publication_leaves_no_torn_immutable_name() {
    for cut in [
        ArchiveBatchCut::BeforeManifest,
        ArchiveBatchCut::DuringInstall,
    ] {
        let fixture = ActivationFixture::nested_unicode(
            &format!("clean-archive-batch-cut-{cut:?}"),
            0xa1c1 + cut as u128,
        );
        let graph = Graph::open_checked(&fixture.graph_root).unwrap();
        let resources =
            activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
        let CleanRuntimeResources {
            graph,
            receipts,
            runtime,
            managed_local,
            projection_turns,
            sweeps,
            recovered_provider_batches: _,
        } = resources;
        drop(managed_local);
        let mut projection_turns = projection_turns;
        let accepted_before = runtime.engine().accepted_batch_count().unwrap();
        let mut actor = CleanRuntimeActorCore::new(runtime, sweeps, false);
        let root_path = ManagedPath::parse("Root.md".to_owned()).unwrap();
        let owner = actor
            .runtime
            .database()
            .materialized_read()
            .unwrap()
            .pages_by_path(&root_path, 2)
            .unwrap()
            .pop()
            .expect("clean SQLite names Root.md");
        let edit = |actor: &mut CleanRuntimeActorCore| {
            let current = actor
                .load_current_editor_page(owner.page_id)
                .unwrap()
                .expect("clean actor loads Root.md");
            let first = current.blocks.first().expect("Root.md has one block");
            OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
                block: BlockLocation {
                    block_id: first.block_id,
                    home_document_id: first.home_document_id,
                },
                content: "batch cut edit".into(),
            }])
            .unwrap()
        };

        let objects_dir = find_single_named_directory(
            &fixture.root,
            crate::oplog::sync_layout::ARCHIVE_OBJECTS_DIR,
        )
        .expect("the archive publishes its objects namespace");
        let before_bytes = fs::read(fixture.graph_root.join("Root.md")).unwrap();
        let genesis_objects = archive_object_names(&objects_dir);

        match cut {
            ArchiveBatchCut::BeforeManifest => {
                crate::oplog::object_store::fail_next_publish_after_objects()
            }
            ArchiveBatchCut::DuringInstall => {
                crate::oplog::object_store::cut_after_next_archive_install()
            }
        }
        let transaction = edit(&mut actor);
        let cut_outcome =
            actor.execute_local(&graph, &receipts, &transaction, &mut projection_turns);
        assert!(
            !matches!(cut_outcome, Ok(CleanActorMutationOutcome::Durable(_))),
            "the armed {cut:?} cut must not report a durable save: {cut_outcome:?}"
        );
        assert_eq!(
            fs::read(fixture.graph_root.join("Root.md")).unwrap(),
            before_bytes,
            "an unpublished batch must not project Markdown"
        );
        drop(actor);
        drop(projection_turns);

        // The invariant: every installed final name still hashes to its
        // own content. Temporary names are not archive entries and are
        // allowed to hold anything.
        assert_archive_object_names_match_their_bytes(&objects_dir, cut);
        let installed = archive_object_names(&objects_dir)
            .difference(&genesis_objects)
            .count();
        assert!(
            !fs::read_dir(&objects_dir)
                .unwrap()
                .flatten()
                .any(|entry| entry.file_name().to_string_lossy().starts_with(".tmp-")),
            "an abandoned batch must not leak temporaries into the archive"
        );
        match cut {
            // The cut precedes the batch's barrier, so nothing may be
            // installed yet.
            ArchiveBatchCut::BeforeManifest => assert_eq!(
                installed, 0,
                "a pre-barrier cut must not install any final archive name"
            ),
            // The cut is mid-install, so the test is only meaningful if at
            // least one final name really was installed.
            ArchiveBatchCut::DuringInstall => assert!(
                installed > 0,
                "the mid-install cut did not install anything; the crash point is untested"
            ),
        }

        let reopened = open_clean_runtime_resources(&reopen_request(&fixture.request))
            .unwrap()
            .unwrap_or_else(|| panic!("a {cut:?} cut must not make the graph unopenable"));
        assert_eq!(
            reopened.runtime.engine().accepted_batch_count().unwrap(),
            accepted_before,
            "a torn batch must not enter accepted history"
        );
        let CleanRuntimeResources {
            graph,
            receipts,
            runtime,
            managed_local,
            projection_turns,
            sweeps,
            recovered_provider_batches: _,
        } = reopened;
        drop(managed_local);
        let mut projection_turns = projection_turns;
        let mut actor = CleanRuntimeActorCore::new(runtime, sweeps, false);
        let retry = edit(&mut actor);
        let repaired = actor.execute_local(&graph, &receipts, &retry, &mut projection_turns);
        assert!(
            matches!(repaired, Ok(CleanActorMutationOutcome::Durable(_))),
            "a fresh session must complete the same edit after a {cut:?} cut: {repaired:?}"
        );
        assert!(fs::read_to_string(fixture.graph_root.join("Root.md"))
            .unwrap()
            .contains("batch cut edit"));
        drop(actor);
        drop(projection_turns);

        let reopened = open_clean_runtime_resources(&reopen_request(&fixture.request))
            .unwrap()
            .expect("the completed batch cold-reopens");
        assert_eq!(reopened.runtime.engine().accepted_batch_count().unwrap(), 1);
        assert_archive_object_names_match_their_bytes(&objects_dir, cut);
    }
}

#[test]
fn cold_open_repairs_only_torn_objects_covered_by_an_undrained_local_record() {
    let fixture = ActivationFixture::nested_unicode("covered-torn-archive-object", 0xa1c4);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let mut actor = RuntimeActor::from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    )
    .unwrap();
    let (mut page, revision) = match actor
        .load_application_page(SyncApplicationPageLoadRequest {
            page: SyncApplicationPageSelector::ExactPath {
                path: "Root.md".into(),
            },
        })
        .unwrap()
    {
        SyncApplicationPageLoadOutcome::Loaded { page, revision } => (page, revision),
        other => panic!("foreground target did not load: {other:?}"),
    };
    page.blocks[0].raw = "journal-authorized torn object repair".into();
    crate::model::inject_journal_projection_before_publish_failure(std::io::Error::new(
        std::io::ErrorKind::Interrupted,
        "retain one undrained repair authority",
    ));
    let outcome = actor
        .save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::Existing {
                path: page.path.clone(),
                revision,
            },
            page,
        })
        .unwrap();
    assert!(matches!(
        outcome,
        SyncApplicationPageSaveOutcome::Deferred {
            state: SyncEditorDeferred::BlockedRecovery { .. }
        }
    ));
    let frame = actor
        .managed_local
        .as_ref()
        .unwrap()
        .frames
        .front()
        .expect("the injected cut retains one journal frame");
    let record = crate::oplog::decode_managed_local_record(frame).unwrap();
    let object_bytes = record.prepared_batch().objects()[0].encode().unwrap();
    let digest = ContentDigest::of(&object_bytes);

    let archive_path = clean_operation_archive_directory(&fixture.request.archive_root);
    let store = ObjectStore::open(&archive_path, fixture.request.identities.workspace_id).unwrap();
    assert_eq!(store.stage_object_bytes(&object_bytes).unwrap(), digest);
    let objects_dir = archive_path.join(crate::oplog::sync_layout::ARCHIVE_OBJECTS_DIR);
    let object_path = fs::read_dir(&objects_dir)
        .unwrap()
        .flatten()
        .map(|entry| entry.path())
        .find(|path| {
            path.file_name()
                .is_some_and(|name| name.to_string_lossy().contains(&digest.to_string()))
        })
        .expect("the covered object was published under its content address");
    fs::write(&object_path, b"torn object bytes").unwrap();
    drop(store);
    drop(actor);

    let reopened = open_clean_runtime_resources(&reopen_request(&fixture.request))
        .unwrap()
        .expect("an undrained record repairs its covered torn object");
    assert_eq!(fs::read(&object_path).unwrap(), object_bytes);
    drop(reopened);

    let uncovered = ActivationFixture::nested_unicode("uncovered-torn-archive-object", 0xa1c5);
    let activated = SyncRuntimeHandle::activate_or_resume_local(uncovered.request.clone());
    let handle = activated.handle.expect("uncovered fixture activates");
    drive_initial_feed(&handle);
    let (page, revision) = load_application_exact(&handle, "Root.md");
    save_application_block_text(
        &handle,
        page,
        revision,
        "a fully drained object has no repair authority",
    );
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    let archive_path = clean_operation_archive_directory(&uncovered.request.archive_root);
    let objects_dir = archive_path.join(crate::oplog::sync_layout::ARCHIVE_OBJECTS_DIR);
    let object_path = fs::read_dir(&objects_dir)
        .unwrap()
        .flatten()
        .map(|entry| entry.path())
        .find(|path| {
            path.is_file()
                && !path
                    .file_name()
                    .unwrap()
                    .to_string_lossy()
                    .starts_with(".tmp-")
        })
        .expect("activation published an object not covered by an undrained record");
    let uncovered_bytes = fs::read(&object_path).unwrap();
    let uncovered_digest = ContentDigest::of(&uncovered_bytes);
    assert!(
        object_path
            .file_name()
            .unwrap()
            .to_string_lossy()
            .contains(&uncovered_digest.to_string()),
        "the control object starts byte-correct"
    );
    fs::write(&object_path, b"uncovered torn bytes").unwrap();

    let refused = match open_clean_runtime_resources(&reopen_request(&uncovered.request)) {
        Err(error) => error,
        Ok(_) => panic!("a torn object without an undrained record must stay a refusal"),
    };
    assert_eq!(
        serde_json::from_str::<serde_json::Value>(&refused).unwrap(),
        serde_json::json!({
            "kind": "clean-open",
            "reason_code": "clean_open.store",
        }),
        "{refused}"
    );
}

#[derive(Clone, Copy, Debug)]
enum ArchiveBatchCut {
    /// Between the objects and the manifest, before the batch's barrier.
    BeforeManifest,
    /// Part-way through installing final names and before the directory
    /// barriers. This is post-barrier for strict publication and
    /// pre-barrier for the first journal-covered object install.
    DuringInstall,
}

fn archive_object_names(objects_dir: &Path) -> BTreeSet<String> {
    fs::read_dir(objects_dir)
        .unwrap()
        .flatten()
        .filter(|entry| entry.path().is_file())
        .map(|entry| entry.file_name().to_string_lossy().into_owned())
        .filter(|name| !name.starts_with(".tmp-"))
        .collect()
}

fn assert_archive_object_names_match_their_bytes(objects_dir: &Path, cut: ArchiveBatchCut) {
    for entry in fs::read_dir(objects_dir).unwrap().flatten() {
        let path = entry.path();
        if !path.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.starts_with(".tmp-") {
            continue;
        }
        let bytes = fs::read(&path).unwrap();
        let digest = format!("{}", ContentDigest::of(&bytes));
        assert!(
            name.contains(&digest),
            "after a {cut:?} cut the archive entry {name} does not name its own \
                 content ({digest}); a reader would refuse the whole archive"
        );
    }
}

/// An external formatting-only rewrite (same semantics, different bytes)
/// must be adopted as the endpoint's exact baseline: the file keeps the
/// external spelling and the next local save still works. Refusing to
/// adopt wedges Direct Files -- every later save demands a reconciliation
/// that will forever report Noop without fixing the drift.
///
/// The clean runtime re-proves the exact endpoint-local bytes against the
/// accepted semantic state at capture time. This keeps formatting out of
/// shared history while preserving the exact base-revision guard.
#[test]
fn clean_external_formatting_only_change_does_not_wedge_the_next_local_save() {
    let fixture = ActivationFixture::nested_unicode("clean-formatting-only-adopt", 0xa177);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("clean activation opens actor");
    drive_initial_feed(&handle);

    let original = fs::read_to_string(fixture.graph_root.join("Root.md")).unwrap();
    let formatted = original.replace('\n', "\r\n");
    assert_ne!(
        formatted, original,
        "the fixture page must have line endings"
    );
    fs::write(fixture.graph_root.join("Root.md"), formatted.as_bytes()).unwrap();
    handle
        .observe_watcher(vec![
            SyncWatcherObservation::managed_path("Root.md").unwrap()
        ])
        .unwrap();
    drain_until_settled(&handle);
    assert_eq!(
        fs::read_to_string(fixture.graph_root.join("Root.md")).unwrap(),
        formatted,
        "a formatting-only external change keeps the external spelling"
    );

    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(handle);
    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened
        .handle
        .expect("formatting-only lazy-genesis state reopens");

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let _ = save_application_block_text(&handle, page, revision, "saved after formatting");
    drain_managed_local(&handle);
    let first_saved = fs::read(fixture.graph_root.join("Root.md")).unwrap();
    assert!(first_saved.windows(2).any(|window| window == b"\r\n"));
    assert!(
        String::from_utf8(first_saved.clone())
            .unwrap()
            .contains("saved after formatting"),
        "the save after a formatting-only external change must reach the file"
    );

    // Repeat after the page has a manifest head, and cross a cold reopen:
    // neither predecessor source may confuse endpoint-local formatting
    // with a shared semantic mutation.
    let lf = String::from_utf8(first_saved)
        .unwrap()
        .replace("\r\n", "\n");
    fs::write(fixture.graph_root.join("Root.md"), lf.as_bytes()).unwrap();
    handle
        .observe_watcher(vec![
            SyncWatcherObservation::managed_path("Root.md").unwrap()
        ])
        .unwrap();
    drain_until_settled(&handle);
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(handle);

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened
        .handle
        .expect("formatting-only manifest state reopens");
    let (page, revision) = load_application_exact(&handle, "Root.md");
    let _ = save_application_block_text(&handle, page, revision, "saved after second formatting");
    drain_managed_local(&handle);
    let second_saved = fs::read(fixture.graph_root.join("Root.md")).unwrap();
    assert!(!second_saved.windows(2).any(|window| window == b"\r\n"));
    assert!(String::from_utf8(second_saved)
        .unwrap()
        .contains("saved after second formatting"));
}

#[test]
fn clean_actor_escalates_a_deterministic_retained_retry_to_a_named_stuck_state() {
    fn find_file(root: &Path, name: &str) -> PathBuf {
        let mut stack = vec![root.to_path_buf()];
        while let Some(dir) = stack.pop() {
            for entry in fs::read_dir(&dir).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    stack.push(path);
                } else if path.file_name().is_some_and(|file| file == name) {
                    return path;
                }
            }
        }
        panic!("{name} is absent under {}", root.display());
    }

    let fixture = ActivationFixture::nested_unicode("clean-actor-stuck", 0xa17b);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let CleanRuntimeResources {
        graph,
        receipts,
        runtime,
        managed_local,
        projection_turns,
        sweeps,
        recovered_provider_batches: _,
    } = resources;
    drop(managed_local);
    let mut projection_turns = projection_turns;
    let mut actor = CleanRuntimeActorCore::new(runtime, sweeps, false);
    let root_path = ManagedPath::parse("Root.md".to_owned()).unwrap();
    let owner = actor
        .runtime
        .database()
        .materialized_read()
        .unwrap()
        .pages_by_path(&root_path, 2)
        .unwrap()
        .pop()
        .expect("clean SQLite names Root.md");
    let current = actor
        .load_current_editor_page(owner.page_id)
        .unwrap()
        .expect("clean actor loads Root.md from SQLite");
    let first = current.blocks.first().expect("Root.md has one block");
    let transaction = OperationTransaction::new(vec![SemanticOperation::EditBlockContent {
        block: BlockLocation {
            block_id: first.block_id,
            home_document_id: first.home_document_id,
        },
        content: "stuck retained save".into(),
    }])
    .unwrap();

    fail_once_at(OperationalFaultPoint::AfterManifest);
    let pending = actor
        .execute_local(&graph, &receipts, &transaction, &mut projection_turns)
        .unwrap();
    let CleanActorMutationOutcome::DurablePending { batch_id, .. } = pending else {
        panic!("fault must retain this submission's own durable work: {pending:?}");
    };

    // Something outside Tine removes the durable manifest, so every retry
    // of the retained continuation fails the same way. Before escalation
    // existed this spun indefinitely, one full coordinator attempt per
    // tick, with the real failure never surfaced.
    let manifest_path = find_file(
        &fixture.request.archive_root,
        &format!("{batch_id}.manifest"),
    );
    let manifest_bytes = fs::read(&manifest_path).unwrap();
    fs::remove_file(&manifest_path).unwrap();

    for attempt in 1..MAX_IDENTICAL_RETAINED_RETRY_ATTEMPTS {
        let retried = actor.retry_pending_with_turns(&graph, &receipts, &mut projection_turns);
        assert!(
            matches!(
                &retried,
                Some(CleanActorMutationOutcome::DurablePending { batch_id: retained, .. })
                    if *retained == batch_id
            ),
            "attempt {attempt} escalated or completed early: {retried:?}"
        );
    }
    let stuck = actor.retry_pending_with_turns(&graph, &receipts, &mut projection_turns);
    let Some(CleanActorMutationOutcome::DurableStuck {
        batch_id: stuck_batch,
        phase,
        detail,
    }) = stuck
    else {
        panic!("identical failures must escalate to a named stuck state: {stuck:?}");
    };
    assert_eq!(stuck_batch, batch_id);
    assert_eq!(phase, OperationalPhase::ArchiveStage);
    assert!(!detail.is_empty());

    // Escalation names the state but never stops the retries: an identical
    // detail string is not proof of determinism, so once the external
    // cause is repaired the very next tick's retry must recover without a
    // restart.
    fs::write(&manifest_path, &manifest_bytes).unwrap();
    let recovered = actor.retry_pending_with_turns(&graph, &receipts, &mut projection_turns);
    assert!(
        matches!(&recovered, Some(CleanActorMutationOutcome::Durable(retained)) if *retained == batch_id),
        "a repaired cause must recover on the next retry: {recovered:?}"
    );
    // Cold-open recovery of a continuation whose Markdown projection is
    // still pending is a separate contract with its own open defect (a
    // resources-level reopen refuses with "managed text writes are
    // reserved for external reconciliation"); it is tracked with the
    // GH #351 follow-ups and deliberately not asserted here.
}

