#[test]
fn cold_replay_error_exit_flushes_completion_before_lease_release() {
    let fixture = ActivationFixture::nested_unicode("local-completion-cold-guard", 0xc2008);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let mut resources =
        activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let page_id = PageId::from_uuid(Uuid::from_u128(0xc2009));
    let path = ManagedPath::parse("Cold replay completion.md").unwrap();
    let transaction = OperationTransaction::new(vec![SemanticOperation::CreatePage {
        page_id,
        home_document_id: DocumentId::from_uuid(Uuid::from_u128(0xc200a)),
        name: LogicalPageName::parse("Cold replay completion").unwrap(),
        path: path.clone(),
        kind: ManagedTextKind::Page,
    }])
    .unwrap();

    fail_once_at(OperationalFaultPoint::BeforeProjection);
    let result = {
        let mut session = resources
            .runtime
            .admit_clean_mutation(&resources.graph)
            .unwrap();
        OperationalCoordinator::execute_clean_local(
            &mut session,
            &resources.graph,
            &resources.receipts,
            &transaction,
            &mut resources.projection_turns,
        )
    };
    assert!(matches!(
        result,
        Ok(crate::oplog::operational_coordinator::CleanLocalMutationState::DurablePending(_))
    ));
    drop(result);
    drop(resources);

    let cut = crate::oplog::projection::cut_turn_replay_after_pages_for_test(1);
    let interrupted = open_clean_runtime_resources(&reopen_request(&fixture.request));
    let cut_was_reached = crate::oplog::projection::turn_replay_cut_was_reached_for_test();
    drop(cut);
    let error = match interrupted {
        Err(error) => error,
        Ok(_) => panic!("cold replay did not stop after executing its page"),
    };
    assert_eq!(
        serde_json::from_str::<serde_json::Value>(&error).unwrap(),
        serde_json::json!({
            "kind": "clean-open",
            "reason_code": "clean_open.projection",
        })
    );
    // The code alone is shared by every projection failure; the cut's counter
    // is what says replay got as far as the injected cut.
    assert!(
        cut_was_reached,
        "cold replay refused before reaching the injected cut"
    );
    assert!(fixture.graph_root.join(path.as_str()).is_file());

    assert_eq!(
        withhold_receipt_completions(&fixture.request.receipt_root),
        0,
        "the cold own-endpoint replay must author no receipt completion"
    );
    fs::remove_file(fixture.graph_root.join(path.as_str())).unwrap();
    let reopened = open_clean_runtime_resources(&reopen_request(&fixture.request))
        .unwrap()
        .expect("the exact cold-replay completion must defer its absent target");
    assert_eq!(reopened.projection_turns.pending_count(), 0);
    assert!(
        !fixture.graph_root.join(path.as_str()).exists(),
        "the scope-guarded completion was not durable before lease release"
    );
    drop(reopened);
}

#[test]
fn an_older_same_path_completion_cannot_defer_a_new_creation_intent() {
    let fixture = ActivationFixture::nested_unicode("local-completion-exact-id", 0xc200d);
    let path = ManagedPath::parse("Reused completion path.md").unwrap();
    let first_page = PageId::from_uuid(Uuid::from_u128(0xc200e));
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    let first = activated.handle.expect("C-2 activation opens");
    drive_initial_feed(&first);
    submit_durable(
        &first,
        vec![SemanticOperation::CreatePage {
            page_id: first_page,
            home_document_id: DocumentId::from_uuid(Uuid::from_u128(0xc200f)),
            name: LogicalPageName::parse("First completion owner").unwrap(),
            path: path.clone(),
            kind: ManagedTextKind::Page,
        }],
    );
    drain_until_settled(&first);
    assert!(matches!(
        first.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let deleting = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
    submit_durable(
        &deleting,
        vec![SemanticOperation::DeletePage {
            page_id: first_page,
        }],
    );
    drain_until_settled(&deleting);
    assert!(!fixture.graph_root.join(path.as_str()).exists());
    assert!(matches!(
        deleting.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let second_page = PageId::from_uuid(Uuid::from_u128(0xc2013));
    let creating = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
    submit_durable(
        &creating,
        vec![SemanticOperation::CreatePage {
            page_id: second_page,
            home_document_id: DocumentId::from_uuid(Uuid::from_u128(0xc2014)),
            name: LogicalPageName::parse("Second completion owner").unwrap(),
            path: path.clone(),
            kind: ManagedTextKind::Page,
        }],
    );
    let ticks = drain_until_settled(&creating);
    assert!(
        fixture.graph_root.join(path.as_str()).is_file(),
        "a path-keyed stale completion deferred a distinct creation intent: {ticks:?}"
    );
    assert!(matches!(
        creating.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn one_quiet_local_completion_flushes_through_the_actor_deadline_tick() {
    let fixture = ActivationFixture::nested_unicode("local-completion-deadline", 0xc2010);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let mut actor = RuntimeActor::from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    )
    .unwrap();
    for _ in 0..128 {
        if matches!(actor.tick(), SyncRuntimeTick::Idle) && !actor.last_watcher.pending {
            break;
        }
    }

    let outcome = actor.submit_local_mutation(
        OperationTransaction::new(vec![SemanticOperation::CreatePage {
            page_id: PageId::from_uuid(Uuid::from_u128(0xc2011)),
            home_document_id: DocumentId::from_uuid(Uuid::from_u128(0xc2012)),
            name: LogicalPageName::parse("One quiet completion").unwrap(),
            path: ManagedPath::parse("One quiet completion.md").unwrap(),
            kind: ManagedTextKind::Page,
        }])
        .unwrap(),
    );
    assert!(matches!(
        outcome,
        SyncLocalMutationOutcome::Durable { .. }
            | SyncLocalMutationOutcome::RetryableRetainedRecovery { .. }
    ));
    for _ in 0..128 {
        if actor
            .managed_local
            .as_ref()
            .is_some_and(|managed| managed.pending_count() == 0)
        {
            break;
        }
        actor.tick();
    }
    let engine = actor.clean.as_ref().unwrap().runtime.engine();
    assert_eq!(engine.local_completion_entry_count_for_test(), 1);
    assert!(engine.has_buffered_local_completions());

    {
        let graph = &actor.graph;
        let clean = actor.clean.as_mut().unwrap();
        let mut session = clean.runtime.admit_clean_mutation(graph).unwrap();
        let (_, engine, _) = session.parts().unwrap();
        engine.age_local_completion_buffer_for_test(
            crate::oplog::local_completion_index::LOCAL_COMPLETION_FLUSH_AFTER,
        );
    }
    assert_eq!(
        actor.local_completion_deadline_remaining(Instant::now()),
        Some(Duration::ZERO)
    );
    assert!(actor.local_completion_flush_due(Instant::now()));
    assert!(actor.flush_local_completions_if_required().unwrap());
    let engine = actor.clean.as_ref().unwrap().runtime.engine();
    assert!(!engine.has_buffered_local_completions());
    assert_eq!(
        engine
            .local_completion_flush_stats_for_test()
            .unwrap()
            .flushes,
        1
    );

    let source = include_str!("sync_runtime.rs");
    let loop_source = source
        .split_once("fn run_actor_loop(")
        .unwrap()
        .1
        .split_once("enum PendingManagedLocalCommit")
        .unwrap()
        .0;
    assert!(
        loop_source
            .find("local_completion_deadline_remaining")
            .unwrap()
            < loop_source.find("receiver.recv_timeout(timeout)").unwrap()
    );
    assert!(loop_source.contains("local_completion_flush_due(Instant::now())"));
}

#[test]
fn the_open_time_recovery_walk_precedes_every_journal_replay() {
    let runtime_source = include_str!("sync_runtime.rs");
    let open = runtime_source
        .split_once("fn open_clean_runtime_resources_with_progress(")
        .unwrap()
        .1
        .split_once("fn open_reconstructible_activation_receipts(")
        .unwrap()
        .0;
    let graph_open = open.find("Graph::open_checked").unwrap();
    let semantic_replay = open.find("drain_open_managed_local_journal").unwrap();
    let projection_replay = open.find("drain_open_projection_turn_journal").unwrap();
    assert!(graph_open < semantic_replay);
    assert!(graph_open < projection_replay);

    let model_source = include_str!("model.rs");
    let checked_open = model_source
        .split_once("pub fn open_checked_with_assets(")
        .unwrap()
        .1
        .split_once("pub(crate) fn has_interrupted_publication_claimant")
        .unwrap()
        .0;
    assert!(
        checked_open
            .find("recover_interrupted_publishes()?")
            .unwrap()
            < checked_open.rfind("Ok(graph)").unwrap(),
        "W4 must complete or fail before checked open can expose a graph"
    );
    let quarantine = model_source
        .split_once("fn quarantine_projection_artifact(")
        .unwrap()
        .1
        .split_once("fn create_editor_staged_recovery(")
        .unwrap()
        .0;
    assert!(
        quarantine
            .find("sync_projection_chain_required(&destination.chain)")
            .unwrap()
            < quarantine
                .find("sync_projection_chain_required(&parent.chain)")
                .unwrap(),
        "quarantine must make its destination name durable before its source removal"
    );

    let drain_source = include_str!("oplog/local_journal_drain.rs");
    let absence = drain_source
        .find("has_interrupted_publication_claimant(intent.path())")
        .unwrap();
    let accept_absence = drain_source[absence..].find("Ok(None) => true").unwrap();
    assert!(
        accept_absence > 0,
        "claimant refusal must precede C-absent acceptance"
    );
}

/// A foreground page save must not depend on the frontend repeatedly
/// resubmitting it to advance an earlier, finite retained continuation.
/// The managed actor owns that continuation and can settle it before
/// admitting the new request.  GH #292 exposed the old one-turn contract:
/// the UI exhausted its two short retries while activation/watcher work
/// was still making progress, then stranded the page as dirty.
#[test]
fn application_save_settles_finite_prior_clean_work_before_admission() {
    let fixture = ActivationFixture::nested_unicode("clean-prior-save", 0xa1782);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("clean actor handle opens");

    handle.install_repeated_projection_fault(2).unwrap();
    let prior = handle
        .submit_local_mutation(
            OperationTransaction::new(vec![SemanticOperation::CreatePage {
                page_id: PageId::from_uuid(Uuid::from_u128(0xa178_2001)),
                home_document_id: DocumentId::from_uuid(Uuid::from_u128(0xa178_2002)),
                name: LogicalPageName::parse("Prior retained page").unwrap(),
                path: ManagedPath::parse("Prior retained page.md").unwrap(),
                kind: ManagedTextKind::Page,
            }])
            .unwrap(),
        )
        .unwrap();
    assert!(matches!(
        prior,
        SyncLocalMutationOutcome::RetryableRetainedRecovery {
            batch_id: Some(_),
            ..
        }
    ));

    let name = "20260823105223";
    let outcome = handle
        .save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::New {
                name: name.into(),
                page_kind: SyncPageKind::Page,
            },
            page: new_application_page(
                name,
                SyncPageKind::Page,
                None,
                vec![BlockDto {
                    raw: "created immediately after managed activation".into(),
                    ..BlockDto::default()
                }],
            ),
        })
        .unwrap();
    let saved_path = match outcome {
        SyncApplicationPageSaveOutcome::Saved { page, .. } => page.path,
        other => {
            panic!("finite prior managed work must settle inside foreground admission: {other:?}")
        }
    };
    let loaded = handle
        .load_application_page(SyncApplicationPageLoadRequest {
            page: SyncApplicationPageSelector::ExactPath {
                path: saved_path.clone(),
            },
        })
        .unwrap();
    assert!(matches!(
        loaded,
        SyncApplicationPageLoadOutcome::Loaded { page, .. }
            if page.blocks.first().is_some_and(|block| {
                block.raw == "created immediately after managed activation"
            })
    ));
    for _ in 0..64 {
        if fixture.graph_root.join(&saved_path).is_file() {
            break;
        }
        let _ = handle.tick().unwrap();
    }
    assert!(fixture.graph_root.join(saved_path).is_file());
}

/// Android's shared storage does not uniformly provide the directory flush
/// primitive and reports the refusal as `EINVAL`. The Markdown projection
/// is reconstructible from the already-durable manifest, so that refusal
/// must degrade and the user's edit must reach the graph. Anything else
/// retries forever and strands the save — which is exactly what Android CI
/// run 32088229039 observed (`phase:ProjectionDrain`,
/// `detail:Invalid argument (os error 22)`, `settled:false`, 64 turns).
#[test]
fn clean_runtime_save_survives_an_android_projection_directory_barrier_refusal() {
    let fixture = ActivationFixture::nested_unicode("clean-android-einval", 0xa1783);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("clean actor handle opens");

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let mut edited = page.clone();
    edited.blocks[0].raw = "android shared storage barrier refusal".into();

    let _refusal = crate::model::InjectedProjectionDirectoryBarrierFailure::enter(
        crate::filesystem_durability::DurabilityArtifactClass::SharedReconstructibleProjection,
        libc::EINVAL,
        true,
        &fixture.graph_root,
    )
    .unwrap();
    let outcome = handle.save_application_page(SyncApplicationPageSaveRequest {
        target: SyncApplicationPageSaveTarget::Existing {
            path: page.path.clone(),
            revision,
        },
        page: edited,
    });
    assert!(
            matches!(outcome, Ok(SyncApplicationPageSaveOutcome::Saved { .. })),
            "a projection directory barrier Android cannot provide must not strand the save: {outcome:?}"
        );
    assert!(fs::read_to_string(fixture.graph_root.join("Root.md"))
        .unwrap()
        .contains("android shared storage barrier refusal"));
}

/// The same errno off Android remains a real projection failure. The
/// journaled edit is already durable, but the application response defers
/// while the visible Markdown projection stays pending and names the
/// failed end-of-turn barrier rather than pretending it reached disk. The
/// collapsed-barrier protocol permits the publication rename to be visible
/// before that one barrier refuses; replay still owns it until the barrier
/// succeeds.
#[test]
fn a_projection_directory_barrier_refusal_stays_pending_off_android() {
    let fixture = ActivationFixture::nested_unicode("clean-desktop-einval", 0xa1784);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("clean actor handle opens");

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let mut edited = page.clone();
    edited.blocks[0].raw = "desktop barrier refusal is fatal".into();

    let _refusal = crate::model::InjectedProjectionDirectoryBarrierFailure::enter(
        crate::filesystem_durability::DurabilityArtifactClass::SharedReconstructibleProjection,
        libc::EINVAL,
        false,
        &fixture.graph_root,
    )
    .unwrap();
    let outcome = handle
        .save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::Existing {
                path: page.path.clone(),
                revision,
            },
            page: edited,
        })
        .expect("the durable journal append is acknowledged");
    assert!(
        matches!(
            outcome,
            SyncApplicationPageSaveOutcome::Deferred {
                state: SyncEditorDeferred::BlockedRecovery { .. }
            }
        ),
        "the accepted journal edit must defer while projection is pending: {outcome:?}"
    );
    assert!(fs::read_to_string(fixture.graph_root.join("Root.md"))
        .unwrap()
        .contains("desktop barrier refusal is fatal"));

    let status = handle.status().unwrap();
    assert_eq!(status.managed_local_pending, 1);
    let detail = status
        .detail
        .expect("the pending projection names its failure");
    assert!(
        detail.contains("fsync of the projection parent directory") && detail.contains("Root.md"),
        "the pending failure must name the operation and the page: {detail}"
    );
}

/// Android CI run 32091898520, one layer below the barrier fix: the flagged
/// rename ITSELF is unsupported on shared storage —
/// `renameat2(RENAME_NOREPLACE) publishing the projection failed at
/// "Smoke.md" -> ".Smoke.md.49a4ed18…"`, `Invalid argument (os error 22)`.
/// Two earlier lanes eliminated this call by reading AOSP `FuseDaemon.cpp`;
/// the device disagreed. The publication must complete through the
/// capability fallback, and the displaced bytes must still be retained by
/// the same displacement mechanism as an unrefused save.
#[test]
fn clean_runtime_save_survives_a_projection_rename_capability_refusal() {
    for errno in [libc::EINVAL, libc::ENOSYS] {
        let fixture =
            ActivationFixture::nested_unicode("clean-rename-capability", 0xa1785 + errno as u128);
        let graph = Graph::open_checked(&fixture.graph_root).unwrap();
        let resources =
            activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
        let open_request = reopen_request(&fixture.request);
        let identities = open_request.clean_identities.clone().unwrap();
        let opened = SyncRuntimeHandle::open_from_clean_resources(
            open_request,
            identities,
            resources,
            SyncRuntimeRecovery::CleanActivation,
        );
        let handle = opened.handle.expect("clean actor handle opens");
        let (page, revision) = load_application_exact(&handle, "Root.md");
        let mut edited = page.clone();
        edited.blocks[0].raw = "shared storage cannot flag a rename".into();
        let _refusal = crate::model::InjectedProjectionNoreplaceRenameFailure::enter(
            crate::filesystem_durability::DurabilityArtifactClass::SharedReconstructibleProjection,
            errno,
            &fixture.graph_root,
        )
        .unwrap();
        let outcome = handle.save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::Existing {
                path: page.path.clone(),
                revision,
            },
            page: edited,
        });
        assert!(
            matches!(outcome, Ok(SyncApplicationPageSaveOutcome::Saved { .. })),
            "a rename flag the filesystem cannot provide must not strand the save \
                 (errno {errno}): {outcome:?}"
        );

        assert!(
            fs::read_to_string(fixture.graph_root.join("Root.md"))
                .unwrap()
                .contains("shared storage cannot flag a rename"),
            "the reconstructible projection must reach the graph (errno {errno})"
        );
        drain_managed_local(&handle);
        assert_eq!(handle.status().unwrap().managed_local_pending, 0);
    }
}

/// `EIO` is not a filesystem capability answer. The accepted journal edit
/// remains durable but deferred, while the projection stays pending and
/// reports the real I/O failure instead of taking the capability fallback.
#[test]
fn a_non_capability_errno_from_the_projection_rename_stays_pending() {
    let fixture = ActivationFixture::nested_unicode("clean-rename-fatal", 0xa1787);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("clean actor handle opens");

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let mut edited = page.clone();
    edited.blocks[0].raw = "a disk error is not a capability answer".into();

    let _refusal = crate::model::InjectedProjectionNoreplaceRenameFailure::enter(
        crate::filesystem_durability::DurabilityArtifactClass::SharedReconstructibleProjection,
        libc::EIO,
        &fixture.graph_root,
    )
    .unwrap();
    let outcome = handle
        .save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::Existing {
                path: page.path.clone(),
                revision,
            },
            page: edited,
        })
        .expect("the durable journal append is acknowledged");
    assert!(
        matches!(
            outcome,
            SyncApplicationPageSaveOutcome::Deferred {
                state: SyncEditorDeferred::BlockedRecovery { .. }
            }
        ),
        "the accepted journal edit must defer while projection is pending: {outcome:?}"
    );
    assert!(!fs::read_to_string(fixture.graph_root.join("Root.md"))
        .unwrap()
        .contains("a disk error is not a capability answer"));

    let status = handle.status().unwrap();
    assert_eq!(status.managed_local_pending, 1);
    let detail = status
        .detail
        .expect("the pending projection names its failure");
    assert!(
        detail.contains("renameat2(RENAME_NOREPLACE) publishing the projection")
            && detail.contains("Root.md"),
        "the pending failure must name the primitive and the page: {detail}"
    );
}

