#[test]
fn cold_acknowledgement_cleanup_tolerates_stale_directory_entries() {
    let fixture = ActivationFixture::nested_unicode("move-stale-cold-entry", 0xa17713);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request.clone(),
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("stale-entry source actor opens");
    let request = simple_application_move_request(&handle, "Stale Cold Entry");
    let episode_id = match accepted_application_move(&handle, &request) {
        SyncApplicationMoveSubtreesOutcome::Committed { episode_id, .. } => episode_id,
        other => panic!("stale-entry move did not commit: {other:?}"),
    };
    let episode = Uuid::parse_str(&episode_id).unwrap();
    let directory = fixture
        .request
        .application_runtime_root
        .join("move-episodes");
    let record_name = format!("episode-{}.bin", episode.simple());
    let completion_name = format!("episode-{}.complete", episode.simple());
    let record: ApplicationMoveEpisodeRecord =
        postcard::from_bytes(&fs::read(directory.join(&record_name)).unwrap()).unwrap();
    drop(handle);

    let resources = open_clean_runtime_resources(&open_request)
        .unwrap()
        .expect("stale-entry runtime resources reopen");
    let identities = open_request.clean_identities.clone().unwrap();
    let mut actor = RuntimeActor::from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanManifestReplay,
    )
    .unwrap();
    let acknowledgement = ApplicationMoveEpisodeAcknowledgement::from_record(&record);
    let acknowledgement_name = acknowledgement.filename();
    fs::write(
        directory.join(&acknowledgement_name),
        acknowledgement.encode().unwrap(),
    )
    .unwrap();

    assert!(actor
        .cleanup_move_episode_acknowledgement(&acknowledgement_name)
        .unwrap());
    assert!(
        !actor
            .cleanup_cold_move_episode_entry(&completion_name)
            .unwrap(),
        "a ReadDir entry buffered before acknowledgement cleanup may be stale"
    );
    assert!(!directory.join(record_name).exists());
    assert!(!directory.join(completion_name).exists());
    assert!(!directory.join(acknowledgement_name).exists());
}

#[test]
fn live_acknowledgement_queue_saturation_drains_before_marker_publication() {
    let fixture = ActivationFixture::nested_unicode("move-ack-queue-saturation", 0xa17715);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request.clone(),
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("saturation source actor opens");
    let request = simple_application_move_request(&handle, "Saturated Ack Queue");
    let (episode_id, batch_id) = match accepted_application_move(&handle, &request) {
        SyncApplicationMoveSubtreesOutcome::Committed {
            episode_id,
            batch_id,
            ..
        } => (episode_id, batch_id),
        other => panic!("saturation move did not commit: {other:?}"),
    };
    drop(handle);

    let resources = open_clean_runtime_resources(&open_request)
        .unwrap()
        .expect("saturation runtime resources reopen");
    let identities = open_request.clean_identities.clone().unwrap();
    let mut actor = RuntimeActor::from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanManifestReplay,
    )
    .unwrap();
    for _ in 0..MOVE_EPISODE_CLEANUP_QUEUE_LIMIT {
        let acknowledgement = ApplicationMoveEpisodeAcknowledgement {
            workspace_id: actor.binding.workspace_id(),
            lineage_digest: actor.binding.lineage_digest(),
            episode_id: Uuid::new_v4(),
            batch_id: BatchId::new(),
        };
        let name = acknowledgement.filename();
        fs::write(
            fixture
                .request
                .application_runtime_root
                .join("move-episodes")
                .join(&name),
            acknowledgement.encode().unwrap(),
        )
        .unwrap();
        actor.move_episode_cleanup_queue.push_back(name);
    }
    actor.move_episode_cleanup_pending = true;

    actor
        .acknowledge_application_move(
            Uuid::parse_str(&episode_id).unwrap(),
            batch_id.parse::<BatchId>().unwrap(),
        )
        .expect("the 257th acknowledgement makes bounded room before publication");
    assert!(actor.move_episode_cleanup_queue.len() <= MOVE_EPISODE_CLEANUP_QUEUE_LIMIT);
    for _ in 0..16 {
        if !actor.move_episode_cleanup_pending {
            break;
        }
        actor.cleanup_acknowledged_move_episodes().unwrap();
    }
    assert!(!actor.move_episode_cleanup_pending);
    let acknowledged = fs::read_dir(
        fixture
            .request
            .application_runtime_root
            .join("move-episodes"),
    )
    .unwrap()
    .filter_map(Result::ok)
    .filter(|entry| {
        entry
            .file_name()
            .to_string_lossy()
            .ends_with(".acknowledged")
    })
    .count();
    assert_eq!(acknowledged, 0);
    assert!(matches!(
        actor.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn cold_move_cleanup_cursor_stays_runnable_and_bounded_across_turns() {
    let fixture = ActivationFixture::nested_unicode("move-cold-bounded-cursor", 0xa17714);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    let handle = activated.handle.expect("bounded cursor fixture activates");
    let directory = fixture
        .request
        .application_runtime_root
        .join("move-episodes");
    drop(handle);

    for index in 0..(MOVE_EPISODE_SCAN_ENTRIES_PER_TURN * 2 + 7) {
        fs::write(
            directory.join(format!("unrelated-{index:04}.keep")),
            b"ignored",
        )
        .unwrap();
    }

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    let reopened = reopened.handle.expect("bounded cursor actor reopens");
    let initial = reopened.status().unwrap();
    assert!(initial.move_episode_cleanup_pending);
    assert!(initial.has_runnable_work());

    let mut turns = 0;
    while reopened.status().unwrap().move_episode_cleanup_pending && turns < 4 {
        reopened.tick().unwrap();
        turns += 1;
    }
    let settled = reopened.status().unwrap();
    assert!(
        !settled.move_episode_cleanup_pending,
        "the retained directory cursor must finish within its bounded turns: {settled:?}"
    );
    assert!(
        turns >= 1 && turns <= 3,
        "unexpected cleanup turn count: {turns}"
    );
    drop(reopened);
}

#[test]
fn foreground_cross_page_move_crash_reopens_from_the_local_journal() {
    let fixture = ActivationFixture::nested_unicode("foreground-move-crash-reopen", 0xa17711);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request.clone(),
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("foreground move actor opens");
    let request = simple_application_move_request(&handle, "Foreground Crash Move");
    assert!(matches!(
        handle.move_application_subtrees(request.clone()).unwrap(),
        SyncApplicationMoveSubtreesOutcome::Committed {
            recovered: false,
            ..
        }
    ));
    assert_eq!(handle.status().unwrap().managed_local_pending, 1);

    // Simulate force-close before archive, SQLite, or Markdown projection
    // drains. The local journal is already the commit boundary.
    drop(handle);
    let reopened = SyncRuntimeHandle::open(open_request);
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened.handle.expect("foreground move crash-reopens");
    match handle
        .resolve_application_move_subtrees(request)
        .unwrap()
        .move_outcome
    {
        SyncApplicationMoveSubtreesOutcome::Committed {
            recovered: true,
            source,
            destination,
            ..
        } => {
            assert!(source.page.blocks.is_empty());
            assert_eq!(destination.page.blocks.len(), 2);
        }
        other => panic!("journal-recovered move was not visible: {other:?}"),
    }
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn foreground_cross_page_move_is_bounded_and_does_no_graph_wide_work() {
    let fixture = ActivationFixture::nested_unicode("foreground-move-bounded", 0xa17712);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("bounded move fixture activates");
    drive_initial_feed(&handle);
    let request = simple_application_move_request(&handle, "Bounded Foreground Move");
    let before = handle
        .managed_application_save_instrumentation()
        .expect("bounded move reads foreground counters");
    let started = Instant::now();
    assert!(matches!(
        handle.move_application_subtrees(request).unwrap(),
        SyncApplicationMoveSubtreesOutcome::Committed {
            recovered: false,
            ..
        }
    ));
    let caller = started.elapsed();
    let after = handle
        .managed_application_save_instrumentation()
        .expect("bounded move reads post-commit counters");
    assert!(after.forbidden.since(before.forbidden).is_none());
    assert_eq!(
        after.graph_wide.since(before.graph_wide),
        GraphWideCommitWork::default()
    );
    assert!(
        after.local_mutation_detail.move_page_home_hint_hits >= 2,
        "foreground compound move must use its authenticated page-home hints: {:?}",
        after.local_mutation_detail
    );
    assert_eq!(
        after.local_mutation_detail.move_page_home_hot_catalog_hits, 0,
        "foreground compound move must not clone the catalog to resolve page homes"
    );
    let stages = after.move_stages;
    eprintln!(
            "foreground_cross_page_move caller={caller:?} stages={stages:?} preparation={:?} mutation={:?}",
            after.preparation_stages,
            after.local_mutation_detail
        );
    assert!(
        stages.foreground_total <= caller,
        "{stages:?} caller={caller:?}"
    );
    let accounted = stages.preparation
        + stages.episode_publication
        + stages.journal_and_hot_overlay
        + stages.queue_and_response;
    assert!(
        accounted <= stages.foreground_total,
        "foreground stage accounting exceeds total: {stages:?}"
    );
    assert_eq!(
        after.managed_local_pending,
        before.managed_local_pending + 1
    );
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn managed_rename_uses_the_canonical_fold_for_final_sigma_names() {
    // "ΟΔΥΣΣΕΥΣ" is a name where refs::page_key ("οδυσσευς", contextual
    // final sigma) and the managed canonical fold ("οδυσσευσ", char-wise)
    // disagree. Pre-DUP-1 the rename planner keyed the canonical-keyed
    // navigation index with the refs fold, selected nothing, and reported
    // Applied while renaming nothing — a silent no-op.
    let fixture = ActivationFixture::nested_unicode("rename-final-sigma", 0xa1773);
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("clean actor handle opens");

    accepted_new_application_page(
        &handle,
        "ΟΔΥΣΣΕΥΣ",
        vec![BlockDto {
            id: "sigma-block".into(),
            raw: "sigma body".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    assert_eq!(
        handle
            .mutate_application_graph(SyncApplicationGraphMutationRequest::RenamePage {
                old: "ΟΔΥΣΣΕΥΣ".into(),
                new: "Odysseus".into(),
                expected_path: None,
            })
            .unwrap(),
        SyncApplicationUnitOutcome::Applied
    );
    drain_managed_local(&handle);
    let (renamed, _) = load_application_logical(&handle, "Odysseus", SyncPageKind::Page);
    assert_eq!(renamed.blocks[0].raw, "sigma body");
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn clean_runtime_serves_regime_neutral_graph_pdf_and_guide_journeys() {
    let fixture = ActivationFixture::nested_unicode("clean-runtime-app-journeys", 0xa1772);
    fs::create_dir_all(fixture.graph_root.join("assets")).unwrap();
    fs::write(
        fixture.graph_root.join("assets/paper.pdf"),
        b"test pdf bytes",
    )
    .unwrap();
    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let resources = activate_clean_runtime_resources(&fixture.request, graph, &mut |_| {}).unwrap();
    let open_request = reopen_request(&fixture.request);
    let identities = open_request.clean_identities.clone().unwrap();
    let opened = SyncRuntimeHandle::open_from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanActivation,
    );
    let handle = opened.handle.expect("clean actor handle opens");

    let (renamed, _) = accepted_new_application_page(
        &handle,
        "Clean Rename Source",
        vec![BlockDto {
            id: "temporary-rename".into(),
            raw: "rename body".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    accepted_new_application_page(
        &handle,
        "Clean Rename Source/Child",
        vec![BlockDto {
            id: "temporary-rename-child".into(),
            raw: "rename child body".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    assert_eq!(
        handle
            .mutate_application_graph(SyncApplicationGraphMutationRequest::RenamePage {
                old: "Clean Rename Source".into(),
                new: "Clean Rename Target".into(),
                expected_path: Some(renamed.path),
            })
            .unwrap(),
        SyncApplicationUnitOutcome::Applied
    );
    drain_managed_local(&handle);
    let (renamed, _) = load_application_logical(&handle, "Clean Rename Target", SyncPageKind::Page);
    assert_eq!(renamed.blocks[0].raw, "rename body");
    let (renamed_child, _) =
        load_application_logical(&handle, "Clean Rename Target/Child", SyncPageKind::Page);
    assert_eq!(renamed_child.blocks[0].raw, "rename child body");

    let (source, _) = accepted_new_application_page(
        &handle,
        "Clean Merge Source",
        vec![BlockDto {
            id: "temporary-merge-source".into(),
            raw: "source sees [[Clean Merge Source]]".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    let (destination, _) = accepted_new_application_page(
        &handle,
        "Clean Merge Destination",
        vec![BlockDto {
            id: "temporary-merge-destination".into(),
            raw: "destination body".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    accepted_new_application_page(
        &handle,
        "Clean Merge Source/Child",
        vec![BlockDto {
            id: "temporary-merge-child".into(),
            raw: "merge child body".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    assert_eq!(
        handle
            .mutate_application_graph(SyncApplicationGraphMutationRequest::MergePages {
                source_path: source.path,
                destination_path: destination.path,
                rename_from: Some("Clean Merge Source".into()),
                rename_to: Some("Clean Merge Destination".into()),
            })
            .unwrap(),
        SyncApplicationUnitOutcome::Applied
    );
    drain_managed_local(&handle);
    let (merged, _) =
        load_application_logical(&handle, "Clean Merge Destination", SyncPageKind::Page);
    assert_eq!(merged.blocks.len(), 2);
    assert!(merged.blocks[1].raw.contains("[[Clean Merge Destination]]"));
    let (merged_child, _) =
        load_application_logical(&handle, "Clean Merge Destination/Child", SyncPageKind::Page);
    assert_eq!(merged_child.blocks[0].raw, "merge child body");

    let (stray, _) = accepted_new_application_page(
        &handle,
        "Clean Stray",
        vec![BlockDto {
            id: "temporary-stray".into(),
            raw: "rescue body".into(),
            ..BlockDto::default()
        }],
    );
    drain_managed_local(&handle);
    assert_eq!(
        handle
            .mutate_application_graph(SyncApplicationGraphMutationRequest::RenameFileToPage {
                path: stray.path,
                new_name: "Clean Rescued".into(),
            })
            .unwrap(),
        SyncApplicationUnitOutcome::Applied
    );
    drain_managed_local(&handle);
    let (rescued, _) = load_application_logical(&handle, "Clean Rescued", SyncPageKind::Page);
    assert_eq!(rescued.blocks[0].raw, "rescue body");
    assert_eq!(
        handle
            .mutate_application_graph(SyncApplicationGraphMutationRequest::DeletePage {
                name: "Clean Rescued".into(),
                page_kind: SyncPageKind::Page,
                expected_path: Some(rescued.path),
            })
            .unwrap(),
        SyncApplicationUnitOutcome::Applied
    );
    drain_managed_local(&handle);

    assert!(matches!(
        handle
            .open_application_pdf("paper.pdf".into(), "Paper".into())
            .unwrap(),
        SyncApplicationPdfOpenOutcome::Ready { .. }
    ));
    assert!(
        relative_files(&fixture.graph_root)
            .iter()
            .all(|path| !path.contains("hls__")),
        "opening a PDF must not create an empty semantic annotation page"
    );
    assert_eq!(
        handle
            .write_application_pdf_highlights(
                "paper.pdf".into(),
                "Paper".into(),
                Vec::new(),
                Vec::new(),
            )
            .unwrap(),
        SyncApplicationUnitOutcome::Applied
    );
    drain_managed_local(&handle);
    let hls_name = crate::pdf::hls_page_name(&crate::pdf::asset_key("paper.pdf"));
    let (hls, _) = load_application_logical(&handle, &hls_name, SyncPageKind::Page);
    assert!(hls
        .pre_block
        .as_deref()
        .is_some_and(|preamble| preamble.contains("../assets/paper.pdf")));

    let SyncApplicationGuideCopyOutcome::Copied { result } = handle
        .copy_application_guide("Features/Sheets".into())
        .unwrap()
    else {
        panic!("clean guide copy unexpectedly deferred")
    };
    assert!(result.created);
    assert!(result.created_pages.len() > 5);
    let pending_before_tick = handle.status().unwrap().managed_local_pending;
    assert!(pending_before_tick >= result.created_pages.len());
    let mut last_tick = None;
    for _ in 0..64 {
        last_tick = Some(handle.tick().unwrap());
        if handle.status().unwrap().managed_local_pending < pending_before_tick {
            break;
        }
    }
    assert!(
        handle.status().unwrap().managed_local_pending < pending_before_tick,
        "guide foreground prefix did not advance: status={:?}, last_tick={last_tick:?}",
        handle.status().unwrap()
    );
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

