#[test]
fn public_clean_activation_loads_saves_and_cold_reopens_an_editor_page() {
    const SAVED_CONTENT: &str = "saved through the clean public actor";
    let fixture = ActivationFixture::nested_unicode("clean-public-editor", 0xa17a);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("clean activation opens actor");
    let pages = handle
        .query(SyncRuntimeQueryRequest::ListPages {
            page_kind: Some(SyncPageKind::Page),
            limit: 32,
        })
        .unwrap();
    let SyncRuntimeQueryReply::Pages(pages) = pages else {
        panic!("clean page listing returned the wrong reply");
    };
    let page_id = pages
        .into_iter()
        .find(|page| page.path == "Root.md")
        .expect("clean SQLite projection contains Root.md")
        .page_id;
    let mut page = match handle
        .load_editor_page(SyncEditorLoadRequest {
            page: SyncEditorPageSelector::PageId {
                page_id: page_id.clone(),
            },
        })
        .unwrap()
    {
        SyncEditorLoadOutcome::Loaded { page } => page,
        other => panic!("clean editor page did not load: {other:?}"),
    };
    page.blocks[0].content = SAVED_CONTENT.into();
    let saved = handle
        .save_editor_page(SyncEditorSaveRequest {
            target: SyncEditorSaveTarget::Existing {
                page_id: page.page_id,
                revision: page.revision,
            },
            preamble: page.preamble,
            blocks: page.blocks,
        })
        .unwrap();
    assert!(matches!(saved, SyncEditorSaveOutcome::Durable { .. }));
    assert!(fs::read_to_string(fixture.graph_root.join("Root.md"))
        .unwrap()
        .contains(SAVED_CONTENT));
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let reopened = reopened.handle.expect("clean runtime cold-reopens");
    assert_eq!(
        reopened.status().unwrap().recovery,
        Some(SyncRuntimeRecovery::CleanManifestReplay)
    );
    let page = match reopened
        .load_editor_page(SyncEditorLoadRequest {
            page: SyncEditorPageSelector::PageId { page_id },
        })
        .unwrap()
    {
        SyncEditorLoadOutcome::Loaded { page } => page,
        other => panic!("saved clean editor page did not reopen: {other:?}"),
    };
    assert_eq!(page.blocks[0].content, SAVED_CONTENT);
    assert!(matches!(
        reopened.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// The Android instrumentation journey (`android_managed_storage_smoke.rs`)
/// drives this exact call sequence and request shape against a graph on
/// Android shared storage.  It has been failing there with an
/// information-free `Err(ActorRefused)` since the journey first performed a
/// post-activation save.  This host test pins the same sequence so the
/// Linux/host boundary stays green and any future host-visible regression
/// in it is caught here rather than only on an emulator.
/// The exact request pair `src-tauri/src/android_managed_storage_smoke.rs`
/// builds, on a host graph.  Every journey-shape test drives it, so the
/// host and Android call sequences can only diverge deliberately.
fn android_instrumentation_journey_fixture(
    name: &str,
) -> (PathBuf, SyncRuntimeOpenRequest, SyncLocalActivationRequest) {
    android_instrumentation_journey_fixture_with(name, true)
}

fn android_instrumentation_journey_fixture_with(
    name: &str,
    write_journey_graph: bool,
) -> (PathBuf, SyncRuntimeOpenRequest, SyncLocalActivationRequest) {
    let root = std::env::temp_dir().join(format!("tine-android-{name}-{}", Uuid::new_v4()));
    let graph_root = root.join("graph");
    let private_root = root.join("private");
    // The instrumentation and this host test share ONE fixture, so the two
    // boundaries cannot drift apart the way they had (the device hit a
    // reconciliation refusal on real-graph name shapes while the journey
    // was green on a single ASCII page).
    if write_journey_graph {
        crate::managed_storage_journey::write_journey_graph_fixture(&graph_root).unwrap();
    }

    let identities = SyncLocalActivationIdentities {
        workspace_id: WorkspaceId::new(),
        lineage_digest: LineageDigest::of(Uuid::new_v4().as_bytes()),
        catalog_document_id: DocumentId::new(),
        endpoint_id: ProjectionEndpointId::new(),
        device_id: DeviceId::new(),
        preparation_id: Uuid::new_v4(),
        session_id: SessionId::new(),
    };
    let open_request = SyncRuntimeOpenRequest {
        profile: SyncStorageProfile::ExperimentalLocal,
        clean_identities: Some(identities.clone()),
        graph_root: graph_root.clone(),
        archive_root: private_root.join("archive"),
        enrollment_root: private_root.join("enrollment"),
        receipt_root: private_root.join("receipts"),
        database_path: private_root.join("projection/materialization.sqlite"),
        application_runtime_root: private_root.join("runtime"),
        provider_root: graph_root.join(".tine-sync/v2/shared"),
        provider_journal_root: private_root.join("provider/device/journal"),
    };
    let activation_request = SyncLocalActivationRequest {
        graph_root: graph_root.clone(),
        archive_root: open_request.archive_root.clone(),
        enrollment_root: open_request.enrollment_root.clone(),
        receipt_root: open_request.receipt_root.clone(),
        database_path: open_request.database_path.clone(),
        application_runtime_root: open_request.application_runtime_root.clone(),
        capture_root: private_root.join("capture"),
        preparation_root: private_root.join("preparation"),
        provider_root: open_request.provider_root.clone(),
        provider_journal_root: open_request.provider_journal_root.clone(),
        identities,
    };
    (graph_root, open_request, activation_request)
}

/// A first local activation writes NOTHING into the graph's `.tine-sync/`.
///
/// Two comments in the Tauri shell claimed the opposite — that activation
/// creates the provider directory skeleton — and the "Return to Direct
/// files" escape hatch reasons from that claim. It is false: the skeleton
/// is written by the SHARED TRANSPORT, on prepare/join/shared-reopen. This
/// pins the real behaviour so the premise cannot come back, and it is the
/// product property too: managed storage is write-shy about the graph
/// folder until the user asks to share it.
#[test]
fn local_activation_writes_nothing_into_the_graphs_sync_folder() {
    let (graph_root, _open_request, activation_request) =
        android_instrumentation_journey_fixture("activation-write-shyness");
    let activation = SyncRuntimeHandle::activate_or_resume_local(activation_request);
    assert_eq!(activation.status, SyncLocalActivationStatus::Active);
    let handle = activation.handle.expect("activated");
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(handle);

    assert!(
        !graph_root.join(".tine-sync").exists(),
        "activation alone must not create anything under the graph's .tine-sync"
    );
}

/// The initiator must put back the one file another device joins by.
///
/// A file-sync tool can remove `outbox/enrollment/shared-enrollment-v1.json`
/// while Tine is running — propagating a peer's deletion, or mid-delete.
/// Before this, the exact callback for the now-absent path refused
/// ("clean provider evidence disappeared at …") and, because the entry is
/// only popped on success, produced that same blocked tick on every retry
/// while the share stayed unadvertised and the second device kept reading
/// "does not yet contain sync data from another device".
#[test]
fn the_initiator_republishes_a_descriptor_something_else_removed() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture("descriptor-repair");
    let activation = SyncRuntimeHandle::activate_or_resume_local(activation_request);
    assert_eq!(activation.status, SyncLocalActivationStatus::Active);
    let handle = activation.handle.expect("activated");
    handle.prepare_shared().expect("share prepared");
    drop(handle);

    let descriptor_path = graph_root
        .join(".tine-sync/v2/shared/outbox")
        .join(SHARED_ENROLLMENT_DESCRIPTOR_PATH);
    assert!(descriptor_path.exists(), "preparation published it");
    let original_descriptor = fs::read(&descriptor_path).unwrap();

    let reopened = SyncRuntimeHandle::open(open_request);
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened.handle.expect("reopened");
    assert_eq!(
        handle.status().unwrap().shared_phase,
        Some(SyncSharedPhase::Active)
    );
    // Let the ordinary reopen repair finish first, so what this test
    // observes afterwards is the running-actor path and not that one.
    drain_ticks(&handle);
    assert!(descriptor_path.exists());

    for round in 1..=MAX_PROVIDER_DESCRIPTOR_REPUBLICATIONS {
        fs::remove_file(&descriptor_path).unwrap();
        handle
            .observe_provider_paths(vec![SHARED_ENROLLMENT_DESCRIPTOR_PATH.into()], false)
            .unwrap();
        let ticks = drain_ticks(&handle);
        assert!(
            descriptor_path.exists(),
            "round {round}: the initiator did not put its descriptor back: {ticks:?}"
        );
        assert!(
            !ticks.iter().any(|tick| matches!(
                tick,
                SyncRuntimeTick::RecoveryBlocked(_) | SyncRuntimeTick::Blocked(_)
            )),
            "round {round}: repairing must not block: {ticks:?}"
        );
        // Byte-exact: a republished descriptor is the SAME enrollment, so
        // a device that already joined is still joined to it.
        assert_eq!(
            fs::read(&descriptor_path).unwrap(),
            original_descriptor,
            "round {round}: the republished descriptor is not the enrolled one"
        );
    }

    // Something that keeps removing the file is not a delivery window. The
    // actor stops writing around it and names the condition once.
    fs::remove_file(&descriptor_path).unwrap();
    handle
        .observe_provider_paths(vec![SHARED_ENROLLMENT_DESCRIPTOR_PATH.into()], false)
        .unwrap();
    let ticks = drain_ticks(&handle);
    let blocked = ticks
        .iter()
        .filter_map(|tick| match tick {
            SyncRuntimeTick::RecoveryBlocked(detail) => Some(detail.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(blocked.len(), 1, "one condition, one report: {ticks:?}");
    assert!(
        blocked[0].contains("shared-enrollment-v1.json") && blocked[0].contains(".tine-sync"),
        "the report must name the file it wants: {}",
        blocked[0]
    );
    let _ = handle.clean_shutdown();
}

/// Tick until the actor stops making progress, returning what it reported.
fn drain_ticks(handle: &SyncRuntimeHandle) -> Vec<SyncRuntimeTick> {
    let mut ticks = Vec::new();
    for _ in 0..64 {
        let tick = handle.tick().expect("actor available");
        let done = matches!(tick, SyncRuntimeTick::Idle);
        ticks.push(tick);
        if done {
            break;
        }
    }
    ticks
}

/// The complete Android instrumentation journey, run at the HOST boundary.
///
/// This is the same code `ManagedStorageSmokeTest` invokes over JNI — same
/// fixture, same call sequence — so a defect that would fail on the device
/// fails here first, without an emulator. What it therefore does NOT prove:
/// the Android UID, Android shared storage, SAF, or anything above the
/// native runtime (no WebView, no Tauri commands, no watcher thread, no
/// UI). It is also one fixture of a few dozen pages: a name-shape gate, not
/// a corpus-scale gate.
///
/// It exists because the device-side journey was GREEN on CI in the same
/// round Martin's physical Android flooded the app with
/// `clean external reconciliation failed during Planning: decoded
/// destination logical page name … is already owned by page <uuid>`. The
/// journey never drove an external change through reconciliation planning,
/// and its fixture was one ASCII page — so the failing leg and the failing
/// shapes were both outside it (GH: Android, 2026-08-18).
#[test]
fn android_managed_storage_journey_reconciles_real_graph_name_shapes_on_a_host_graph() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture("full-journey");
    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root.clone(),
        open_request,
        activation_request,
    );
    assert!(
        receipt.starts_with("ok "),
        "the managed-storage journey must survive real-graph page-name shapes and an \
             external reconciliation: {receipt}"
    );
    // Every physical file the journey deliberately does not import is still
    // exactly where the user left it.
    for (path, bytes) in [
        (
            "pages/Z\u{30c} pilot notes #pilot.md",
            "- decomposed pilot notes\n",
        ),
        (
            "pages/\u{17d} pilot notes %23pilot.md",
            "- encoded pilot notes\n",
        ),
        (
            crate::managed_storage_journey::JOURNEY_CASE_TWIN_PAGE,
            // The journey's external leg now rewrites this file after
            // activation, so the byte assertion is about write-shyness on
            // the OUTSIDE writer's bytes rather than on the fixture's.
            crate::managed_storage_journey::JOURNEY_CASE_TWIN_AFTER,
        ),
        ("archiv/2026/Denn\u{ed} pozn\u{e1}mky.md", "- backup copy\n"),
    ] {
        assert_eq!(
            fs::read_to_string(graph_root.join(path)).unwrap(),
            bytes,
            "{path} was rewritten or removed"
        );
    }
    // The host filesystem holds every spelling apart, and the receipt has
    // to say so: a device receipt is read against this one, and "the
    // journey passed" means different things on the two filesystem classes.
    assert!(
        receipt.contains("graph_name_folding=none"),
        "the receipt must state what the graph filesystem folds: {receipt}"
    );
}

/// What "enable sync with another device" actually leaves on disk.
///
/// Martin's desktop repeated `RecoveryBlocked("unsafe provider entry:
/// enrollment: No such file or directory (os error 2)")` after preparing a
/// share, which reads as a preparation that published a half-built tree.
/// It does not: the transport creates every namespace in both trees before
/// it writes a byte, and preparation then publishes the descriptor into the
/// tree it already made. So a tree missing `outbox/enrollment` was made
/// incomplete AFTER preparation — by whatever carries the folder between
/// devices — which is exactly the case discovery must read as "not yet".
#[test]
fn preparing_a_share_publishes_a_complete_joinable_provider_tree() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture("share-provider-tree");
    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root.clone(),
        open_request,
        activation_request,
    );
    assert!(receipt.starts_with("ok "), "{receipt}");

    let provider_root = graph_root.join(".tine-sync/v2/shared");
    let mut expected = crate::oplog::SHARED_PROVIDER_TREE_NAMESPACES.to_vec();
    expected.sort_unstable();
    for tree in ["inbox", "outbox"] {
        let mut present = fs::read_dir(provider_root.join(tree))
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .collect::<Vec<_>>();
        present.sort();
        assert_eq!(
            present, expected,
            "share preparation left an incomplete {tree} tree"
        );
    }
    // The one file a joining device looks for, present and readable.
    let descriptor = inspect_shared_enrollment_for_cold_discovery(&provider_root)
        .unwrap()
        .expect("a prepared share is joinable");
    assert!(!descriptor.encoded.is_empty());
    assert_eq!(
        inspect_shared_provider_cold_prefix(&provider_root).unwrap(),
        SyncSharedProviderColdPrefix::ReadyForDescriptorInspection
    );

    // The state Martin's desktop is in. It must read as "nothing to join
    // yet", not as a hostile tree, on both the discovery and prefix paths.
    fs::remove_dir_all(provider_root.join("outbox/enrollment")).unwrap();
    assert_eq!(
        inspect_shared_enrollment_for_cold_discovery(&provider_root).unwrap(),
        None
    );
    assert_eq!(
        inspect_shared_provider_cold_prefix(&provider_root).unwrap(),
        SyncSharedProviderColdPrefix::Partial
    );
}

/// The same journey on a filesystem that CANNOT hold two of its page names.
///
/// Android shared storage folds case (CI 32123012366): the fixture's
/// `pages/K\u{16f}\u{148} b\u{11b}\u{17e}\u{ed}.md` read back the 18
/// bytes written for `pages/k\u{16f}\u{148} b\u{11b}\u{17e}\u{ed}.md`
/// instead of its own 8. The fixture's precondition check caught that and
/// refused — correctly, but it took Android's ONLY coverage with it.
///
/// So the journey now models what the filesystem does and asserts the
/// product behavior on the tree that filesystem can actually hold:
/// * exactly ONE page for the folded pair, never two and never none;
/// * that page holds the bytes the storage really has;
/// * the outside writer's write to the twin spelling is an ordinary EDIT
///   there, reconciled rather than refused;
/// * and nothing about it refuses the rest of the graph.
///
/// No host filesystem this suite runs on folds anything, so the fold is
/// forced. That is the same reason the Android instrumentation exists at
/// all: the behavior is unreachable here and reachable there.
#[test]
fn android_managed_storage_journey_holds_one_page_on_a_case_folding_graph_filesystem() {
    use crate::graph_name_folding::{
        clear_graph_name_folding_for_tests, force_graph_name_folding_for_tests, GraphNameFolding,
    };

    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture_with("case-folding", false);
    fs::create_dir_all(&graph_root).unwrap();
    let folding = GraphNameFolding {
        ascii_case: true,
        unicode_case: true,
        normalization: false,
    };
    force_graph_name_folding_for_tests(&graph_root, folding);
    crate::managed_storage_journey::write_journey_graph_fixture(&graph_root).unwrap();

    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root.clone(),
        open_request,
        activation_request,
    );
    clear_graph_name_folding_for_tests(&graph_root);
    assert!(
            receipt.starts_with("ok "),
            "a filesystem that cannot hold two of the graph's page names must not deny the whole graph: {receipt}"
        );
    assert!(
        receipt.contains("graph_name_folding=ascii_case+unicode_case"),
        "the receipt must name the folding it ran on: {receipt}"
    );
    // The twin never became a file of its own, and the one file the pair
    // shares holds exactly what the outside writer last wrote. Tine neither
    // recreated the twin nor rewrote the survivor.
    assert!(
        !graph_root
            .join(crate::managed_storage_journey::JOURNEY_CASE_TWIN_PAGE)
            .exists(),
        "Tine must not manufacture a file this storage cannot hold"
    );
    assert_eq!(
        fs::read_to_string(
            graph_root.join(crate::managed_storage_journey::JOURNEY_CASE_OWNER_PAGE)
        )
        .unwrap(),
        crate::managed_storage_journey::JOURNEY_CASE_TWIN_AFTER,
    );
    // The pair that this filesystem does NOT fold is still two files. A
    // fixture that dropped every twin as soon as anything folded would stop
    // covering the normalization shape that reproduced the field report.
    assert_eq!(
        fs::read_to_string(graph_root.join("pages/Z\u{30c} pilot notes #pilot.md")).unwrap(),
        "- decomposed pilot notes\n"
    );
}

/// The other axis, probed independently because it is a different platform
/// fact: a filesystem that folds NFC against NFD but keeps case apart —
/// HFS+, and what AOSP's casefold implementation suggests Android should
/// also do, though CI 32123012366 says it does not (see
/// `docs/storage-sync-contract.md` §2.10d).
///
/// The pair that folds is the other one, so this is not the same test with
/// a different constant: it proves the journey reads its expectations out
/// of the probe rather than out of a hard-coded idea of which pair folds.
#[test]
fn android_managed_storage_journey_holds_one_page_on_a_normalizing_graph_filesystem() {
    use crate::graph_name_folding::{
        clear_graph_name_folding_for_tests, force_graph_name_folding_for_tests, GraphNameFolding,
    };

    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture_with("normalization-folding", false);
    fs::create_dir_all(&graph_root).unwrap();
    force_graph_name_folding_for_tests(
        &graph_root,
        GraphNameFolding {
            ascii_case: false,
            unicode_case: false,
            normalization: true,
        },
    );
    crate::managed_storage_journey::write_journey_graph_fixture(&graph_root).unwrap();

    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root.clone(),
        open_request,
        activation_request,
    );
    clear_graph_name_folding_for_tests(&graph_root);
    assert!(
        receipt.starts_with("ok "),
        "a normalizing filesystem must not deny the whole graph either: {receipt}"
    );
    assert!(
        receipt.contains("graph_name_folding=normalization"),
        "the receipt must name the folding it ran on: {receipt}"
    );
    // The decomposed spelling has no file of its own; the precomposed one
    // holds the last write for the pair.
    assert!(!graph_root
        .join("pages/Z\u{30c} pilot notes #pilot.md")
        .exists());
    assert_eq!(
        fs::read_to_string(graph_root.join("pages/\u{17d} pilot notes #pilot.md")).unwrap(),
        "- decomposed pilot notes\n"
    );
    // Case is a different axis: this filesystem holds that pair apart, and
    // the twin still carries the outside writer's bytes with no page of its
    // own.
    assert_eq!(
        fs::read_to_string(graph_root.join(crate::managed_storage_journey::JOURNEY_CASE_TWIN_PAGE))
            .unwrap(),
        crate::managed_storage_journey::JOURNEY_CASE_TWIN_AFTER,
    );
    assert_eq!(
        fs::read_to_string(
            graph_root.join(crate::managed_storage_journey::JOURNEY_CASE_OWNER_PAGE)
        )
        .unwrap(),
        "- horse\n"
    );
}

/// The device shape, at the host boundary: another writer changes a graph
/// file WHILE activation is running — after the source capture is sealed and
/// before the final inventory proof.
///
/// CI 32115065229 reported it from an Android emulator as
/// `activation failed after Phase { phase: ImmutablePublicationInstall }:
/// Retryable { … "source capture changed before final inventory proof: 1
/// row(s) differ; first 1: changed: file pages/Ž pilot notes #pilot.md …
/// content:4371a8010f63@26 -> … content:888a74373a30@25" }` — and both
/// spellings of that path print identically, which is why the escaped
/// rendering is asserted here rather than the raw one.
///
/// An external editor saving mid-activation is in scope, and the runtime
/// already answers it: the refusal is `Retryable` and the attempt retracts
/// the disposable archive it created. What was NOT proven anywhere is that
/// the journey converges — the instrumentation reported the first refusal
/// and stopped, so three device rounds said "activation failed" about a
/// scenario the product handles. This drives the whole journey through it.
#[test]
fn android_managed_storage_journey_converges_when_a_graph_file_changes_during_activation() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture("external-write-during-activation");
    let moved = graph_root.join("pages/\u{17d} pilot notes #pilot.md");
    let changed = "- precomposed pilot notes edited by another editor\n";
    crate::model::set_bootstrap_source_capture_before_final_proof_hook_for_test({
        let moved = moved.clone();
        move || fs::write(&moved, changed)
    });

    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root.clone(),
        open_request,
        activation_request,
    );
    assert!(
        receipt.starts_with("ok "),
        "an external write during activation must converge on retry, not fail forever: \
             {receipt}"
    );
    assert!(
        receipt.contains("activation_attempts=2"),
        "the receipt must say the journey needed a second attempt: {receipt}"
    );
    assert!(
        receipt.contains("clean_open.bootstrap_streaming_import"),
        "a retried-past refusal must retain its typed source code: {receipt}"
    );
    // Write-shyness: the retry rebuilt from the OTHER writer's bytes and
    // rewrote nothing of its own, here or on the twin that differs from it
    // only by Unicode normalization.
    assert_eq!(fs::read_to_string(&moved).unwrap(), changed);
    assert_eq!(
        fs::read_to_string(graph_root.join("pages/Z\u{30c} pilot notes #pilot.md")).unwrap(),
        "- decomposed pilot notes\n"
    );
}

/// The journey's external-reconciliation leg EDITS a page that the
/// journey's own fixture put on disk. Driven against a graph that lacks
/// that fixture the same write is a CREATE, the `archiv/` backup copy of
/// the same decoded name sorts earlier and wins it, and the run fails as
/// `external edit did not reconcile: Ok(Missing { draft: None })` — which
/// says nothing about the actual mistake. That is verbatim how the resume
/// instrumentation case failed on CI 32108957903 while the runtime behaved
/// exactly as `bootstrap_authoritative_source_paths` specifies.
///
/// The precondition is now proven where it is required, so a caller that
/// drives the journey against the wrong graph is told so.
#[test]
fn android_journey_refuses_a_graph_that_lacks_its_own_fixture() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture_with("no-journey-graph", false);
    fs::create_dir_all(graph_root.join("pages")).unwrap();
    fs::create_dir_all(graph_root.join("journals")).unwrap();
    fs::create_dir_all(graph_root.join("logseq")).unwrap();
    fs::write(graph_root.join("logseq/config.edn"), "{}\n").unwrap();
    fs::write(
        graph_root.join("pages/Resume.md"),
        "- Android interrupted activation resume\n",
    )
    .unwrap();
    fs::write(
        graph_root.join(crate::managed_storage_journey::JOURNEY_EDITED_PAGE),
        "- Android managed storage smoke\n",
    )
    .unwrap();

    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root,
        open_request,
        activation_request,
    );
    assert!(
        receipt.starts_with("journey precondition failed:"),
        "a journey driven against the wrong graph must say so: {receipt}"
    );
    assert!(
        receipt.contains(crate::managed_storage_journey::JOURNEY_EXTERNAL_EDIT_PAGE),
        "the refusal must name the page the leg edits: {receipt}"
    );
}

/// The graph the device journey actually holds: the instrumentation writes
/// 1097 corpus pages before it calls in, and the journey's own name shapes
/// are layered under them.
///
/// Reconciliation advances one bounded slice per turn, so the number of
/// turns the drain must offer scales with the graph. This graph settles on
/// tick 71 here; the journey's previous fixed 64 was below that, so a
/// correct runtime would have been reported as `external reconciliation
/// never admitted an epoch` on the first device run that got this far.
/// Nothing smaller reproduces it — 600 corpus pages settle on tick 40 — so
/// the fixture is the device's, deliberately.
#[test]
fn android_managed_storage_journey_settles_reconciliation_on_a_corpus_scale_graph() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture_with("corpus-scale", false);
    fs::create_dir_all(graph_root.join("pages")).unwrap();
    for page_index in 0..1097 {
        let mut blocks = String::new();
        for block_index in 0..12 {
            blocks.push_str(&format!(
                "- Android corpus page {page_index} block {block_index} with [[Smoke]] \
                     and #android-corpus\n"
            ));
        }
        fs::write(
            graph_root.join(format!("pages/Corpus-{page_index}.md")),
            blocks,
        )
        .unwrap();
    }
    crate::managed_storage_journey::write_journey_graph_fixture(&graph_root).unwrap();

    let receipt = crate::managed_storage_journey::run_managed_storage_journey(
        graph_root,
        open_request,
        activation_request,
    );
    assert!(
        receipt.starts_with("ok "),
        "the journey must settle its external reconciliation at the size the device \
             instrumentation runs: {receipt}"
    );
}

/// Two physical files whose decoded page name is the same: the FIRST exact
/// path owns the name and the later one keeps its bytes with no page of its
/// own (`bootstrap_authoritative_source_paths`). Exact-path order is plain
/// byte order over the graph-relative path, so a copy under a directory
/// that sorts before `pages/` takes the name from the file in `pages/`.
///
/// This pins the rule rather than endorsing it: it is the reason a journey
/// leg that meant to edit `pages/Denní poznámky.md` silently addressed
/// `archiv/2026/Denní poznámky.md` instead, and a user with an ordinary
/// backup copy gets the backup as their page with no surface saying so.
#[test]
fn one_page_name_with_two_physical_files_is_owned_by_the_first_exact_path() {
    let (graph_root, _open_request, activation_request) =
        android_instrumentation_journey_fixture_with("duplicate-name-order", false);
    fs::create_dir_all(graph_root.join("pages")).unwrap();
    fs::create_dir_all(graph_root.join("journals")).unwrap();
    fs::create_dir_all(graph_root.join("logseq")).unwrap();
    fs::write(graph_root.join("logseq/config.edn"), "{}\n").unwrap();
    fs::create_dir_all(graph_root.join("archiv/2026")).unwrap();
    fs::write(graph_root.join("pages/Notes.md"), "- the page\n").unwrap();
    fs::write(
        graph_root.join("archiv/2026/Notes.md"),
        "- the backup copy\n",
    )
    .unwrap();

    let activation = SyncRuntimeHandle::activate_or_resume_local(activation_request);
    assert_eq!(activation.status, SyncLocalActivationStatus::Active);
    let handle = activation.handle.expect("activation opens the actor");
    let backup = handle
        .load_application_page(SyncApplicationPageLoadRequest {
            page: SyncApplicationPageSelector::ExactPath {
                path: "archiv/2026/Notes.md".into(),
            },
        })
        .unwrap();
    assert!(
        matches!(&backup, SyncApplicationPageLoadOutcome::Loaded { page, .. }
                if page.blocks.first().map(|block| block.raw.as_str()) == Some("the backup copy")),
        "the earlier exact path owns the decoded name: {backup:?}"
    );
    let canonical = handle
        .load_application_page(SyncApplicationPageLoadRequest {
            page: SyncApplicationPageSelector::ExactPath {
                path: "pages/Notes.md".into(),
            },
        })
        .unwrap();
    assert!(
        matches!(canonical, SyncApplicationPageLoadOutcome::Missing { .. }),
        "the later exact path acquires no page of its own: {canonical:?}"
    );
    assert_eq!(
        fs::read_to_string(graph_root.join("pages/Notes.md")).unwrap(),
        "- the page\n",
        "its bytes are still exactly where the user left them"
    );
    drop(handle);
}

#[test]
fn android_instrumentation_save_journey_shape_succeeds_on_a_host_graph() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture("journey-shape");

    let mut progress_log = Vec::new();
    let activation = SyncRuntimeHandle::activate_or_resume_local_with_detailed_progress(
        activation_request,
        |progress| progress_log.push(progress.diagnostic_name().to_string()),
    );
    assert_eq!(
        activation.status,
        SyncLocalActivationStatus::Active,
        "progress={progress_log:?}"
    );
    let handle = activation.handle.expect("activation opens the actor");
    let (mut page, revision) = match handle.load_application_page(SyncApplicationPageLoadRequest {
        page: SyncApplicationPageSelector::ExactPath {
            path: "pages/Smoke.md".into(),
        },
    }) {
        Ok(SyncApplicationPageLoadOutcome::Loaded { page, revision }) => (page, revision),
        other => panic!("post-activation page load failed: {other:?}"),
    };
    page.blocks
        .first_mut()
        .expect("post-activation page has an editable block")
        .raw = "Android managed storage edited".into();
    let saved = handle.save_application_page(SyncApplicationPageSaveRequest {
        target: SyncApplicationPageSaveTarget::Existing {
            path: page.path.clone(),
            revision,
        },
        page,
    });
    assert!(
        matches!(saved, Ok(SyncApplicationPageSaveOutcome::Saved { .. })),
        "post-activation page save failed: {saved:?}"
    );
    assert_eq!(
        fs::read_to_string(graph_root.join("pages/Smoke.md")).unwrap(),
        "- Android managed storage edited\n"
    );

    // Match the force-closed app the instrumentation models: drop the last
    // sender without a clean drain and prove the exact durable edit reopens.
    drop(handle);
    let reopened = SyncRuntimeHandle::open(open_request);
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened.handle.expect("crash-style reopen opens the actor");
    match handle.load_application_page(SyncApplicationPageLoadRequest {
        page: SyncApplicationPageSelector::ExactPath {
            path: "pages/Smoke.md".into(),
        },
    }) {
        Ok(SyncApplicationPageLoadOutcome::Loaded { page, .. }) => assert_eq!(
            page.blocks.first().map(|block| block.raw.as_str()),
            Some("Android managed storage edited")
        ),
        other => panic!("crash-style reopened page mismatch: {other:?}"),
    }
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// One journey step further than its sibling: the Android instrumentation
/// prepares a share and then asks the SAME handle for a clean shutdown
/// (CI run 32098261560 — `clean shutdown failed: Err(ActorUnavailable)`,
/// with no panic anywhere in the job log).
///
/// A successful `prepare_shared` retires its actor by design — the actor
/// commits a Safe transaction, publishes the enrollment cut, and then stops
/// so one handle can never serve two enrollment epochs.  The handle,
/// however, kept advertising a live sender, so every later request —
/// including the observational `status()` and the `clean_shutdown()` that
/// should simply report the already-committed Safe state — collapsed into a
/// payload-free `ActorUnavailable`.  That is an availability bug: no
/// in-scope threat is served by refusing to name a state the runtime has
/// already reached durably.
#[test]
fn android_instrumentation_share_journey_shape_shuts_down_cleanly_on_a_host_graph() {
    let (graph_root, open_request, activation_request) =
        android_instrumentation_journey_fixture("share-journey-shape");

    let mut progress_log = Vec::new();
    let activation = SyncRuntimeHandle::activate_or_resume_local_with_detailed_progress(
        activation_request,
        |progress| progress_log.push(progress.diagnostic_name().to_string()),
    );
    assert_eq!(
        activation.status,
        SyncLocalActivationStatus::Active,
        "progress={progress_log:?}"
    );
    let handle = activation.handle.expect("activation opens the actor");
    let (mut page, revision) = match handle.load_application_page(SyncApplicationPageLoadRequest {
        page: SyncApplicationPageSelector::ExactPath {
            path: "pages/Smoke.md".into(),
        },
    }) {
        Ok(SyncApplicationPageLoadOutcome::Loaded { page, revision }) => (page, revision),
        other => panic!("post-activation page load failed: {other:?}"),
    };
    page.blocks
        .first_mut()
        .expect("post-activation page has an editable block")
        .raw = "Android managed storage edited".into();
    let saved = handle.save_application_page(SyncApplicationPageSaveRequest {
        target: SyncApplicationPageSaveTarget::Existing {
            path: page.path.clone(),
            revision,
        },
        page,
    });
    assert!(
        matches!(saved, Ok(SyncApplicationPageSaveOutcome::Saved { .. })),
        "post-activation page save failed: {saved:?}"
    );

    drop(handle);
    let reopened = SyncRuntimeHandle::open(open_request.clone());
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened.handle.expect("crash-style reopen opens the actor");
    match handle.load_application_page(SyncApplicationPageLoadRequest {
        page: SyncApplicationPageSelector::ExactPath {
            path: "pages/Smoke.md".into(),
        },
    }) {
        Ok(SyncApplicationPageLoadOutcome::Loaded { page, .. }) => assert_eq!(
            page.blocks.first().map(|block| block.raw.as_str()),
            Some("Android managed storage edited")
        ),
        other => panic!("crash-style reopened page mismatch: {other:?}"),
    }
    let prepared = handle.prepare_shared();
    assert!(prepared.is_ok(), "share preparation failed: {prepared:?}");

    // The enrollment cut retired the actor.  Observation must survive it:
    // the handle answers from the actor's final published snapshot rather
    // than reporting that the runtime cannot be reached at all.
    let status = handle
        .status()
        .expect("a retired actor still answers its own final status");
    assert_eq!(status.lifecycle, SyncRuntimeLifecycle::StoppedSafe);
    assert_eq!(status.shared_role, Some(SyncSharedRole::Initiator));
    let shutdown = handle.clean_shutdown();
    assert!(
        matches!(shutdown, Ok(SyncShutdownOutcome::Safe(_))),
        "clean shutdown after share preparation failed: {shutdown:?}"
    );
    drop(handle);

    let reopened = SyncRuntimeHandle::open(open_request);
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened
        .handle
        .expect("the shared-enrolled runtime reopens after its cut");
    assert_eq!(
        fs::read_to_string(graph_root.join("pages/Smoke.md")).unwrap(),
        "- Android managed storage edited\n"
    );
    let shutdown = handle.clean_shutdown();
    assert!(
        matches!(shutdown, Ok(SyncShutdownOutcome::Safe(_))),
        "reopened clean shutdown failed: {shutdown:?}"
    );
}

/// The other half of the retirement rule.  Only a SUCCESSFUL enrollment cut
/// retires the actor; a pre-Safe refusal must leave it reachable for an
/// explicit retry or a crash-style drop, exactly as before.
#[cfg(unix)]
#[test]
fn a_refused_share_preparation_leaves_the_actor_available() {
    let fixture = ActivationFixture::nested_unicode("share-refusal-keeps-actor", 0xa179_0000);
    let handle = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone())
        .handle
        .expect("share-refusal initiator LocalActive");
    drive_initial_feed(&handle);
    let refused = {
        let _injected =
            crate::oplog::wire::InjectedSharedProviderFlaggedRenameFailure::enter(libc::EIO);
        handle.prepare_shared()
    };
    assert!(
        matches!(refused, Err(SyncRuntimeRequestError::ActorRefused(_))),
        "unexpected share-preparation outcome: {refused:?}"
    );
    // An actor round trip, not a cached snapshot: it proves the thread is
    // still running and its request channel is still open.
    assert!(
        handle.last_retained_publication().is_ok(),
        "a refused share preparation must leave the actor reachable"
    );
    handle
        .prepare_shared()
        .expect("the retained actor completes the cut on an explicit retry");
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
}

/// Every refusal a platform boundary can observe must name where it came
/// from.  The Android instrumentation journey can report only the returned
/// error value, so an editor-shaped rejection of a request the application
/// layer built itself must not collapse into a bare `ActorRefused`: that
/// leaves an off-host failure permanently undiagnosable.
#[test]
fn derived_editor_rejections_name_their_stage_at_the_application_boundary() {
    for reason in [
        SyncEditorInvalidRequest::EmptyTemporaryKey,
        SyncEditorInvalidRequest::InvalidTemporaryKey,
        SyncEditorInvalidRequest::InvalidExistingId,
        SyncEditorInvalidRequest::DuplicateKey,
        SyncEditorInvalidRequest::UnknownParent,
        SyncEditorInvalidRequest::CyclicOutline,
        SyncEditorInvalidRequest::InvalidName,
    ] {
        let mapped =
            map_editor_application_error(SyncEditorRequestError::InvalidRequest(reason.clone()));
        let SyncApplicationPageRequestError::ActorRefusedAt(stage) = mapped else {
            panic!("derived editor rejection {reason:?} lost its site: {mapped:?}");
        };
        assert!(
            stage.starts_with("derived_editor_"),
            "unexpected stage {stage}"
        );
    }
}

