#[test]
fn public_clean_runtime_reconciles_an_exact_external_edit_and_reopens_it() {
    const EXTERNAL: &str = "externally edited through the clean watcher";
    let fixture = ActivationFixture::nested_unicode("clean-external-edit", 0xa17c);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("clean activation opens actor");
    let page_id = match handle
        .query(SyncRuntimeQueryRequest::ResolvePage {
            path: "Root.md".into(),
            name: "Root logical".into(),
            page_kind: SyncPageKind::Page,
        })
        .unwrap()
    {
        SyncRuntimeQueryReply::Page(Some(page)) => page.page_id,
        other => panic!("clean Root.md resolution failed: {other:?}"),
    };
    fs::write(
        fixture.graph_root.join("Root.md"),
        format!("title:: Root logical\r\n\r\n- {EXTERNAL}\r\n"),
    )
    .unwrap();
    handle
        .observe_watcher(vec![
            SyncWatcherObservation::managed_path("Root.md").unwrap()
        ])
        .unwrap();
    let ticks = drain_until_settled(&handle);
    assert!(
        ticks
            .iter()
            .any(|tick| matches!(tick, SyncRuntimeTick::AdmittedComplete { .. })),
        "clean external edit did not produce an observable admission: {ticks:?}"
    );
    let loaded = handle
        .load_editor_page(SyncEditorLoadRequest {
            page: SyncEditorPageSelector::PageId {
                page_id: page_id.clone(),
            },
        })
        .unwrap();
    assert!(matches!(
        loaded,
        SyncEditorLoadOutcome::Loaded { page }
            if page.page_id == page_id && page.blocks[0].content == EXTERNAL
    ));
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let reopened = reopened.handle.expect("external edit cold-reopens");
    drive_initial_feed(&reopened);
    let loaded = reopened
        .load_editor_page(SyncEditorLoadRequest {
            page: SyncEditorPageSelector::PageId { page_id },
        })
        .unwrap();
    assert!(matches!(
        loaded,
        SyncEditorLoadOutcome::Loaded { page } if page.blocks[0].content == EXTERNAL
    ));
    assert!(matches!(
        reopened.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// GH #397: page hydration can race a bounded watcher continuation on a
/// large graph. Application-page selectors must still read the same current
/// Markdown bytes while the actor has not yet admitted them; selector choice
/// cannot turn that ordinary race into a `hot_source_join` refusal.
#[test]
fn application_page_selectors_read_external_content_before_watcher_settles() {
    const EXTERNAL: &str = "external winner before focus rescan settlement";
    let fixture = ActivationFixture::nested_unicode("focus-rescan-selector-parity", 0xa17c_397);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("clean activation opens actor");
    drive_initial_feed(&handle);

    fs::write(
        fixture.graph_root.join("Root.md"),
        format!("title:: Root logical\r\n\r\n- {EXTERNAL}\r\n"),
    )
    .unwrap();
    handle
        .observe_watcher(vec![SyncWatcherObservation::RescanRequired])
        .unwrap();
    assert!(
        handle.status().unwrap().watcher.pending,
        "the selector proof must run before the focus rescan settles"
    );

    let exact = handle
        .load_application_page(SyncApplicationPageLoadRequest {
            page: SyncApplicationPageSelector::ExactPath {
                path: "Root.md".into(),
            },
        })
        .unwrap();
    assert!(matches!(
        exact,
        SyncApplicationPageLoadOutcome::Loaded { page, .. }
            if page.blocks[0].raw == EXTERNAL
    ));

    let logical = handle
        .load_application_page(SyncApplicationPageLoadRequest {
            page: SyncApplicationPageSelector::Logical {
                name: "Root logical".into(),
                page_kind: SyncPageKind::Page,
            },
        })
        .expect("a logical route must not refuse at hot_source_join");
    assert!(matches!(
        logical,
        SyncApplicationPageLoadOutcome::Loaded { page, .. }
            if page.blocks[0].raw == EXTERNAL
    ));

    let delete = handle.mutate_application_graph(SyncApplicationGraphMutationRequest::DeletePage {
        name: "Root logical".into(),
        page_kind: SyncPageKind::Page,
        expected_path: Some("Root.md".into()),
    });
    assert!(
        matches!(
            delete,
            Err(SyncApplicationPageRequestError::ActorRefusedAt(_))
        ),
        "a mutation baseline must refuse the unadmitted external edit: {delete:?}"
    );
    assert!(fixture.graph_root.join("Root.md").is_file());

    drain_until_settled(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

