fn recursive_file_bytes(root: &Path) -> BTreeMap<String, Vec<u8>> {
    let mut files = BTreeMap::new();
    if !root.is_dir() {
        return files;
    }
    let mut pending = vec![root.to_path_buf()];
    while let Some(directory) = pending.pop() {
        let mut entries = fs::read_dir(directory)
            .unwrap()
            .map(Result::unwrap)
            .collect::<Vec<_>>();
        entries.sort_by_key(std::fs::DirEntry::file_name);
        for entry in entries {
            if entry.file_type().unwrap().is_dir() {
                pending.push(entry.path());
            } else {
                let relative = entry
                    .path()
                    .strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                files.insert(relative, fs::read(entry.path()).unwrap());
            }
        }
    }
    files
}

fn immutable_archive_bytes(archive_root: &Path) -> BTreeMap<String, Vec<u8>> {
    recursive_file_bytes(archive_root)
        .into_iter()
        .filter(|(path, _)| {
            ["objects/", "batches/", "bootstrap-v1/"]
                .iter()
                .any(|prefix| path.starts_with(prefix))
        })
        .collect()
}

#[derive(Debug)]
struct ActivationScaleReceipt {
    source_files: usize,
    source_bytes: usize,
    blocks: usize,
    total_ms: u128,
    phase_ms: Vec<(SyncLocalActivationPhase, u128)>,
    clean: CleanActivationInstrumentation,
    clean_marker_present: bool,
    retired_artifacts: Vec<String>,
    operation_batches: usize,
}

fn activation_source_counts(root: &Path) -> (usize, usize, usize) {
    let sources = user_graph_bytes(root);
    sources
        .iter()
        .filter(|(path, _)| {
            matches!(
                Path::new(path.as_str())
                    .extension()
                    .and_then(|value| value.to_str()),
                Some("md" | "markdown" | "org")
            )
        })
        .map(|(_, source)| source)
        .fold(
            (0_usize, 0_usize, 0_usize),
            |(files, bytes, blocks), source| {
                (
                    files + 1,
                    bytes + source.len(),
                    blocks
                        + source
                            .split(|byte| *byte == b'\n')
                            .filter(|line| {
                                line.starts_with(b"- ")
                                    || line.starts_with(b"* ")
                                    || line.starts_with(b"** ")
                            })
                            .count(),
                )
            },
        )
}

fn activate_with_scale_receipt(fixture: &ActivationFixture) -> ActivationScaleReceipt {
    let (source_files, source_bytes, blocks) = activation_source_counts(&fixture.graph_root);
    let before = user_graph_bytes(&fixture.graph_root);
    let started = std::time::Instant::now();
    let mut transitions = Vec::new();
    let activated = SyncRuntimeHandle::activate_or_resume_local_with_progress(
        fixture.request.clone(),
        |phase| {
            let elapsed = started.elapsed();
            if std::env::var_os("TINE_ACTIVATION_TRACE").is_some() {
                eprintln!("activation phase {:?} at {} ms", phase, elapsed.as_millis());
            }
            transitions.push((phase, elapsed));
        },
    );
    let total = started.elapsed();
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);
    let expected = [
        SyncLocalActivationPhase::PrivateSetup,
        SyncLocalActivationPhase::SourceCapture,
        SyncLocalActivationPhase::BootstrapImportPreparation,
        SyncLocalActivationPhase::ImmutablePublicationInstall,
        SyncLocalActivationPhase::SqliteOpenBuild,
        SyncLocalActivationPhase::ReconciliationBaselineActorOpen,
    ];
    assert_eq!(
        transitions
            .iter()
            .map(|(phase, _)| *phase)
            .collect::<Vec<_>>(),
        expected
    );
    let phase_ms = transitions
        .iter()
        .enumerate()
        .map(|(index, (phase, at))| {
            let end = transitions
                .get(index + 1)
                .map(|(_, next)| *next)
                .unwrap_or(total);
            (*phase, end.saturating_sub(*at).as_millis())
        })
        .collect();
    drop(activated.handle);
    let clean = take_clean_activation_instrumentation();
    let clean_marker_present = fixture
        .request
        .enrollment_root
        .join(crate::oplog::lazy_genesis::LAZY_GENESIS_ACTIVATION_MARKER_FILE)
        .is_file();
    let mut retired_artifacts = [
        "bootstrap-v1",
        "engine-history",
        "projection-work-index-v1",
        "reference-catalog-v2",
        "inactive-bootstrap-publication-v1",
    ]
    .iter()
    .filter(|name| fixture.request.archive_root.join(name).exists())
    .map(|name| format!("archive/{name}"))
    .collect::<Vec<_>>();
    for (label, root) in [
        ("capture scratch", &fixture.request.capture_root),
        ("preparation scratch", &fixture.request.preparation_root),
    ] {
        if !recursive_file_bytes(root).is_empty() {
            retired_artifacts.push(label.to_owned());
        }
    }
    let operation_batches = fs::read_dir(
        clean_operation_archive_directory(&fixture.request.archive_root).join("batches"),
    )
    .map(|entries| entries.filter_map(Result::ok).count())
    .unwrap_or(0);
    ActivationScaleReceipt {
        source_files,
        source_bytes,
        blocks,
        total_ms: total.as_millis(),
        phase_ms,
        clean,
        clean_marker_present,
        retired_artifacts,
        operation_batches,
    }
}

fn assert_activation_near_linear(small: &ActivationScaleReceipt, large: &ActivationScaleReceipt) {
    // Permit at most 1.5x normalized wall time plus a one-second fixed-cost
    // allowance. A quadratic implementation at the retained ~2x input
    // scales fails this discriminator, while fsync and scheduler noise do
    // not turn an otherwise linear debug-build receipt flaky.
    let observed = 2_u128
        .saturating_mul(large.total_ms)
        .saturating_mul(small.source_bytes as u128);
    let ceiling = 3_u128
        .saturating_mul(small.total_ms.saturating_add(1_000))
        .saturating_mul(large.source_bytes as u128);
    assert!(
            observed <= ceiling,
            "scaled activation exceeded the near-linear normalized ceiling: small={small:?}, large={large:?}"
        );
}

#[test]
fn retained_clean_reactivation_reports_each_recovery_boundary() {
    let fixture = ActivationFixture::nested_unicode("retained-reactivation-progress", 0xa091);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("fresh activation opens its actor");
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    let mut updates = Vec::new();
    let reopened = SyncRuntimeHandle::activate_or_resume_local_with_detailed_progress(
        fixture.request.clone(),
        |update| updates.push(update),
    );
    assert_eq!(reopened.status, SyncLocalActivationStatus::Active);
    let phases = updates
        .iter()
        .filter_map(|update| match update {
            SyncLocalActivationProgress::Phase { phase } => Some(*phase),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        phases,
        vec![
            SyncLocalActivationPhase::RetainedRuntimeOpen,
            SyncLocalActivationPhase::RetainedRuntimeTailReplay,
            SyncLocalActivationPhase::RetainedRuntimeProjectionRepair,
            SyncLocalActivationPhase::RetainedRuntimeActorOpen,
        ]
    );
    let handle = reopened
        .handle
        .expect("retained activation opens its actor");
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn activation_progress_is_ordered_exact_byte_and_structurally_near_linear() {
    let small = ActivationFixture::scaled("scale-small", 0xa090, 4);
    let large = ActivationFixture::scaled("scale-large", 0xa0a0, 8);
    let small_receipt = activate_with_scale_receipt(&small);
    let large_receipt = activate_with_scale_receipt(&large);
    eprintln!("activation scale small: {small_receipt:?}");
    eprintln!("activation scale large: {large_receipt:?}");
    assert_eq!(large_receipt.source_files, small_receipt.source_files + 4);
    assert!(large_receipt.source_bytes > small_receipt.source_bytes);
    assert!(large_receipt.blocks > small_receipt.blocks);
    assert_eq!(small_receipt.phase_ms.len(), 6);
    assert_eq!(large_receipt.phase_ms.len(), 6);
    for receipt in [&small_receipt, &large_receipt] {
        assert_eq!(
            receipt.clean.source_files, receipt.source_files as u64,
            "the clean builder must consume one activation record per source page"
        );
        assert_eq!(
            receipt.clean.source_bytes, receipt.source_bytes as u64,
            "the clean builder must consume each sealed source byte exactly once"
        );
        assert!(
            receipt.clean.parser_nodes >= receipt.blocks as u64,
            "the parser-owned activation record must cover every outline block"
        );
        assert!(
            receipt.clean.activation_record_bytes > 0,
            "the clean builder must retain a bounded parser-owned record stream"
        );
        assert!(
            !receipt.clean.activation_records_spilled,
            "the small structural fixture must remain on the bounded in-memory record path"
        );
        assert!(
            receipt.clean_marker_present,
            "clean activation must publish its sole authority marker last"
        );
        assert!(
                receipt.retired_artifacts.is_empty(),
                "clean activation retained retired bootstrap, Patricia, shadow, or backup artifacts: {:?}",
                receipt.retired_artifacts
            );
        assert_eq!(
            receipt.operation_batches, 0,
            "operation-free genesis must not fabricate an edit batch per imported page"
        );
    }
    assert_activation_near_linear(&small_receipt, &large_receipt);
}

/// The permanent per-operation durability-barrier budget (cost-model audit
/// 2026-08-26, defect D1).
///
/// A durability barrier is a device round trip. Their *count* — not any
/// phase timer — is what scales an ordinary edit from milliseconds on a
/// local SSD to hundreds of milliseconds on a slow or network filesystem.
/// Before this budget existed, one accepted single-block managed save
/// performed 66 barriers and a cross-page move 151, because durability was
/// decided artifact by artifact and no test ever looked at the sum.
///
/// The numbers asserted here are *core-initiated* barriers, as
/// [`crate::durability_counters`] documents: the local journal's own append
/// barriers inside `tine-storage` and the SQLite VFS are not visible from
/// this crate and are excluded from both sides of the comparison.
///
/// This test is deliberately cheap (a five-file fixture, not the real
/// corpus) so it runs in CI on every change. `managed_save_and_move_barrier_probe`
/// is its real-graph companion; the two agreed to within one barrier when
/// the budget was set, because barrier count is a property of the *shape*
/// of an accepted batch and not of graph size — which is exactly why a
/// small fixture can guard it.
/// Mark the operation boundary in a `TINE_PUBLISH_TRACE=1` run, so the
/// per-artifact-class ledger the budget produces can be split into
/// "activation", "save" and "move" instead of read as one undivided list.
/// Silent otherwise.
fn publication_trace_phase(phase: &str) {
    if std::env::var_os("TINE_PUBLISH_TRACE").is_some() {
        eprintln!("PUBLISH PHASE {phase}");
    }
}

/// One managed-local frame and one projection turn are the same authority
/// in two shapes (journal-universal durability design §3.2/§3.6). The drain
/// projects the foreground frame into the `ProjectionTurn` view so recovery
/// has one record shape to reason about, whichever physical segment carried
/// it. The production managed-local drain feeds this view to the same
/// turn-level executor used by the independent projection journal.
#[test]
fn a_foreground_journal_frame_projects_into_the_same_projection_turn_view() {
    let fixture = ActivationFixture::nested_unicode("frame-as-turn", 0xa1c1);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("turn-view fixture activates");
    drive_initial_feed(&handle);
    drain_managed_local(&handle);

    let request = simple_application_move_request(&handle, "Turn View");
    let (page, revision) = load_application_exact(&handle, &request.source_path);
    let _ = save_application_block_text(&handle, page, revision, "turn-view single-block edit");

    let lineage_digest = fixture.request.identities.lineage_digest;
    let open_request = reopen_request(&fixture.request);
    let frames = managed_local_journal_frames(&open_request);
    let frame = frames
        .last()
        .expect("an accepted save leaves at least one retained frame");
    let record = crate::oplog::decode_managed_local_record(frame).unwrap();
    let turn = crate::oplog::local_journal_drain::projection_turn_from_managed_local_frame(
        frame,
        lineage_digest,
    )
    .expect("a managed-local frame projects into a turn");

    assert_eq!(turn.domain, crate::oplog::SequenceDomain::ManagedLocal);
    assert_eq!(turn.sequence, frame.sequence());
    assert_eq!(turn.device_id, frame.device_id());
    assert_eq!(turn.lineage_digest, lineage_digest);
    assert_eq!(
        turn.origin,
        crate::oplog::TurnOrigin::LocalBatch {
            batch_id: record.prepared_batch().manifest().batch_id()
        }
    );
    assert_eq!(turn.pages.len(), record.projections().len());
    for (page, projection) in turn.pages.iter().zip(record.projections()) {
        assert_eq!(&page.path, projection.intent().path());
        assert_eq!(page.page_id, projection.intent().page_id());
        match (&page.target, projection.intent().target()) {
            (
                crate::oplog::TurnTarget::Present { bytes, .. },
                crate::oplog::ManifestProjectionTarget::Present {
                    bytes: expected, ..
                },
            ) => assert_eq!(bytes.as_deref(), Some(expected.as_slice())),
            (crate::oplog::TurnTarget::Absent, crate::oplog::ManifestProjectionTarget::Absent) => {}
            (turn_target, intent_target) => {
                panic!("target kinds differ: {turn_target:?} versus {intent_target:?}")
            }
        }
    }

    // The projected view is itself a canonical record.
    let bytes = turn.encode().unwrap();
    assert_eq!(
        crate::oplog::ProjectionTurn::decode(&bytes, frame.device_id(), frame.sequence()).unwrap(),
        turn
    );

    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn managed_save_and_move_stay_within_their_barrier_budget() {
    let session = crate::durability_counters::BarrierSession::begin();
    let fixture = ActivationFixture::nested_unicode("barrier-budget", 0xa1c0);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("barrier budget fixture activates");
    drive_initial_feed(&handle);

    let mut request = simple_application_move_request(&handle, "Barrier Budget");
    drain_managed_local(&handle);

    // (c) one accepted single-block save, foreground plus deferred drain.
    let (page, revision) = load_application_exact(&handle, &request.source_path);
    session.reset();
    publication_trace_phase("save");
    let (page, revision) =
        save_application_block_text(&handle, page, revision, "budgeted single-block edit");
    let save_foreground = session.counts();
    drain_managed_local(&handle);
    let save_total = session.counts();
    eprintln!(
        "managed save barriers: foreground [{}] total [{}]",
        save_foreground.report(),
        save_total.report()
    );

    // (d) one accepted cross-page move, foreground plus deferred drain.
    request.source_revision = revision;
    request.roots[0].identity = page.blocks[0].id.clone();
    let (_destination, destination_revision) =
        load_application_exact(&handle, &request.destination_path);
    request.destination_revision = destination_revision;
    session.reset();
    publication_trace_phase("move");
    let moved = accepted_application_move(&handle, &request);
    assert!(matches!(
        moved,
        SyncApplicationMoveSubtreesOutcome::Committed { .. }
    ));
    let move_foreground = session.counts();
    drain_managed_local(&handle);
    let move_total = session.counts();
    eprintln!(
        "managed cross-page move barriers: foreground [{}] total [{}]",
        move_foreground.report(),
        move_total.report()
    );

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    crate::durability_counters::BarrierSession::detach_current_thread();

    assert_eq!(
        save_foreground.total(),
        3,
        "managed save foreground barrier pin moved: {}",
        save_foreground.report()
    );
    assert_eq!(
        save_total.total(),
        crate::durability_counters::MANAGED_SAVE_BARRIER_BUDGET,
        "one accepted single-block managed save performed {} core-initiated durability \
             barriers, pinned total {} ({}). Each barrier is a device round trip; any drift \
             must be attributed before this exact ledger changes.",
        save_total.total(),
        crate::durability_counters::MANAGED_SAVE_BARRIER_BUDGET,
        save_total.report()
    );
    assert_eq!(
        move_foreground.total(),
        0,
        "managed move foreground barrier pin moved: {}",
        move_foreground.report()
    );
    assert_eq!(
        move_total.total(),
        crate::durability_counters::MANAGED_MOVE_BARRIER_BUDGET,
        "one accepted cross-page move performed {} core-initiated durability barriers, \
             pinned total {} ({}).",
        move_total.total(),
        crate::durability_counters::MANAGED_MOVE_BARRIER_BUDGET,
        move_total.report()
    );
}

#[test]
fn own_endpoint_save_and_move_author_no_receipt_artifacts() {
    let fixture = ActivationFixture::nested_unicode("own-receipt-retirement", 0xa1c3);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("own receipt retirement fixture activates");
    drive_initial_feed(&handle);

    let mut request = simple_application_move_request(&handle, "Own Receipt Retirement");
    drain_managed_local(&handle);
    let before_save = recursive_file_bytes(&fixture.request.receipt_root);

    let (page, revision) = load_application_exact(&handle, &request.source_path);
    let (page, revision) =
        save_application_block_text(&handle, page, revision, "own receipt retirement save");
    drain_managed_local(&handle);
    assert_eq!(
        recursive_file_bytes(&fixture.request.receipt_root),
        before_save,
        "an own-endpoint save must not author or rewrite receipt artifacts"
    );

    request.source_revision = revision;
    request.roots[0].identity = page.blocks[0].id.clone();
    let (_destination, destination_revision) =
        load_application_exact(&handle, &request.destination_path);
    request.destination_revision = destination_revision;
    let moved = accepted_application_move(&handle, &request);
    assert!(matches!(
        moved,
        SyncApplicationMoveSubtreesOutcome::Committed { .. }
    ));
    drain_managed_local(&handle);
    assert_eq!(
        recursive_file_bytes(&fixture.request.receipt_root),
        before_save,
        "an own-endpoint move must not author or rewrite receipt artifacts"
    );

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn residual_own_endpoint_receipts_are_reported_but_remain_inert_on_open() {
    let fixture = ActivationFixture::nested_unicode("own-receipt-residue", 0xa1c4);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("own receipt residue fixture activates");
    drive_initial_feed(&handle);
    drain_managed_local(&handle);

    let request = simple_application_move_request(&handle, "Own Receipt Residue");
    let base = fs::read(fixture.graph_root.join(&request.source_path)).unwrap();
    let (page, revision) = load_application_exact(&handle, &request.source_path);
    let _ = save_application_block_text(&handle, page, revision, "residual receipt save");
    let frames = managed_local_journal_frames(&reopen_request(&fixture.request));
    let record = crate::oplog::decode_managed_local_record(
        frames
            .last()
            .expect("the save retains its authoritative frame"),
    )
    .unwrap();
    let intent = record
        .projections()
        .iter()
        .find(|projection| projection.intent().path().as_str() == request.source_path.as_str())
        .expect("the save frame carries its own projection")
        .completion_intent()
        .unwrap()
        .clone();
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    let graph = Graph::open(&fixture.graph_root);
    let endpoint = ProjectionEndpointBinding::enroll_graph(
        &graph,
        fixture.request.identities.endpoint_id,
        fixture.request.identities.device_id,
    )
    .unwrap();
    let receipts = ProjectionReceiptStore::open_for_endpoint(
        &fixture.request.receipt_root,
        fixture.request.identities.workspace_id,
        endpoint,
    )
    .unwrap();
    let published_base = match intent.precondition() {
        crate::oplog::ProjectionPrecondition::Absent => None,
        crate::oplog::ProjectionPrecondition::Base(description) => {
            assert_eq!(*description, BlobDescription::of(&base));
            Some(base.as_slice())
        }
    };
    receipts.publish_intent(&intent, published_base).unwrap();
    assert_eq!(
        receipts.validated_catalog().unwrap().len(),
        1,
        "the fixture must carry one pre-2c own receipt before retirement registration"
    );
    let before_report = recursive_file_bytes(&fixture.request.receipt_root);
    let own = [intent.id().unwrap()].into_iter().collect();
    let reported = receipts.retired_own_endpoint_artifacts(&own);
    assert!(
        reported.iter().any(|path| path.ends_with(".intent")),
        "the residual own intent suffix was not reported: {reported:?}"
    );
    assert!(
        receipts.validated_catalog().unwrap().is_empty(),
        "registered own residue must be excluded from the live receiver catalog"
    );
    assert_eq!(
        recursive_file_bytes(&fixture.request.receipt_root),
        before_report,
        "reporting and registering own residue must be names-only"
    );
    drop(receipts);
    drop(graph);
    let before_open = recursive_file_bytes(&fixture.request.receipt_root);

    let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    assert_eq!(
        recursive_file_bytes(&fixture.request.receipt_root),
        before_open,
        "reporting residual own receipt suffixes must not delete or rewrite them"
    );
}

/// The real-graph companion to
/// `managed_save_and_move_stay_within_their_barrier_budget`.
///
/// The fast budget test runs on a five-file fixture because barrier count
/// is a property of the *shape* of an accepted batch, not of graph size.
/// This probe is what proves that claim on a real corpus, and it is what
/// packet 2c measured on the anonymized real-graph copy. Exact base
/// `72150fb1` produced a warm-up save at 33, stable saves at 31, and a move
/// at 89; packet 2c produces 12, then stable 10s, and a move at 13. Run it
/// after any publication-protocol change and compare against the fixture.
///
/// ```text
/// TINE_MS_AUDIT_GRAPH_COPY=/path/to/graph \
///   cargo test -p tine-core --release --lib \
///   managed_save_and_move_barrier_probe -- --ignored --nocapture
/// ```
#[test]
#[ignore = "manual probe: per-operation durability barriers on a real graph copy"]
fn managed_save_and_move_barrier_probe() {
    let source = real_graph_copy_source_from_env("TINE_MS_AUDIT_GRAPH_COPY");
    let session = crate::durability_counters::BarrierSession::begin();
    let fixture = ActivationFixture::copied_graph("ms-barrier-probe", 0xa1c2, &source);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("the barrier probe activates");
    eprintln!("activation barriers: [{}]", session.counts().report());
    drive_initial_feed_with_turn_budget(&handle, 4096);

    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("barrier probe inventory did not load: {other:?}"),
    };
    let mut journals: Vec<String> = pages
        .iter()
        .map(|entry| entry.rel_path.clone())
        .filter(|path| path.starts_with("journals/"))
        .collect();
    journals.sort();
    let mut nonempty = Vec::new();
    for path in &journals {
        let (page, _) = load_application_exact(&handle, path);
        if !page.blocks.is_empty() {
            nonempty.push(path.clone());
        }
        if nonempty.len() == 2 {
            break;
        }
    }
    let day1 = nonempty
        .first()
        .expect("the corpus has a nonempty journal")
        .clone();
    let day2 = nonempty
        .get(1)
        .expect("the corpus has a second nonempty journal")
        .clone();

    for sample in 0..3 {
        let (page, revision) = load_application_exact(&handle, &day1);
        session.reset();
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            &format!("barrier probe save sample {sample}"),
        );
        let foreground = session.counts();
        drain_managed_local(&handle);
        eprintln!(
            "save sample {sample}: foreground [{}] total [{}]",
            foreground.report(),
            session.counts().report()
        );
    }

    let (source_page, source_revision) = load_application_exact(&handle, &day1);
    let (destination_page, destination_revision) = load_application_exact(&handle, &day2);
    session.reset();
    let outcome = handle
        .move_application_subtrees(SyncApplicationMoveSubtreesRequest {
            episode_id: Uuid::new_v4().to_string(),
            source_path: source_page.path.clone(),
            source_revision,
            destination_path: destination_page.path.clone(),
            destination_revision,
            roots: vec![SyncApplicationMoveRoot {
                identity: source_page.blocks[0].id.clone(),
                raw_rewrite: None,
            }],
            placement: SyncApplicationMovePlacement::Root { position: 0 },
            admission: application_move_admission(),
        })
        .unwrap();
    assert!(
        !matches!(outcome, SyncApplicationMoveSubtreesOutcome::NoCommit { .. }),
        "the barrier probe move did not commit: {outcome:?}"
    );
    let foreground = session.counts();
    drain_managed_local(&handle);
    eprintln!(
        "cross-day move: foreground [{}] total [{}]",
        foreground.report(),
        session.counts().report()
    );
    crate::durability_counters::BarrierSession::detach_current_thread();
}

/// Packet C-4's real-corpus absence gate. The supplied source is copied by
/// `ActivationFixture::copied_graph`; all managed writes and external
/// deletions therefore land only in the disposable fixture.
#[test]
#[ignore = "manual gate: absence sweep on an anonymized corpus copy"]
fn managed_absence_sweep_probe() {
    let source = real_graph_copy_source_from_env("TINE_MS_AUDIT_GRAPH_COPY");
    let fixture = ActivationFixture::copied_graph("c4-sweep-probe", 0xc4c0, &source);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    let handle = activated.handle.expect("the sweep corpus copy activates");
    drive_initial_feed_with_turn_budget(&handle, 4096);
    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("sweep corpus inventory did not load: {other:?}"),
    };
    assert!(pages.len() >= 4);
    let deleted = pages
        .iter()
        .take(4)
        .map(|page| page.rel_path.clone())
        .collect::<Vec<_>>();
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    for path in &deleted {
        fs::remove_file(fixture.graph_root.join(path)).unwrap();
    }

    let open_request = reopen_request(&fixture.request);
    let resources = open_clean_runtime_resources(&open_request)
        .unwrap()
        .expect("the sweep corpus copy reopens");
    let identities = open_request.clean_identities.clone().unwrap();
    let mut actor = RuntimeActor::from_clean_resources(
        open_request,
        identities,
        resources,
        SyncRuntimeRecovery::CleanManifestReplay,
    )
    .unwrap();
    for _ in 0..4096 {
        let tick = actor.tick();
        assert!(
            !matches!(
                tick,
                SyncRuntimeTick::RecoveryBlocked(_)
                    | SyncRuntimeTick::Blocked(_)
                    | SyncRuntimeTick::Terminal(_)
                    | SyncRuntimeTick::Failed(_)
            ),
            "corpus sweep did not converge: {tick:?}"
        );
        if !actor.clean.as_ref().unwrap().watcher_status().pending {
            break;
        }
    }
    let records = actor.clean.as_ref().unwrap().sweeps.records_for_test();
    assert_eq!(records.len(), 1);
    assert_eq!(records[0].members.len(), 4);
    assert_eq!(records[0].tier, SweepTier::Tier2);
    assert_eq!(records[0].pages_at_open as usize, pages.len());
    assert!(actor.publication_barrier_active());
    eprintln!(
        "corpus_sweep tier=tier2 k={} pages_at_open={} barrier_held_before_close=true",
        records[0].members.len(),
        records[0].pages_at_open
    );
    actor
        .clean
        .as_mut()
        .unwrap()
        .sweeps
        .force_open_window_close_for_test()
        .unwrap();
    assert!(!actor.publication_barrier_active());
    eprintln!("corpus_sweep barrier_released_at_close=true");
}

/// Packet C-5a's real-corpus Restore scale gate. The supplied graph is
/// copied before activation; deletion, revival batches, projections, and
/// sweep records are confined to the disposable fixture. Assertions use
/// semantic digests so private corpus text is never emitted by the gate.
#[test]
#[ignore = "manual gate: whole-sweep Restore on an anonymized corpus copy"]
fn managed_absence_restore_probe() {
    let source = real_graph_copy_source_from_env("TINE_MS_AUDIT_GRAPH_COPY");
    let fixture = ActivationFixture::copied_graph("c5a-restore-probe", 0xc5a0, &source);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    let handle = activated.handle.expect("the restore corpus copy activates");
    drive_initial_feed_with_turn_budget(&handle, 4096);
    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("restore corpus inventory did not load: {other:?}"),
    };
    let page_count = pages.len();
    let removal_count = page_count
        .saturating_mul(3)
        .saturating_add(9)
        .checked_div(10)
        .expect("the fixed percentage divisor is nonzero");
    let mut candidates = pages
        .iter()
        .filter(|page| page.rel_path.ends_with(".md") || page.rel_path.ends_with(".org"))
        .filter_map(|page| {
            fs::metadata(fixture.graph_root.join(&page.rel_path))
                .ok()
                .is_some_and(|metadata| metadata.is_file())
                .then_some(page.rel_path.clone())
        })
        .collect::<Vec<_>>();
    candidates.sort_unstable();
    assert!(
        candidates.len() >= removal_count,
        "the corpus copy has fewer writable text files than its 30% restore sample requires"
    );

    let mut selected = Vec::new();
    for path in candidates {
        let (mut page, _) = load_application_exact(&handle, &path);
        if page.read_only {
            continue;
        }
        let bytes = fs::read(fixture.graph_root.join(&path)).unwrap();
        page.rev = None;
        page.activation = None;
        let semantic_digest = ContentDigest::of(&serde_json::to_vec(&page).unwrap());
        selected.push((path, bytes, semantic_digest));
        if selected.len() == removal_count {
            break;
        }
    }
    assert_eq!(
        selected.len(),
        removal_count,
        "the corpus copy must supply the full 30% writable-page sample"
    );
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    for (path, _, _) in &selected {
        fs::remove_file(fixture.graph_root.join(path)).unwrap();
    }
    let handle = active_handle(SyncRuntimeHandle::open(reopen_request(&fixture.request)));
    drive_initial_feed_with_turn_budget(&handle, 4096);
    let event = handle
        .absence_sweep_events()
        .unwrap()
        .into_iter()
        .last()
        .expect("the closed-window corpus deletions surface one sweep");
    assert_eq!(event.tier, SyncAbsenceSweepTier::Tier3);
    assert_eq!(event.absence_count, selected.len());
    assert_eq!(event.pages_at_open, page_count);
    assert!(
        handle
            .prepare_shared()
            .unwrap_err()
            .to_string()
            .contains("external deletions awaiting disposition"),
        "the tier-3 restore window must retain the publication barrier"
    );
    let restored = handle.restore_absence_sweep(&event.sweep_id).unwrap();
    assert_eq!(restored.fidelity.len(), selected.len());
    drain_managed_local(&handle);

    let byte_identical = restored
        .fidelity
        .iter()
        .filter(|entry| entry.grade == SyncAbsenceSweepRestoreFidelityGrade::ByteIdentical)
        .count();
    let semantically_identical = restored.fidelity.len() - byte_identical;
    for (path, expected_bytes, expected_digest) in &selected {
        let (mut page, _) = load_application_exact(&handle, path);
        page.rev = None;
        page.activation = None;
        let actual_digest = ContentDigest::of(&serde_json::to_vec(&page).unwrap());
        assert_eq!(
            actual_digest, *expected_digest,
            "a restored corpus page differs semantically"
        );
        if restored.fidelity.iter().any(|entry| {
            entry.path == *path
                && entry.grade == SyncAbsenceSweepRestoreFidelityGrade::ByteIdentical
        }) {
            assert_eq!(
                fs::read(fixture.graph_root.join(path)).unwrap(),
                *expected_bytes,
                "a byte-identical corpus restore changed accepted layout"
            );
        }
    }
    eprintln!(
            "corpus_restore pages_at_open={} removed={} authored_batches={} byte_identical={} semantically_identical={} semantic_digest_match=true",
            page_count,
            selected.len(),
            restored.authored_batch_ids.len(),
            byte_identical,
            semantically_identical
        );
}

/// Measured C-2 freshness gate. The fixture copies the supplied corpus
/// before activation; the local completion objects are written only below
/// that disposable fixture.
#[test]
#[ignore = "manual gate: local-completion open cost on an anonymized corpus copy"]
fn local_completion_open_reads_only_the_summary_and_new_delta_on_a_real_copy() {
    let source = real_graph_copy_source_from_env("TINE_MS_AUDIT_GRAPH_COPY");
    let fixture = ActivationFixture::copied_graph("c2-open-cost", 0xc20c0, &source);
    let (pages, _, _) = activation_source_counts(&fixture.graph_root);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("the C-2 map-cost fixture activates");
    drive_initial_feed_with_turn_budget(&handle, 4096);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let store = ObjectStore::open(
        &clean_operation_archive_directory(&fixture.request.archive_root),
        fixture.request.identities.workspace_id,
    )
    .unwrap();
    let first = crate::oplog::ProjectionIntent::new(
        fixture.request.identities.workspace_id,
        PageId::from_uuid(Uuid::from_u128(0xc20c1)),
        ManagedPath::parse("C2 map cost first.md").unwrap(),
        crate::oplog::FrontierV2::default(),
        Vec::new(),
        crate::oplog::ProjectionPrecondition::Absent,
        crate::oplog::ProjectionTargetKind::Present,
        BlobDescription::of(b"first map cost target"),
        Vec::new(),
    )
    .unwrap();
    let second = crate::oplog::ProjectionIntent::new(
        fixture.request.identities.workspace_id,
        PageId::from_uuid(Uuid::from_u128(0xc20c2)),
        ManagedPath::parse("C2 map cost second.md").unwrap(),
        crate::oplog::FrontierV2::default(),
        Vec::new(),
        crate::oplog::ProjectionPrecondition::Absent,
        crate::oplog::ProjectionTargetKind::Present,
        BlobDescription::of(b"second map cost target"),
        Vec::new(),
    )
    .unwrap();
    let live = crate::oplog::local_completion_index::LocalCompletionPruningContext {
        live_page_paths: [
            (first.page_id(), first.path().clone()),
            (second.page_id(), second.path().clone()),
        ]
        .into_iter()
        .collect(),
        retained_intents: BTreeSet::new(),
        ..crate::oplog::local_completion_index::LocalCompletionPruningContext::default()
    };

    let mut index = crate::oplog::local_completion_index::LocalCompletionIndex::open(
        &store,
        fixture.request.identities.endpoint_id,
    )
    .unwrap();
    index.force_compaction_threshold_for_test(1);
    index.stage_completed(&first).unwrap();
    assert!(index.flush(pages, &live).unwrap());
    drop(index);

    let mut index = crate::oplog::local_completion_index::LocalCompletionIndex::open(
        &store,
        fixture.request.identities.endpoint_id,
    )
    .unwrap();
    index.stage_completed(&second).unwrap();
    assert!(index.flush(pages, &live).unwrap());
    drop(index);

    let index = crate::oplog::local_completion_index::LocalCompletionIndex::open(
        &store,
        fixture.request.identities.endpoint_id,
    )
    .unwrap();
    let stats = index.open_stats();
    eprintln!(
            "local_completion_open_cost corpus_pages={pages} names={} content_reads={} new_delta_names=1 rebuilt={}",
            stats.names_observed, stats.content_reads, stats.rebuilt
        );
    assert_eq!(stats.names_observed, 3);
    assert_eq!(stats.content_reads, 2);
    assert!(!stats.rebuilt);
}

/// The anonymized-corpus acceptance gate for the 2026-08-26 chain-flush cut
/// (`docs/storage-sync-contract.md` §2.10a-i).
///
/// A projection operation now flushes only the directory whose entry list
/// it changed; a freshly created ancestor gets its barrier from
/// `create_projection_chain_component` instead. Synthetic fixtures are
/// generated from our own model of a graph, so this drives the real shape:
/// a namespaced page whose projection path is two deep, plus a cross-page
/// move whose source and destination chains are distinct. The other half of
/// the invariant — a chain component the projection has to *create* — is
/// driven on the same corpus by
/// `model::tests::projection_creates_a_nested_parent_on_a_real_graph_copy`,
/// because a managed save whose page directory has been removed underneath
/// it is an external-deletion conflict, not a chain-creation path.
///
/// ```text
/// TINE_MS_AUDIT_GRAPH_COPY=/path/to/graph/copy \
///   cargo test -p tine-core --lib \
///   managed_nested_projection_lands_on_a_real_graph_copy -- --ignored --nocapture
/// ```
///
/// The copy must contain at least one page under a subdirectory of
/// `pages/`; the gate says so rather than silently passing without one.
#[test]
#[ignore = "manual acceptance gate: nested projection chains on a real graph copy"]
fn managed_nested_projection_lands_on_a_real_graph_copy() {
    let source = real_graph_copy_source_from_env("TINE_MS_AUDIT_GRAPH_COPY");
    let session = crate::durability_counters::BarrierSession::begin();
    let fixture = ActivationFixture::copied_graph("ms-nested-projection", 0xa1c3, &source);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("the real graph copy activates");
    drive_initial_feed_with_turn_budget(&handle, 4096);

    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("nested-projection inventory did not load: {other:?}"),
    };
    let mut nested: Vec<String> = pages
        .iter()
        .map(|entry| entry.rel_path.clone())
        .filter(|path| path.starts_with("pages/") && path.matches('/').count() >= 2)
        .collect();
    nested.sort();
    let nested = nested
        .first()
        .expect("this gate needs a page under a subdirectory of pages/; add one to the graph copy")
        .clone();
    let mut journals: Vec<String> = pages
        .iter()
        .map(|entry| entry.rel_path.clone())
        .filter(|path| path.starts_with("journals/"))
        .collect();
    journals.sort();

    // (a) Save into an existing two-deep chain.
    let (page, revision) = load_application_exact(&handle, &nested);
    session.reset();
    let (page, revision) =
        save_application_block_text(&handle, page, revision, "nested chain acceptance one");
    drain_managed_local(&handle);
    eprintln!(
        "nested save into an existing chain: [{}]",
        session.counts().report()
    );
    let absolute = fixture.graph_root.join(&nested);
    assert!(
        fs::read_to_string(&absolute)
            .unwrap()
            .contains("nested chain acceptance one"),
        "the nested page's bytes must reach {nested}"
    );

    // (b) A cross-page move: two distinct chains, source and destination.
    let mut nonempty = Vec::new();
    for path in &journals {
        let (candidate, _) = load_application_exact(&handle, path);
        if !candidate.blocks.is_empty() {
            nonempty.push(path.clone());
        }
        if nonempty.len() == 2 {
            break;
        }
    }
    let day1 = nonempty.first().expect("the copy has a nonempty journal");
    let day2 = nonempty.get(1).expect("the copy has a second journal");
    let (source_page, source_revision) = load_application_exact(&handle, day1);
    let (destination_page, destination_revision) = load_application_exact(&handle, day2);
    session.reset();
    let outcome = handle
        .move_application_subtrees(SyncApplicationMoveSubtreesRequest {
            episode_id: Uuid::new_v4().to_string(),
            source_path: source_page.path.clone(),
            source_revision,
            destination_path: destination_page.path.clone(),
            destination_revision,
            roots: vec![SyncApplicationMoveRoot {
                identity: source_page.blocks[0].id.clone(),
                raw_rewrite: None,
            }],
            placement: SyncApplicationMovePlacement::Root { position: 0 },
            admission: application_move_admission(),
        })
        .unwrap();
    assert!(
        !matches!(outcome, SyncApplicationMoveSubtreesOutcome::NoCommit { .. }),
        "the acceptance move did not commit: {outcome:?}"
    );
    drain_managed_local(&handle);
    eprintln!("cross-page move: [{}]", session.counts().report());
    let moved_text = source_page.blocks[0].raw.clone();
    assert!(
        fs::read_to_string(fixture.graph_root.join(day2))
            .unwrap()
            .contains(moved_text.lines().next().unwrap_or(&moved_text)),
        "the moved block must reach the destination journal"
    );

    let _ = revision;
    let _ = page;
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    crate::durability_counters::BarrierSession::detach_current_thread();
}

#[test]
#[ignore = "manual release gate: activation of a real graph copy"]
fn managed_activation_real_graph_manual_benchmark() {
    assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_activation_real_graph_manual_benchmark -- --ignored --nocapture"
        );
    let source = PathBuf::from(
        std::env::var("TINE_MANAGED_ACTIVATION_GRAPH_COPY")
            .or_else(|_| std::env::var("TINE_MANAGED_CRASH_REOPEN_GRAPH_COPY"))
            .expect("TINE_MANAGED_ACTIVATION_GRAPH_COPY must name a disposable graph copy"),
    );
    let fixture = ActivationFixture::copied_graph("managed-activation-real", 0xa0d4, &source);
    let receipt = activate_with_scale_receipt(&fixture);
    eprintln!(
            "managed_activation_real total_ms={} source_files={} source_bytes={} blocks={} phases={:?} clean={:?}",
            receipt.total_ms,
            receipt.source_files,
            receipt.source_bytes,
            receipt.blocks,
            receipt.phase_ms,
            receipt.clean,
        );
    assert_eq!(receipt.clean.source_files, receipt.source_files as u64);
    assert!(receipt.clean_marker_present);
    assert!(receipt.retired_artifacts.is_empty(), "{receipt:?}");
    assert_eq!(receipt.operation_batches, 0);
    assert!(
        receipt.total_ms < 10_000,
        "real-graph managed activation exceeded 10 seconds: {receipt:?}"
    );
}

#[test]
#[ignore = "manual MS-08 gate: current parse census and real-corpus SQLite rebuild"]
fn managed_parse_receipt_real_graph_census() {
    assert!(
        !cfg!(debug_assertions),
        "release-only; run with --release --ignored --test-threads=1"
    );
    let source = real_graph_copy_source_from_env("TINE_MANAGED_ACTIVATION_GRAPH_COPY");
    let fixture = ActivationFixture::copied_graph("managed-parse-receipt", 0xa0d8, &source);

    crate::outline::start_managed_parse_census();
    let activation = activate_with_scale_receipt(&fixture);
    let activation_parses = crate::outline::finish_managed_parse_census();
    assert!(
            activation_parses <= activation.source_files,
            "activation must perform at most one parser invocation per source file: parses={activation_parses}, files={}",
            activation.source_files,
        );

    crate::outline::start_managed_parse_census();
    let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    let cold_open_parses = crate::outline::finish_managed_parse_census();
    assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
    assert_eq!(
        cold_open_parses, 0,
        "a healthy cold open must not parse pages"
    );
    let handle = opened.handle.expect("the activated corpus reopens");
    drive_initial_feed_with_turn_budget(&handle, 4096);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    crate::oplog::sqlite::remove_disposable_projection(&fixture.request.database_path).unwrap();
    crate::outline::start_managed_parse_census();
    let rebuild_started = Instant::now();
    let rebuilt = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    let rebuild_ms = rebuild_started.elapsed().as_millis();
    let rebuild_parses = crate::outline::finish_managed_parse_census();
    assert_eq!(rebuilt.status, SyncRuntimeOpenStatus::Active);
    assert_eq!(
        rebuild_parses, 0,
        "a healthy receipted baseline rebuild must not parse source pages"
    );
    assert!(
        rebuild_ms < 10_000,
        "real-corpus SQLite rebuild exceeded 10 seconds: {rebuild_ms} ms"
    );
    let handle = rebuilt.handle.expect("the rebuilt corpus reopens");
    drive_initial_feed_with_turn_budget(&handle, 4096);

    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("the parse census inventory did not load: {other:?}"),
    };
    let (page, revision) = pages
        .iter()
        .find_map(|entry| {
            let (page, revision) = load_application_exact(&handle, &entry.rel_path);
            (!page.blocks.is_empty()).then_some((page, revision))
        })
        .expect("the census corpus has a nonempty page");
    let selected_path = page.path.clone();

    crate::outline::start_managed_parse_census();
    let _ =
        save_application_block_text(&handle, page, revision, "managed parse receipt census edit");
    let foreground_save_parses = crate::outline::finish_managed_parse_census();
    let foreground = handle
        .managed_application_save_instrumentation()
        .expect("the corpus save reports foreground parse accounting");
    eprintln!(
            "managed_parse_receipt_foreground total_parses={} application_stages={:?} guarded_graph_validation_parse_pairs={} graph_wide={:?}",
            foreground_save_parses,
            foreground.application_stages,
            foreground.guarded_graph_validation_parse_pairs,
            foreground.graph_wide,
        );
    assert_eq!(
        foreground
            .application_stages
            .editor_accepted_parses
            .saturating_add(foreground.application_stages.editor_target_parses),
        2,
        "the same-process save lane exceeded its two-parse budget"
    );
    assert!(
            foreground_save_parses <= 2,
            "one-block foreground save exceeded its two-parser-primitive budget: {foreground_save_parses}"
        );

    crate::outline::start_managed_parse_census();
    drain_managed_local(&handle);
    let drain_parses = crate::outline::finish_managed_parse_census();
    assert_eq!(drain_parses, 0, "first managed-local drain reparsed a page");

    let (page, revision) = load_application_exact(&handle, &selected_path);
    crate::outline::start_managed_parse_census();
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "managed parse receipt second census edit",
    );
    let second_foreground_save_parses = crate::outline::finish_managed_parse_census();
    eprintln!(
        "managed_parse_receipt_second_foreground total_parses={second_foreground_save_parses}"
    );
    assert!(
            second_foreground_save_parses <= 2,
            "steady one-block foreground save exceeded its two-parser-primitive budget: {second_foreground_save_parses}"
        );
    crate::outline::start_managed_parse_census();
    drain_managed_local(&handle);
    let second_drain_parses = crate::outline::finish_managed_parse_census();
    assert_eq!(
        second_drain_parses, 0,
        "steady managed-local drain reparsed a page"
    );
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    eprintln!(
            "managed_parse_receipt_census source_files={} activation_parses={} activation_ms={} cold_open_parses={} foreground_save_parses={} drain_parses={} second_foreground_save_parses={} second_drain_parses={} rebuild_parses={} rebuild_ms={}",
            activation.source_files,
            activation_parses,
            activation.total_ms,
            cold_open_parses,
            foreground_save_parses,
            drain_parses,
            second_foreground_save_parses,
            second_drain_parses,
            rebuild_parses,
            rebuild_ms,
        );
}

#[test]
fn terminal_bootstrap_encodes_only_required_frontier_documents() {
    const EVENTS: usize = 6;
    let fixture = ActivationFixture::nested_unicode("terminal-bootstrap-encode-budget", 0xa0da);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("the terminal-bootstrap fixture activates");
    drive_initial_feed(&handle);
    for index in 0..EVENTS {
        let (page, revision) = load_application_exact(&handle, "Root.md");
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            &format!("terminal bootstrap history event {index}"),
        );
        drain_managed_local(&handle);
    }
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    let workspace_id = fixture.request.identities.workspace_id;
    crate::oplog::sqlite::remove_disposable_projection(&fixture.request.database_path).unwrap();
    crate::oplog::sqlite::reset_terminal_bootstrap_encode_accounting_for_test(workspace_id);
    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let accounting =
        crate::oplog::sqlite::terminal_bootstrap_encode_accounting_for_test(workspace_id);
    assert!(
        accounting.required >= EVENTS,
        "the generated accepted history did not reach terminal replay: {accounting:?}",
    );
    assert_eq!(
        accounting.actual, accounting.required,
        "terminal bootstrap encoded replay intermediates beyond its required accepted-batch and exact-terminal documents",
    );
    let handle = reopened.handle.expect("the rebuilt fixture reopens");
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn managed_one_block_save_stays_within_two_parser_passes() {
    let fixture = ActivationFixture::nested_unicode("managed-save-parse-budget", 0xa0d9);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("the parse-budget fixture activates");
    drive_initial_feed(&handle);
    let (page, revision) = load_application_exact(&handle, "Root.md");

    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "managed one-block two-parser-pass budget",
    );
    let stages = handle
        .managed_application_save_instrumentation()
        .expect("the actor reports foreground parse accounting")
        .application_stages;
    assert_eq!(stages.editor_accepted_parses, 1);
    assert_eq!(stages.editor_target_parses, 1);
    assert_eq!(
        stages
            .editor_accepted_parses
            .saturating_add(stages.editor_target_parses),
        2,
        "one-block foreground save must not regain render/response reparses"
    );
    assert_eq!(stages.response_target_exact_dto_reparses, 0);

    drain_managed_local(&handle);
    let (page, revision) = load_application_exact(&handle, "Root.md");
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "managed one-block second parser-pass budget",
    );
    let steady = handle
        .managed_application_save_instrumentation()
        .expect("the actor reports foreground parse accounting")
        .application_stages;
    assert_eq!(steady.editor_accepted_parses, 1);
    assert_eq!(steady.editor_target_parses, 1);
    assert_eq!(steady.response_target_exact_dto_reparses, 0);

    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// The same budget, counted at the parser primitive instead of the save stage.
///
/// This one CANNOT run in the parallel suite, and it is `#[ignore]`d for a
/// reason worth stating: the census arms a process-global counter, and the save
/// it measures does not run on the calling thread — a probe on 2026-09-03 read
/// `global = 1, caller_thread_local = 0`, so the work happens on the runtime
/// actor. A thread-local counter would therefore always read zero and pass
/// vacuously, while the global one counts every OTHER test parsing
/// concurrently. Run alone it reported 2; run inside
/// `cargo test -p tine-core --lib` it reported **34**, and it had been sitting
/// in master's red baseline as noise ever since.
///
/// The sibling test above keeps the live gate, because
/// `managed_application_save_instrumentation` is scoped to one handle and no
/// other test can contribute to it. This test adds what that one cannot see:
/// parser primitives entered below the named stages.
#[test]
#[ignore = "process-global parse census: run with --test-threads=1"]
fn managed_one_block_save_parser_primitive_budget_census() {
    let fixture = ActivationFixture::nested_unicode("managed-save-parse-census", 0xa0d9);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("the parse-budget fixture activates");
    drive_initial_feed(&handle);
    let (page, revision) = load_application_exact(&handle, "Root.md");

    crate::outline::start_managed_parse_census();
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "managed one-block two-parser-pass budget",
    );
    let primitive_parses = crate::outline::finish_managed_parse_census();
    assert!(
        primitive_parses <= 2,
        "one-block foreground save exceeded its two-parser-primitive budget: {primitive_parses}"
    );

    drain_managed_local(&handle);
    let (page, revision) = load_application_exact(&handle, "Root.md");
    crate::outline::start_managed_parse_census();
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "managed one-block second parser-pass budget",
    );
    let second_primitive_parses = crate::outline::finish_managed_parse_census();
    assert!(
        second_primitive_parses <= 2,
        "steady one-block foreground save exceeded its two-parser-primitive budget: {second_primitive_parses}"
    );
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// A process-global counter cannot be read from a parallel test runner.
///
/// The managed parse census arms one `AtomicUsize` for the whole process, so
/// any test that reads it also counts every unrelated test parsing at the same
/// moment. `managed_one_block_save_stays_within_two_parser_passes` used to do
/// exactly that and reported 2 alone but **34** inside
/// `cargo test -p tine-core --lib` — it lived in master's red baseline as noise
/// until 2026-09-03. The counter is not broken; reading it from a parallel test
/// is.
///
/// So: every consumer of the census is `#[ignore]`d and run with
/// `--test-threads=1`. If you need a budget assertion in the ordinary suite,
/// use `managed_application_save_instrumentation()` instead — it is scoped to
/// one handle, so no other test can contribute to it. The exemplar pair is
/// `managed_one_block_save_stays_within_two_parser_passes` (live, per-handle)
/// and `managed_one_block_save_parser_primitive_budget_census` (ignored,
/// process-global).
#[test]
fn every_managed_parse_census_consumer_is_ignored_from_the_parallel_suite() {
    let source = include_str!("sync_runtime_tests.rs");
    let lines: Vec<&str> = source.lines().collect();
    let mut offenders = Vec::new();

    // Split so this scanner's own source does not match itself.
    let census_call = concat!("start_managed", "_parse_census()");
    for (index, line) in lines.iter().enumerate() {
        if !line.contains(census_call) {
            continue;
        }
        // Walk back to the enclosing `fn`, then over its attributes.
        let Some(signature) = (0..index)
            .rev()
            .find(|candidate| lines[*candidate].starts_with("fn "))
        else {
            continue;
        };
        let mut attribute = signature;
        let mut ignored = false;
        while attribute > 0 && lines[attribute - 1].starts_with("#[") {
            attribute -= 1;
            ignored |= lines[attribute].starts_with("#[ignore");
        }
        if !ignored {
            offenders.push(format!(
                "{} (census read at line {})",
                lines[signature].trim(),
                index + 1
            ));
        }
    }

    offenders.dedup();
    assert!(
        offenders.is_empty(),
        "the managed parse census is a PROCESS-GLOBAL counter and these tests read it \
         from the parallel suite, so they also count unrelated tests' parses: {offenders:#?}. \
         Add #[ignore = \"process-global parse census: run with --test-threads=1\"], or assert \
         on managed_application_save_instrumentation() instead — it is scoped to one handle. \
         Imitate managed_one_block_save_stays_within_two_parser_passes."
    );
}

fn assert_search_index_matches_materialized_sources(database_path: &Path) {
    let connection = rusqlite::Connection::open(database_path).unwrap();
    let phase: i64 = connection
        .query_row(
            "SELECT phase FROM search_fts_build WHERE singleton = 1",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(phase, 1, "the corpus FTS differential requires readiness");
    let outbox: i64 = connection
        .query_row("SELECT COUNT(*) FROM search_fts_outbox", [], |row| {
            row.get(0)
        })
        .unwrap();
    assert_eq!(outbox, 0, "a ready corpus index retained catch-up rows");

    let expected = "SELECT 0 AS entity_type, page_id AS entity_id, page_id,
                               searchable_text AS text,
                               normalized_searchable_text AS normalized_text
                        FROM pages
                        UNION ALL
                        SELECT 1 AS entity_type, block_id AS entity_id, page_id,
                               searchable_text AS text,
                               normalized_searchable_text AS normalized_text
                        FROM blocks";
    let standard = "SELECT owner.entity_type, owner.entity_id, owner.page_id,
                                fts.text, fts.normalized_text
                         FROM search_fts_owners AS owner
                         JOIN search_fts AS fts ON fts.rowid = owner.rowid";
    let substring = "SELECT owner.entity_type, owner.entity_id, owner.page_id,
                                 source.text, substring.normalized_text
                          FROM search_fts_owners AS owner
                          JOIN search_substring_fts AS substring
                            ON substring.rowid = owner.rowid
                          JOIN (
                              SELECT 0 AS entity_type, page_id AS entity_id,
                                     page_id, searchable_text AS text
                              FROM pages
                              UNION ALL
                              SELECT 1 AS entity_type, block_id AS entity_id,
                                     page_id, searchable_text AS text
                              FROM blocks
                          ) AS source
                            ON source.entity_type = owner.entity_type
                           AND source.entity_id = owner.entity_id";
    let count = |sql: String| -> i64 { connection.query_row(&sql, [], |row| row.get(0)).unwrap() };
    for (family, actual) in [("standard", standard), ("substring", substring)] {
        let missing = count(format!(
            "SELECT COUNT(*) FROM (SELECT * FROM ({expected}) EXCEPT SELECT * FROM ({actual}))"
        ));
        let extra = count(format!(
            "SELECT COUNT(*) FROM (SELECT * FROM ({actual}) EXCEPT SELECT * FROM ({expected}))"
        ));
        assert_eq!(
            (missing, extra),
            (0, 0),
            "{family} FTS differs from the authoritative materialized corpus rows"
        );
    }
}

fn drive_search_index_to_ready(handle: &SyncRuntimeHandle, turn_budget: usize) {
    for _ in 0..turn_budget {
        if !handle.status().unwrap().search_index_building {
            return;
        }
        let tick = handle.tick().unwrap();
        assert!(
            !matches!(
                tick,
                SyncRuntimeTick::Failed(_)
                    | SyncRuntimeTick::Blocked(_)
                    | SyncRuntimeTick::RecoveryBlocked(_)
                    | SyncRuntimeTick::Terminal(_)
            ),
            "the FTS build failed: {tick:?}"
        );
    }
    panic!("the FTS build exceeded its bounded turn budget");
}

/// Private-corpus counterpart to tine-storage's permanent synthetic
/// differential. The source graph is copied before activation; this test
/// never prints corpus content and mutates only that disposable copy.
#[test]
#[ignore = "manual gate: lazy and delta FTS differential on an anonymized corpus copy"]
fn managed_search_index_real_corpus_differential() {
    let source = real_graph_copy_source_from_env("TINE_MANAGED_ACTIVATION_GRAPH_COPY");
    let fixture = ActivationFixture::copied_graph("managed-search-fts-corpus", 0xf750, &source);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("the corpus copy activates");
    drive_initial_feed_with_turn_budget(&handle, 4096);
    drive_search_index_to_ready(&handle, 4096);
    assert_search_index_matches_materialized_sources(&fixture.request.database_path);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    assert_search_index_matches_materialized_sources(&fixture.request.database_path);

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let handle = reopened.handle.expect("the indexed corpus copy reopens");
    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("corpus inventory did not load: {other:?}"),
    };
    let (page, revision) = pages
        .iter()
        .find_map(|entry| {
            let loaded = load_application_exact(&handle, &entry.rel_path);
            (!loaded.0.blocks.is_empty()).then_some(loaded)
        })
        .expect("the corpus copy has an editable block");
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "ms07 corpus delta-maintenance probe",
    );
    drain_managed_local(&handle);
    drive_search_index_to_ready(&handle, 4096);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    assert_search_index_matches_materialized_sources(&fixture.request.database_path);
}

#[test]
#[ignore = "manual release benchmark: 20-page live-save and crash-reopen history curve"]
fn managed_twenty_page_history_curve_manual_benchmark() {
    assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release --lib managed_twenty_page_history_curve_manual_benchmark -- --ignored --nocapture"
        );
    let rounds = std::env::var("TINE_MANAGED_HISTORY_CURVE_ROUNDS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(32);
    // nested_unicode contributes exactly three page files; add seventeen
    // more so graph size remains fixed while only accepted history grows.
    let fixture = ActivationFixture::scaled("managed-history-curve-20", 0xa0e6, 17);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("20-page graph activates");
    drive_initial_feed(&handle);

    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("managed page inventory did not load: {other:?}"),
    };
    assert_eq!(pages.len(), 20, "fixture must remain exactly 20 pages");
    let mut editable = pages
        .into_iter()
        .map(|entry| entry.rel_path)
        .filter(|path| !load_application_exact(&handle, path).0.blocks.is_empty())
        .collect::<Vec<_>>();
    editable.sort();
    assert!(!editable.is_empty(), "20-page fixture has no editable page");

    let mut save_ms = Vec::with_capacity(rounds);
    for round in 0..rounds {
        let path = &editable[round % editable.len()];
        let (page, revision) = load_application_exact(&handle, path);
        let started = Instant::now();
        let _ = save_application_block_text(
            &handle,
            page,
            revision,
            &format!("20-page history curve edit {round}"),
        );
        drain_managed_local(&handle);
        save_ms.push(startup_ms(started.elapsed()));
    }

    let pending_path = editable[rounds % editable.len()].clone();
    let (page, revision) = load_application_exact(&handle, &pending_path);
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "20-page history curve pending edit",
    );
    assert_eq!(handle.status().unwrap().managed_local_pending, 1);
    drop(handle);

    let started = Instant::now();
    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    let reopen_ms = startup_ms(started.elapsed());
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let reopened = reopened.handle.expect("20-page aged history reopens");
    let (page, _) = load_application_exact(&reopened, &pending_path);
    assert_eq!(page.blocks[0].raw, "20-page history curve pending edit");
    let tail = save_ms.len().min(10);
    let tail_mean_ms = save_ms[save_ms.len() - tail..].iter().sum::<f64>() / tail as f64;
    eprintln!(
            "managed_twenty_page_history_curve rounds={rounds} last_save_ms={:.3} tail10_mean_ms={tail_mean_ms:.3} reopen_ms={reopen_ms:.3}",
            save_ms[save_ms.len() - 1],
        );
    assert!(matches!(
        reopened.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// Reproduce the managed crash-reopen aging curve and attribute it to a stage.
///
/// The graph stays exactly 20 pages; only accepted history grows, so every
/// difference between checkpoints is lifetime cost (I-14). One process
/// invocation walks all checkpoints so per-stage SHARES and growth factors are
/// comparable even on a machine running other work; absolute milliseconds
/// across separate runs are not.
///
/// `TINE_MANAGED_OPEN_ATTRIBUTION_CHECKPOINTS` (default `50,200,400,800`) sets the
/// accepted-batch checkpoints. Output lines are prefixed `attribution*` and
/// are machine-readable for `scripts/harvest-a1-open-attribution.mjs`.
///
/// Martin accepted option (a) on 2026-09-02: checkpoint capture itself remains
/// a hard per-save delta bound even though the older open ratios were accepted
/// with archive rebaselining as their terminal bound.
const A5_ACCEPTED_CAPTURE_RATIO: f64 = 1.25;

const A3_CONFLICT_LOAD_SLOPE: usize = 8;
const A3_CONFLICT_LOAD_INTERCEPT: usize = 64;

#[test]
fn accepted_capture_ratio_and_contract_are_pinned_to_the_same_value() {
    let contract = include_str!("../../../docs/storage-sync-contract.md");
    let pinned = format!("A5_ACCEPTED_CAPTURE_RATIO = {A5_ACCEPTED_CAPTURE_RATIO}");
    assert!(
        contract.contains(&pinned),
        "I-11: the accepted-history capture-ratio gate and storage contract must pin the same constant and value"
    );
}

