fn managed_application_save_page_local_read_bound(blocks: usize) -> usize {
    // The retained CRDT transaction can touch two authenticated points per
    // block on its first page-shaped edit, plus four page-level points.
    // This is intentionally a bound on the edited page, never graph size.
    blocks.saturating_mul(2).saturating_add(4)
}

fn assert_managed_application_save_foreground_counters(
    before: ManagedApplicationSaveInstrumentation,
    after: ManagedApplicationSaveInstrumentation,
    page_blocks: usize,
) -> ManagedApplicationSavePageLocalReads {
    let forbidden = after.forbidden.since(before.forbidden);
    assert!(
        forbidden.is_none(),
        "ordinary application save performed forbidden foreground work: {forbidden:?}"
    );
    assert_eq!(
        after.graph_wide.since(before.graph_wide),
        GraphWideCommitWork::default(),
        "ordinary application save performed graph-wide foreground work"
    );

    let before_engine = before.engine;
    let after_engine = after.engine;
    assert_eq!(
        after_engine.catalog_hot_state_loads, before_engine.catalog_hot_state_loads,
        "warm ordinary save must not materialize the catalog"
    );
    assert_eq!(
        after_engine.prospective_catalog_shape_entry_visits,
        before_engine.prospective_catalog_shape_entry_visits,
        "ordinary application save must not visit unrelated catalog entries while drafting"
    );
    assert_eq!(
        after_engine.drain_candidate_visits, before_engine.drain_candidate_visits,
        "ordinary application save must not visit tail-drain candidates"
    );
    assert_eq!(
        after_engine.external_flushes, before_engine.external_flushes,
        "ordinary application save must not flush external archive state"
    );
    assert_eq!(
        after_engine.external_range_scans, before_engine.external_range_scans,
        "ordinary application save must not scan external archive state"
    );
    assert_eq!(
        (
            after_engine.store.directory_enumerations,
            after_engine.store.accepted_manifest_reads,
            after_engine.store.accepted_object_reads,
            after_engine.store.dag_manifest_reads,
            after_engine.store.inspected_manifest_operations,
            after_engine.store.inspected_manifest_bytes,
            after_engine.store.inspected_object_operations,
            after_engine.store.inspected_object_bytes,
        ),
        (
            before_engine.store.directory_enumerations,
            before_engine.store.accepted_manifest_reads,
            before_engine.store.accepted_object_reads,
            before_engine.store.dag_manifest_reads,
            before_engine.store.inspected_manifest_operations,
            before_engine.store.inspected_manifest_bytes,
            before_engine.store.inspected_object_operations,
            before_engine.store.inspected_object_bytes,
        ),
        "ordinary application save must not enumerate or inspect archive state"
    );
    let page_local_reads = ManagedApplicationSavePageLocalReads {
        external_points: after_engine
            .external_point_reads
            .saturating_sub(before_engine.external_point_reads),
        history_points: after_engine
            .external_history_page_reads
            .saturating_sub(before_engine.external_history_page_reads)
            .saturating_add(
                after_engine
                    .external_history_blob_reads
                    .saturating_sub(before_engine.external_history_blob_reads),
            ),
    };
    let point_bound = managed_application_save_page_local_read_bound(page_blocks);
    // Each point proof can decode both its history index and record, so
    // the corresponding history counter has a fixed two-to-one ceiling.
    let history_bound = point_bound.saturating_mul(2);
    assert!(
            page_local_reads.external_points <= point_bound,
            "ordinary application save exceeded its page-local external-point read bound: {page_local_reads:?}, blocks={page_blocks}, bound={point_bound}"
        );
    assert!(
            page_local_reads.history_points <= history_bound,
            "ordinary application save exceeded its page-local history read bound: {page_local_reads:?}, blocks={page_blocks}, bound={history_bound}"
        );
    page_local_reads
}

/// The rebuild's own work counters. A rebuild that is superlinear in graph
/// size is superlinear in one of these, and elapsed time alone cannot say
/// which -- so the receipt names the quantities rather than the duration.
fn startup_projection_rebuild_receipt(
    rebuild: &crate::oplog::sqlite::RebuildInstrumentation,
) -> String {
    format!(
            " rebuild_events_validated={} rebuild_events_applied={} rebuild_root_authentications={} rebuild_exact_document_loads={} rebuild_exact_catalog_loads={} rebuild_exact_catalog_decodes={} rebuild_bulk_chunks={} rebuild_peak_bulk_pages={} rebuild_sequence_page_reads={} rebuild_sequence_bytes_read={} rebuild_cleanup_page_attempts={} rebuild_cleanup_existing_pages={} rebuild_cleanup_owned_rows={} rebuild_cleanup_fts_rowids={} rebuild_semantic_proofs={} rebuild_row_digest_proofs={} rebuild_frontier_session_hits={} rebuild_frontier_session_misses={} rebuild_external_session_hits={} rebuild_external_session_misses={} rebuild_candidate_transactions={} rebuild_candidate_barriers={} rebuild_ordinary_transactions={} rebuild_ordinary_barriers={}",
            rebuild.accepted_events_validated,
            rebuild.accepted_events_applied,
            rebuild.accepted_root_authentications,
            rebuild.exact_document_loads,
            rebuild.exact_catalog_loads,
            rebuild.exact_catalog_decodes,
            rebuild.bulk_materialization_chunks,
            rebuild.peak_bulk_pages,
            rebuild.accepted_sequence_page_reads,
            rebuild.accepted_sequence_bytes_read,
            rebuild.cleanup_page_attempts,
            rebuild.cleanup_existing_pages,
            rebuild.cleanup_owned_rows,
            rebuild.cleanup_fts_rowids,
            rebuild.final_semantic_equivalence_proofs,
            rebuild.final_row_digest_equivalence_proofs,
            rebuild.accepted_frontier_session_hits,
            rebuild.accepted_frontier_session_misses,
            rebuild.external_exact_session_hits,
            rebuild.external_exact_session_misses,
            rebuild.physical_candidate_transactions,
            rebuild.physical_candidate_durability_barriers,
            rebuild.physical_ordinary_transactions,
            rebuild.physical_ordinary_durability_barriers,
        )
}

fn startup_projection_open_test_receipt(observation: &ProjectionOpenTestObservation) -> String {
    format!(
        "projection_recovery={} projection_rebuild_reason={:?}",
        observation.recovery, observation.reason,
    ) + &startup_projection_rebuild_receipt(&observation.rebuild)
}

#[test]
#[ignore = "manual release benchmark: settled broad reconciliation and safe shutdown"]
fn managed_reconciliation_and_shutdown_manual_benchmark() {
    assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run cargo test -p tine-core --release managed_reconciliation_and_shutdown_manual_benchmark -- --ignored --nocapture"
        );
    let total_pages = std::env::var("TINE_MANAGED_RECONCILIATION_BENCH_PAGES")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|pages| *pages >= 4)
        .unwrap_or(1_000);
    let blocks_per_page = std::env::var("TINE_MANAGED_RECONCILIATION_BENCH_BLOCKS_PER_PAGE")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|blocks| *blocks > 0)
        .unwrap_or(1);
    let fixture = ActivationFixture::scaled_with_blocks(
        &format!("managed-reconciliation-{total_pages}"),
        0xa0fa + total_pages as u128,
        total_pages - 3,
        blocks_per_page,
    );
    let exact_source = user_graph_bytes(&fixture.graph_root);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation retains a runtime");
    // The fixture deliberately scales to 10,000 pages. Its initial exact
    // feed is page-bounded, so the fixed small-fixture helper would reject
    // the intended large case before the measured reconciliation begins.
    drive_initial_feed_with_turn_budget(&handle, total_pages.saturating_add(128));

    handle
        .observe_watcher(vec![SyncWatcherObservation::RescanRequired])
        .unwrap();
    let reconciliation_started = Instant::now();
    let mut turns = 0usize;
    while handle.status().unwrap().watcher.pending {
        turns = turns.saturating_add(1);
        assert!(
            turns <= 1_024,
            "settled broad reconciliation exceeded the bounded turn budget"
        );
        match handle.tick().unwrap() {
            SyncRuntimeTick::Terminal(detail) | SyncRuntimeTick::Failed(detail) => {
                panic!("settled broad reconciliation failed: {detail}")
            }
            _ => {}
        }
    }
    let reconciliation = reconciliation_started.elapsed();
    assert_eq!(
        user_graph_bytes(&fixture.graph_root),
        exact_source,
        "settled reconciliation must preserve every graph byte"
    );

    let shutdown_started = Instant::now();
    let shutdown = handle.clean_shutdown();
    let shutdown_elapsed = shutdown_started.elapsed();
    assert!(matches!(shutdown, Ok(SyncShutdownOutcome::Safe(_))));
    assert_eq!(
        user_graph_bytes(&fixture.graph_root),
        exact_source,
        "safe shutdown after reconciliation must preserve every graph byte"
    );
    eprintln!(
            "managed_reconciliation_shutdown_bench total_pages={} blocks_per_page={} turns={} reconciliation_ms={:.3} shutdown_ms={:.3}",
            total_pages,
            blocks_per_page,
            turns,
            startup_ms(reconciliation),
            startup_ms(shutdown_elapsed),
        );
    let reconciliation_ceiling = Duration::from_millis(
        (total_pages as u64)
            .div_ceil(1_000)
            .saturating_mul(300)
            .max(500),
    );
    assert!(
            reconciliation < reconciliation_ceiling,
            "settled broad reconciliation exceeded its linear ceiling at {total_pages} pages: elapsed={reconciliation:?}, ceiling={reconciliation_ceiling:?}"
        );
    assert!(
            shutdown_elapsed < Duration::from_millis(300),
            "safe shutdown exceeded 300 ms after settled reconciliation at {total_pages} pages: {shutdown_elapsed:?}"
        );
}

/// Age a graph, shut it down cleanly, then damage only the disposable
/// SQLite projection. The oplog is untouched and authoritative, so the
/// graph must still open.
///
/// `damage` runs with the runtime stopped and returns what the projection
/// recovery is expected to report.
fn managed_safe_reopen_after_projection_damage(
    name: &str,
    seed: u128,
    damage: impl FnOnce(&Path),
    expect_replaced_file: bool,
    expected_forensic_bytes: Option<&[u8]>,
) {
    let fixture = ActivationFixture::nested_unicode(name, seed);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("synthetic graph activates");
    drive_initial_feed(&handle);

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let _ = save_application_block_text(&handle, page, revision, "edit before the damage");
    for _ in 0..512 {
        if handle.status().unwrap().managed_local_pending == 0 {
            break;
        }
        handle.tick().unwrap();
    }
    assert_eq!(
        handle.status().unwrap().managed_local_pending,
        0,
        "the pre-damage edit must drain, so the projection is current at shutdown"
    );
    assert!(
        matches!(handle.clean_shutdown(), Ok(SyncShutdownOutcome::Safe(_))),
        "the graph must reach a Safe handoff, which is the case this covers"
    );
    drop(handle);

    let database_path = &fixture.request.database_path;
    let forensic_prefix = format!(
        "{}.forensic-",
        database_path.file_name().unwrap().to_string_lossy()
    );
    let forensic_directories = || {
        fs::read_dir(database_path.parent().unwrap())
            .unwrap()
            .map(Result::unwrap)
            .filter(|entry| {
                entry.file_type().unwrap().is_dir()
                    && entry
                        .file_name()
                        .to_string_lossy()
                        .starts_with(&forensic_prefix)
            })
            .map(|entry| entry.path())
            .collect::<Vec<_>>()
    };
    assert!(
        forensic_directories().is_empty(),
        "the fixture starts without projection forensic evidence"
    );

    let original_link = database_path.with_extension("pre-damage.sqlite");
    if expect_replaced_file {
        fs::hard_link(database_path, &original_link)
            .expect("the negative-control link retains the original projection inode");
    }

    damage(database_path);

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(
        reopened.status,
        SyncRuntimeOpenStatus::Active,
        "a damaged disposable projection must not make an authoritative oplog unopenable"
    );
    let forensics = forensic_directories();
    if expect_replaced_file {
        assert!(
                !same_file::is_same_file(&original_link, database_path).unwrap(),
                "the missing projection path was not replaced; this oracle must fail when deletion is skipped"
            );
        fs::remove_file(&original_link).unwrap();
    }
    match expected_forensic_bytes {
        None => {
            assert!(
                database_path.is_file(),
                "the projection database was recreated"
            );
            assert!(
                forensics.is_empty(),
                "a missing disposable projection has no damaged bytes to preserve"
            );
        }
        Some(expected) => {
            assert_eq!(
                forensics.len(),
                1,
                "one damaged projection file set is preserved"
            );
            let forensic = &forensics[0];
            assert!(forensic.join("EVIDENCE_COMPLETE").is_file());
            assert!(forensic.join("REBUILD_COMPLETE").is_file());
            assert!(
                recursive_file_bytes(forensic)
                    .values()
                    .any(|bytes| bytes.as_slice() == expected),
                "the exact damaged projection bytes survive in forensic evidence"
            );
        }
    }

    // Opening is not the whole claim: the rebuilt projection must actually
    // answer for the graph, including the edit made before the damage.
    let handle = reopened
        .handle
        .expect("the reopened runtime retains a handle");
    let (page, _) = load_application_exact(&handle, "Root.md");
    assert!(
        page.blocks
            .iter()
            .any(|block| block.raw.contains("edit before the damage")),
        "the rebuilt projection lost an accepted, drained edit"
    );
    drop(handle);
}

/// A cleanly shut down graph whose disposable projection has been deleted
/// -- a cleared cache directory, a sweeper, a restore that skipped it.
///
/// The crash path already rebuilds this exact state. Refusing it after a
/// *clean* shutdown made the tidier lifecycle the unrecoverable one, and
/// the refusal is reported to the frontend as `Retryable`, so the user gets
/// a retry button that cannot ever succeed.
#[test]
fn managed_safe_reopen_rebuilds_a_deleted_disposable_projection() {
    managed_safe_reopen_after_projection_damage(
        "managed-safe-reopen-deleted-projection",
        0xa0ea,
        |database_path| {
            tine_storage::sqlite::SqliteFileSet::new(database_path)
                .remove()
                .expect("the projection file set is removable");
        },
        true,
        None,
    );
}

/// The same graph whose projection file is present but unreadable. This is
/// the shape a schema-version bump or genuine corruption takes, and unlike
/// deletion it also has forensic evidence to preserve.
#[test]
fn managed_safe_reopen_rebuilds_an_unreadable_disposable_projection() {
    managed_safe_reopen_after_projection_damage(
        "managed-safe-reopen-unreadable-projection",
        0xa0eb,
        |database_path| {
            fs::write(database_path, b"this is not a SQLite database")
                .expect("the projection file is writable");
        },
        false,
        Some(b"this is not a SQLite database"),
    );
}

/// Clean composition has no separate reconciliation database. The
/// accepted operation archive plus disposable SQLite projection replace
/// that legacy authority; reintroducing a second baseline would recreate
/// two independently recoverable views of the same graph.
#[test]
fn clean_runtime_does_not_publish_a_legacy_reconciliation_baseline() {
    let fixture = ActivationFixture::nested_unicode(
        "clean-runtime-no-legacy-reconciliation-baseline",
        0xa0ec,
    );
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("synthetic graph activates");
    drive_initial_feed(&handle);

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "accepted before baseline corruption",
    );
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(handle);

    const LEGACY_RECONCILIATION_DIR: &str = "reconciliation";
    let legacy_baseline_root = fixture
        .request
        .application_runtime_root
        .join(LEGACY_RECONCILIATION_DIR)
        .join(fixture.request.identities.workspace_id.to_string())
        .join(fixture.request.identities.endpoint_id.to_string());
    assert!(
        !legacy_baseline_root.exists(),
        "clean runtime must not recreate a separately recoverable reconciliation database"
    );
    let archive_before = immutable_archive_bytes(&fixture.request.archive_root);

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(
        reopened.status,
        SyncRuntimeOpenStatus::Active,
        "absence of the retired reconciliation database must not refuse the graph"
    );
    let handle = reopened
        .handle
        .expect("the recovered graph retains a handle");
    let (page, _) = load_application_exact(&handle, "Root.md");
    assert!(
        page.blocks
            .iter()
            .any(|block| block.raw.contains("accepted before baseline corruption")),
        "baseline recovery lost an accepted edit"
    );
    assert_eq!(
        immutable_archive_bytes(&fixture.request.archive_root),
        archive_before,
        "rebuilding a disposable baseline may not rewrite authoritative history"
    );
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    assert!(!legacy_baseline_root.exists());
}

/// Clean runtimes deliberately do not publish the enrolled runtime's
/// engine-history resume authority. A test which selected and corrupted a
/// run through that directory became test rot when the clean composition
/// replaced the enrolled open path.
#[test]
fn clean_runtime_does_not_publish_legacy_retained_scratch_resume_authority() {
    let fixture = ActivationFixture::nested_unicode(
        "clean-runtime-has-no-legacy-retained-scratch-resume-authority",
        0xa0ed,
    );
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("synthetic graph activates");
    drive_initial_feed(&handle);

    let (page, revision) = load_application_exact(&handle, "Root.md");
    let _ = save_application_block_text(
        &handle,
        page,
        revision,
        "accepted without legacy retained scratch authority",
    );
    drain_managed_local(&handle);
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(handle);

    assert!(
        !fixture.request.archive_root.join("engine-history").exists(),
        "clean runtime must not recreate the enrolled engine-history authority"
    );
    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let reopened = reopened.handle.expect("clean runtime reopens");
    let (page, _) = load_application_exact(&reopened, "Root.md");
    assert!(page.blocks.iter().any(|block| block
        .raw
        .contains("accepted without legacy retained scratch authority")));
    drop(reopened);
}

/// Only a tick that committed a batch may be reported as a content change.
///
/// The two admitted variants were treated alike, so a drain that took no
/// completed batch still told the frontend the graph had changed. That
/// contentless signal, arriving while a page was dirty, is what produced a
/// conflict against nothing -- the false-conflict incident of 2026-08-06.
#[test]
fn only_a_committing_tick_reports_an_observable_change() {
    assert!(SyncRuntimeTick::AdmittedComplete { epoch: 7 }.committed_observable_change());
    assert!(
        SyncRuntimeTick::ProviderMutation {
            batch_id: BatchId::from_uuid(Uuid::from_u128(7)),
        }
        .committed_observable_change(),
        "a provider batch reflected in SQLite and Markdown must wake live readers"
    );
    assert!(
        !SyncRuntimeTick::AdmittedNoop { epoch: 7 }.committed_observable_change(),
        "an admission that took no completed batch is not a content change"
    );
    for quiet in [
        SyncRuntimeTick::Idle,
        SyncRuntimeTick::Recovering,
        SyncRuntimeTick::RetryFull,
        SyncRuntimeTick::Blocked("blocked".into()),
        SyncRuntimeTick::RecoveryBlocked("blocked".into()),
        SyncRuntimeTick::Failed("failed".into()),
        SyncRuntimeTick::Terminal("terminal".into()),
    ] {
        assert!(
            !quiet.committed_observable_change(),
            "{quiet:?} committed nothing and must not be reported as a change"
        );
    }
}

/// A clean-genesis rebuild must restore the complete immutable baseline.
///
/// This asserts the mechanism, not a duration, because the defect it guards
/// is invisible in a single measurement: with the sessions unthreaded every
/// document resolution re-walked the scratch LSM from the top, so
/// per-document cost grew with the graph and a rebuild visiting a linear
/// number of documents came out at about n^1.6. Clean activation no longer
/// retains that scratch authority: genesis is reconstructed from its
/// immutable baseline. The retired retained-root counters no longer
/// describe this path; the real-scale wall-clock benchmark below covers
/// its separate performance property.
#[test]
fn clean_cold_reopen_reuses_the_authenticated_genesis_projection() {
    let fixture = ActivationFixture::scaled("clean-cold-reopen-reuses-projection", 0xa0eb, 3);
    let workspace_id = fixture.request.identities.workspace_id;
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("scaled graph activates");
    drive_initial_feed(&handle);
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(handle);

    reset_projection_open_test_observation(workspace_id);
    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let observation = take_projection_open_test_observation(workspace_id);
    assert_eq!(
        observation.recovery, "opened-existing",
        "an unchanged clean projection was rebuilt: {}",
        observation.reason
    );
}

