/// The Direct/managed differential for the shared block evaluator.
///
/// One corpus, four evaluator shapes, both storage modes: a plain-text
/// whole-graph search, the literal fuzzy `((` block picker, the same search
/// under a small `limit` (which is what makes evidence and DTO construction
/// happen per winner rather than per retained candidate), and byte- and
/// row-bounded block referrers swept ACROSS their truncation boundary.
///
/// The budget sweep is the necessity gate for the accounting fix: Direct
/// charges payload + page name + 256 per admitted row and latches
/// `exceeded`, and the managed referrer loop used to probe a per-group
/// overhead per row while accumulating it once per emitted group -- so the
/// same `max_bytes` admitted a different number of rows on the two paths.
#[test]
fn managed_query_evaluator_matches_direct_files_across_shapes_and_budgets() {
    let fixture = mode_differential_fixture("mode-differential-evaluator", 0xa3f8);
    let direct = Graph::open(&fixture.graph_root);
    let handle = open_reopened_managed_actor(&fixture);

    // 1. Plain-text whole-graph search: page branch plus block branch.
    assert_managed_graph_search_matches_direct(
        "plain text graph search",
        managed_graph_search(&handle, "differential needle", 5, 50),
        direct.run_graph_search("differential needle", 5, 50, false),
    );

    // 2. Literal fuzzy search -- the `((` block picker. `zqx` occurs on
    // exactly one page, so this also proves the managed narrowing returns
    // the same answer the unnarrowed Direct scan does.
    drive_search_index_to_ready(&handle, 4096);
    handle
        .reset_managed_application_query_instrumentation()
        .unwrap();
    assert_managed_block_groups_match_direct(
        "literal fuzzy block search",
        managed_block_search(&handle, "zqx sentinel", 10),
        direct.search("zqx sentinel", 10),
    );
    let counters = handle.managed_application_query_instrumentation().unwrap();
    assert_eq!(
        counters.fuzzy_narrowing_passes, 1,
        "a literal fuzzy block search must consult the managed candidate index: {counters:?}"
    );
    assert_eq!(
        counters.fuzzy_candidate_pages, 1,
        "`zqx` occurs on one page, so narrowing must select one page: {counters:?}"
    );
    assert_eq!(
        counters.result_page_hydrations, 1,
        "a narrowed fuzzy search must hydrate only its candidate pages: {counters:?}"
    );

    // A needle that is nowhere in the graph narrows to nothing, and both
    // modes answer empty rather than one of them scanning everything.
    handle
        .reset_managed_application_query_instrumentation()
        .unwrap();
    assert_managed_block_groups_match_direct(
        "literal fuzzy block search with no candidates",
        managed_block_search(&handle, "zzqqxxjj", 10),
        direct.search("zzqqxxjj", 10),
    );
    let counters = handle.managed_application_query_instrumentation().unwrap();
    assert_eq!(counters.fuzzy_candidate_pages, 0, "{counters:?}");
    assert_eq!(counters.result_page_hydrations, 0, "{counters:?}");

    // 3. Limit-bounded search: the heap keeps `limit` winners and the tie
    // break decides which. Sweep the limit across the result size so an
    // off-by-one in the retention rule cannot hide.
    for limit in [1_usize, 2, 3, 7, 11] {
        assert_managed_graph_search_matches_direct(
            &format!("limit-bounded graph search limit={limit}"),
            managed_graph_search(&handle, "differential needle", 0, limit),
            direct.run_graph_search("differential needle", 0, limit, false),
        );
    }

    // 4. Bounded block referrers, swept across the truncation boundary.
    // The managed request surface caps both bounds, so "unbounded" here is
    // the largest request a caller can actually make.
    const MAX_ROWS: usize = MAX_SYNC_APPLICATION_RESULT_ROWS;
    const MAX_BYTES: usize = MAX_SYNC_APPLICATION_RESULT_BYTES;
    let unbounded_direct =
        direct.block_referrers_bounded(MODE_DIFFERENTIAL_ANCHOR, MAX_ROWS, MAX_BYTES);
    let unbounded_managed =
        managed_block_referrers(&handle, MODE_DIFFERENTIAL_ANCHOR, MAX_ROWS, MAX_BYTES);
    assert_eq!(
        unbounded_direct.total,
        MODE_DIFFERENTIAL_PAGES * 4,
        "the differential corpus must produce one referrer per referring child"
    );
    assert_managed_simple_query_matches_direct(
        "block referrers unbounded",
        unbounded_managed.clone(),
        unbounded_direct.clone(),
    );

    // The two modes charge the SAME rule -- payload + page name + 256 per
    // admitted row, `exceeded` latched -- to inputs that legitimately
    // differ: a managed block carries frontend identity (a Logseq UUID or
    // its managed internal fallback) where a Direct block carries its
    // structural runtime id, and the payload estimate counts that identity.
    // So the meaningful parity claim is not "the same integer admits the
    // same rows" but "the budget that admits k rows admits the SAME k rows,
    // and admits exactly k". Predicting each mode's boundary from the
    // shared rule and then checking it is what makes this a real gate: the
    // superseded managed accounting, which probed a per-group overhead per
    // row and accumulated it once per emitted group, admits a different
    // count than the rule predicts as soon as more than one group is
    // involved.
    let row_costs = |result: &[RefGroup]| {
        result
            .iter()
            .flat_map(|group| {
                group.blocks.iter().map(|block| {
                    crate::model::block_dto_estimated_bytes(block)
                        .saturating_add(group.page.len())
                        .saturating_add(256)
                })
            })
            .collect::<Vec<_>>()
    };
    let direct_costs = row_costs(&unbounded_direct.groups);
    let managed_costs = row_costs(&unbounded_managed.groups);
    assert_eq!(direct_costs.len(), managed_costs.len());
    let prefix_sums = |costs: &[usize]| {
        costs
            .iter()
            .scan(0_usize, |running, cost| {
                *running = running.saturating_add(*cost);
                Some(*running)
            })
            .collect::<Vec<_>>()
    };
    let direct_boundaries = prefix_sums(&direct_costs);
    let managed_boundaries = prefix_sums(&managed_costs);
    for admitted in 1..=direct_boundaries.len() {
        let managed = managed_block_referrers(
            &handle,
            MODE_DIFFERENTIAL_ANCHOR,
            MAX_ROWS,
            managed_boundaries[admitted - 1],
        );
        let direct_bounded = direct.block_referrers_bounded(
            MODE_DIFFERENTIAL_ANCHOR,
            MAX_ROWS,
            direct_boundaries[admitted - 1],
        );
        let rows =
            |groups: &[RefGroup]| groups.iter().map(|group| group.blocks.len()).sum::<usize>();
        assert_eq!(
                rows(&direct_bounded.groups),
                admitted,
                "the shared rule must admit exactly the rows its own prefix sum pays for (Direct, admitted={admitted})"
            );
        assert_eq!(
                rows(&managed.groups),
                admitted,
                "the shared rule must admit exactly the rows its own prefix sum pays for (managed, admitted={admitted})"
            );
        assert_managed_simple_query_matches_direct(
            &format!("block referrers admitting {admitted} rows"),
            managed,
            direct_bounded,
        );
    }
    // Row bounds are semantic, not merely cardinality limits: managed must
    // retain the same document-order prefix Direct Files would show. The
    // materialized index is keyed by internal IDs rather than document
    // order, so candidate discovery must finish before the shared
    // path-ordered construction budget selects its prefix.
    for max_rows in 1..=(MODE_DIFFERENTIAL_PAGES * 4 + 1) {
        let managed =
            managed_block_referrers(&handle, MODE_DIFFERENTIAL_ANCHOR, max_rows, MAX_BYTES);
        let direct_bounded =
            direct.block_referrers_bounded(MODE_DIFFERENTIAL_ANCHOR, max_rows, MAX_BYTES);
        let label = format!("block referrers max_rows={max_rows}");
        assert_managed_simple_query_matches_direct(&label, managed, direct_bounded);
    }

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// The managed projection cache: what it saves and that it cannot go stale.
///
/// Graph search is deliberately the vehicle -- unlike the simple-query
/// evaluator it holds no answer memo, so a repeated evaluation really does
/// re-walk every page and the only thing that can have become cheaper is
/// the per-block lsdoc projection.
///
/// The counters are the architectural claim and hold in any build profile.
/// The wall-clock ratio is printed rather than asserted, because a debug
/// number cannot be compared against a release ceiling and widening a
/// ceiling to fit debug would retire it rather than move it.
#[test]
fn managed_projection_cache_reuses_unchanged_pages_and_drops_changed_ones() {
    // Block-DENSE on purpose. A one-block-per-page corpus measures the
    // managed page LOAD, which this cache does not touch; the cost it
    // removes is one lsdoc parse per block per query, so the fixture has to
    // put enough blocks behind each page load for that to be the term that
    // moves.
    const SYNTHETIC_PAGES: usize = 16;
    const BLOCKS_PER_PAGE: usize = 128;
    let fixture = ActivationFixture::scaled_with_blocks(
        "managed-projection-cache",
        0xa3fa,
        SYNTHETIC_PAGES,
        BLOCKS_PER_PAGE,
    );
    let direct = Graph::open(&fixture.graph_root);
    let pages = direct.list_pages().len();
    assert!(pages > SYNTHETIC_PAGES, "fixture did not activate at scale");
    let handle = open_reopened_managed_actor(&fixture);
    handle.clear_application_simple_query_memo().unwrap();
    let source = "references";

    let run = || {
        handle
            .reset_managed_application_query_instrumentation()
            .unwrap();
        let started = Instant::now();
        let execution = managed_graph_search(&handle, source, 0, 20_000);
        let elapsed = started.elapsed();
        (
            elapsed,
            execution,
            handle.managed_application_query_instrumentation().unwrap(),
        )
    };

    let (cold_elapsed, cold, cold_counters) = run();
    assert_eq!(
        cold_counters.projection_cache_misses, pages,
        "the first managed evaluation must convert every page exactly once: {cold_counters:?}"
    );
    assert_eq!(cold_counters.projection_cache_hits, 0, "{cold_counters:?}");
    assert_eq!(
        cold_counters.hydration_cache_misses, pages,
        "the first evaluation must parse and join each page once: {cold_counters:?}"
    );
    assert_eq!(cold_counters.hydration_cache_hits, 0, "{cold_counters:?}");
    assert_managed_graph_search_matches_direct(
        "cold managed graph search",
        cold,
        direct.run_graph_search(source, 0, 20_000, false),
    );

    let (warm_elapsed, warm, warm_counters) = run();
    assert_eq!(
            warm_counters.projection_cache_hits, pages,
            "a repeated evaluation over unchanged pages must reuse every converted tree: {warm_counters:?}"
        );
    assert_eq!(
        warm_counters.projection_cache_misses, 0,
        "a repeated evaluation must not re-parse a single unchanged page: {warm_counters:?}"
    );
    assert_eq!(
        warm_counters.hydration_cache_hits, pages,
        "a repeated evaluation must reuse every exact page hydration: {warm_counters:?}"
    );
    assert_eq!(warm_counters.hydration_cache_misses, 0, "{warm_counters:?}");
    assert_managed_graph_search_matches_direct(
        "warm managed graph search",
        warm,
        direct.run_graph_search(source, 0, 20_000, false),
    );
    eprintln!(
            "managed_projection_cache cold_ms={:.3} warm_ms={:.3} pages={pages} blocks_per_synthetic_page={BLOCKS_PER_PAGE}",
            cold_elapsed.as_secs_f64() * 1_000.0,
            warm_elapsed.as_secs_f64() * 1_000.0,
        );

    // The leg that matters. A retained tree is reused only after it is
    // proved equal to the incoming DTO tree, so a saved page must MISS on
    // the very next query and answer from its new content -- with no
    // invalidation hook for the save path to have forgotten to call.
    let witness_path = direct
        .list_pages()
        .into_iter()
        .next()
        .expect("the projection-cache fixture must contain pages")
        .rel_path;
    let (mut page, revision) = load_application_exact(&handle, &witness_path);
    page.blocks[0].raw = format!("{} projection-cache-witness", page.blocks[0].raw);
    let save = handle
        .save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::Existing {
                path: page.path.clone(),
                revision,
            },
            page,
        })
        .unwrap();
    assert!(
        matches!(save, SyncApplicationPageSaveOutcome::Saved { .. }),
        "the projection-cache fixture edit was not accepted: {save:?}"
    );

    let (_, _, after_save) = run();
    assert_eq!(
        after_save.projection_cache_misses, 1,
        "exactly the saved page must be reconverted: {after_save:?}"
    );
    assert_eq!(
        after_save.projection_cache_hits,
        pages - 1,
        "every page the save did not touch must still be reused: {after_save:?}"
    );
    assert_eq!(after_save.hydration_cache_misses, 0, "{after_save:?}");
    assert_eq!(
            after_save.hydration_cache_hits,
            pages - 1,
            "unchanged pages must retain their parsed application DTOs while the just-saved page is served from its pending foreground projection: {after_save:?}"
        );

    let reopened_direct = Graph::open(&fixture.graph_root);
    let (_, after_save_execution, _) = run();
    assert_managed_graph_search_matches_direct(
        "managed graph search after an accepted save",
        after_save_execution,
        reopened_direct.run_graph_search(source, 0, 20_000, false),
    );

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn application_hydration_cache_budget_tracks_available_memory_with_bounds() {
    assert_eq!(
        application_hydration_cache_budget_for_available(Some(8 * 1024 * 1024)),
        APPLICATION_HYDRATION_CACHE_MIN_BYTES
    );
    assert_eq!(
        application_hydration_cache_budget_for_available(Some(8 * 1024 * 1024 * 1024)),
        APPLICATION_HYDRATION_CACHE_MAX_BYTES
    );
    assert_eq!(
        application_hydration_cache_budget_for_available(None),
        APPLICATION_HYDRATION_CACHE_FALLBACK_BYTES
    );
}

/// The managed query/search performance receipt.
///
/// It runs in the ordinary selection at the cut scale below, where its job
/// is the SHAPE contract: how many inventory passes, page hydrations,
/// candidate rows and DTO constructions each query kind is allowed. Those
/// counters are the architectural claim and hold in any build profile.
///
/// The calibrated timing ceilings are asserted only in a release build,
/// because they were measured in one and a debug number cannot be compared
/// against them -- and widening them to fit debug would retire the ceiling
/// rather than move it. The release receipt at full scale is
/// `TINE_MANAGED_QUERY_GATE_PAGES=1000,10000 TINE_MANAGED_QUERY_GATE_SAMPLES=5
/// cargo test -p tine-core --release managed_query_search_manual_gate -- --nocapture`,
/// optionally with `TINE_MANAGED_QUERY_GATE_REAL_GRAPH_COPY=<copy>`.
///
/// It was `#[ignore]`d, and red: it asserted the sparse task-query path
/// completed on a runtime that refused it, and nothing ran it to say so.
#[test]
fn managed_query_search_manual_gate() {
    let samples = managed_query_gate_samples();
    for (scale, total_pages) in managed_query_gate_scales().into_iter().enumerate() {
        for (density, candidate_pages) in [
            ("0.1pct", (total_pages.saturating_add(999) / 1_000).max(1)),
            ("10pct", (total_pages.saturating_add(9) / 10).max(1)),
            ("100pct", total_pages),
        ] {
            let fixture = ActivationFixture::scaled_query_candidate_density(
                "managed-query-search-gate",
                0xa1f0 + (scale as u128) * 16 + candidate_pages as u128,
                total_pages,
                candidate_pages,
            );
            managed_query_search_manual_receipt(
                &fixture,
                &format!("synthetic-{total_pages}-{density}"),
                samples,
                Some(total_pages),
                Some(candidate_pages),
            );
        }
    }

    if std::env::var_os("TINE_MANAGED_QUERY_GATE_REAL_GRAPH_COPY").is_some() {
        let source = real_graph_copy_source_from_env("TINE_MANAGED_QUERY_GATE_REAL_GRAPH_COPY");
        let fixture =
            ActivationFixture::copied_graph("managed-query-search-real-copy", 0xa2f0, &source);
        managed_query_search_manual_receipt(&fixture, "explicit-real-copy", samples, None, None);
    }
}

#[test]
#[ignore = "manual release gate: managed reads on an explicitly supplied graph copy"]
fn managed_application_read_real_graph_copy_manual_gate() {
    assert!(
            !cfg!(debug_assertions),
            "this gate is release-only; run with TINE_MANAGED_READ_REAL_GRAPH_COPY=<copy> cargo test -p tine-core --release --lib managed_application_read_real_graph_copy_manual_gate -- --ignored --nocapture"
        );
    let source_root = real_graph_copy_source_from_env("TINE_MANAGED_READ_REAL_GRAPH_COPY");
    let fixture =
        ActivationFixture::copied_graph("managed-application-read-real-copy", 0xa140, &source_root);
    let source = user_graph_bytes(&fixture.graph_root);
    let direct_graph = Graph::open(&fixture.graph_root);
    let mut direct_entries = direct_graph.list_pages();
    direct_entries.sort_by(|left, right| left.rel_path.cmp(&right.rel_path));
    assert!(!direct_entries.is_empty());

    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let activation_handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed(&activation_handle);
    assert!(matches!(
        activation_handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
    drop(activation_handle);

    let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
    let handle = opened.handle.expect("managed reopen retains its actor");
    let feed_started = Instant::now();
    let mut managed_entries = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("managed page inventory did not load: {other:?}"),
    };
    managed_entries.sort_by(|left, right| left.rel_path.cmp(&right.rel_path));
    let inventory_semantics = |entries: &[PageEntry]| {
        entries
            .iter()
            .map(|entry| {
                (
                    entry.rel_path.clone(),
                    entry.name.clone(),
                    entry.kind,
                    entry.date_key,
                )
            })
            .collect::<Vec<_>>()
    };
    assert_eq!(
        inventory_semantics(&managed_entries),
        inventory_semantics(&direct_entries)
    );

    let mut journals = managed_entries
        .iter()
        .filter(|entry| entry.kind == PageKind::Journal && entry.date_key.is_some())
        .cloned()
        .collect::<Vec<_>>();
    journals.sort_by_key(|entry| std::cmp::Reverse(entry.date_key.unwrap_or(0)));
    for entry in journals.iter().take(3) {
        let direct = direct_graph.load_page(entry).unwrap();
        let managed = load_application_exact(&handle, &entry.rel_path).0;
        assert_parser_dto_semantics(&direct, &managed);
    }
    let feed_elapsed = feed_started.elapsed();

    let mut direct_samples = Vec::with_capacity(direct_entries.len());
    let mut managed_samples = Vec::with_capacity(direct_entries.len());
    let mut slowest = (Duration::ZERO, String::new());
    for entry in &direct_entries {
        let direct_started = Instant::now();
        let direct = direct_graph.load_page(entry).unwrap();
        direct_samples.push(direct_started.elapsed());

        let managed_started = Instant::now();
        let managed = load_application_exact(&handle, &entry.rel_path).0;
        let managed_elapsed = managed_started.elapsed();
        if managed_elapsed > slowest.0 {
            slowest = (managed_elapsed, entry.rel_path.clone());
        }
        managed_samples.push(managed_elapsed);
        assert_parser_dto_semantics(&direct, &managed);
    }
    let direct_p50 = startup_median(&direct_samples);
    let direct_p95 = startup_p95(&direct_samples);
    let managed_p50 = startup_median(&managed_samples);
    let managed_p95 = startup_p95(&managed_samples);
    eprintln!(
            "managed_real_graph_read_gate pages={} direct_p50_ms={:.3} direct_p95_ms={:.3} managed_p50_ms={:.3} managed_p95_ms={:.3} journals_first_page_ms={:.3} slowest_managed_ms={:.3} slowest_path={:?}",
            direct_entries.len(),
            startup_ms(direct_p50),
            startup_ms(direct_p95),
            startup_ms(managed_p50),
            startup_ms(managed_p95),
            startup_ms(feed_elapsed),
            startup_ms(slowest.0),
            slowest.1,
        );
    assert!(
        managed_p50 <= Duration::from_millis(50) && managed_p50 <= direct_p50.saturating_mul(10),
        "real-copy managed page-open p50 failed: direct={direct_p50:?}, managed={managed_p50:?}"
    );
    assert!(
        managed_p95 <= Duration::from_millis(50) && managed_p95 <= direct_p95.saturating_mul(10),
        "real-copy managed page-open p95 failed: direct={direct_p95:?}, managed={managed_p95:?}"
    );
    assert!(
        feed_elapsed <= Duration::from_millis(500),
        "real-copy Journals first-page gate failed: {feed_elapsed:?}"
    );
    assert_eq!(user_graph_bytes(&fixture.graph_root), source);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// Strip session-local block identities from a resolve/backlink reply.
///
/// Two fields carry one: `BlockDto::id` and the `block_id` locator inside a
/// backlink `evidence` row (Managed namespaces the latter `sparse-v2:`, which
/// is itself the tell that it is an internal handle, not a durable identity).
///
/// `BlockDto::id` is minted per mode: Managed adopts the durable `id::` uuid,
/// Direct synthesizes a session uuid even for a block that already carries
/// `id::`. Neither identity is written to disk and the user never types one —
/// a `((ref))` carries the durable `id::`, which stays in `properties` and is
/// still compared. Two modes numbering the same block differently, while
/// returning identical content, page, breadcrumb and `id::`, is a
/// representation difference a user would regard as equivalent, so the parity
/// oracle compares everything else.
///
/// This is safe, not merely tolerated: every user-facing reference path goes
/// through `ensureBlockId` (`src/store.ts`), which reads the durable `id::`
/// out of the block's raw text and never writes a second one, so a runtime id
/// cannot reach a `((ref))`. What this field must NOT become is an identity a
/// consumer treats as durable; see `docs/contracts/managed-read-surface.md`.
fn without_session_block_ids(value: &serde_json::Value) -> serde_json::Value {
    match value {
        serde_json::Value::Object(fields) => serde_json::Value::Object(
            fields
                .iter()
                .filter(|(key, _)| !matches!(key.as_str(), "id" | "block_id"))
                .map(|(key, nested)| (key.clone(), without_session_block_ids(nested)))
                .collect(),
        ),
        serde_json::Value::Array(items) => {
            serde_json::Value::Array(items.iter().map(without_session_block_ids).collect())
        }
        other => other.clone(),
    }
}

#[test]
#[ignore = "manual release gate: C7a regression on an explicitly supplied disposable graph copy"]
fn managed_c7a_real_graph_copy_manual_gate() {
    assert!(
        !cfg!(debug_assertions),
        "this C7a graph-copy gate is release-only"
    );
    let source_root = real_graph_copy_source_from_env("TINE_MANAGED_READ_REAL_GRAPH_COPY");
    let fixture = ActivationFixture::copied_graph("managed-c7a-real-copy", 0xc7a0, &source_root);
    let original_bytes = user_graph_bytes(&fixture.graph_root);
    let direct = Graph::open(&fixture.graph_root);
    let mut pages = direct.list_pages();
    pages.sort_by(|left, right| left.rel_path.cmp(&right.rel_path));
    assert!(
        !pages.is_empty(),
        "the supplied disposable graph copy has pages"
    );

    // Resolve the DURABLE `id::` uuids, not `BlockDto::id`. A DTO id is a
    // session-local identity that Direct synthesizes for every block; Managed
    // mints its own and cannot know Direct's, so comparing DTO ids across modes
    // asserts something no user can observe and fails for every block. What a
    // user actually writes in a `((uuid))` ref is the durable `id::` property,
    // so that is the identity both read surfaces must resolve identically.
    fn ids(blocks: &[BlockDto], out: &mut Vec<String>) {
        for block in blocks {
            for (key, value) in &block.properties {
                if key == "id" {
                    out.push(value.clone());
                }
            }
            ids(&block.children, out);
        }
    }
    let mut block_ids = Vec::new();
    for entry in &pages {
        ids(&direct.load_page(entry).unwrap().blocks, &mut block_ids);
    }
    block_ids.sort();
    block_ids.dedup();
    assert!(
        !block_ids.is_empty(),
        "the supplied disposable graph copy carries durable `id::` block refs"
    );
    let direct_templates = serde_json::to_value(direct.templates()).unwrap();
    // `ResolveBlocks` is validated against MAX_SYNC_APPLICATION_PAGE_BLOCKS
    // (= MAX_MATERIALIZATION_QUERY_ROWS - 1), not the raw row cap, so a full
    // 10_000-uuid chunk is rejected as RequestTooLarge. Both sides chunk by the
    // request cap so the flattened comparison stays element-for-element equal.
    let direct_resolved = block_ids
        .chunks(MAX_SYNC_APPLICATION_PAGE_BLOCKS)
        .flat_map(|chunk| direct.resolve_blocks(chunk))
        .collect::<Vec<_>>();
    let direct_resolved = serde_json::to_value(direct_resolved).unwrap();
    let direct_backlinks = pages
        .iter()
        .map(|entry| {
            let result = direct.backlinks_bounded(
                &entry.name,
                MAX_SYNC_APPLICATION_RESULT_ROWS,
                MAX_SYNC_APPLICATION_RESULT_BYTES,
            );
            (
                entry.name.clone(),
                serde_json::to_value((&*result.groups, result.total, result.exceeded)).unwrap(),
            )
        })
        .collect::<Vec<_>>();

    let started = Instant::now();
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("C7a graph copy activates");
    drive_initial_feed(&handle);
    let activation = started.elapsed();

    let managed_snapshot = || {
        let templates = match handle
            .application_navigation(SyncApplicationNavigationRequest::ListTemplates)
            .unwrap()
        {
            SyncApplicationNavigationOutcome::Loaded {
                reply: SyncApplicationNavigationReply::Templates(templates),
            } => serde_json::to_value(templates).unwrap(),
            other => panic!("managed templates did not load: {other:?}"),
        };
        let mut resolved = Vec::new();
        for chunk in block_ids.chunks(MAX_SYNC_APPLICATION_PAGE_BLOCKS) {
            match handle
                .application_navigation(SyncApplicationNavigationRequest::ResolveBlocks {
                    uuids: chunk.to_vec(),
                })
                .unwrap()
            {
                SyncApplicationNavigationOutcome::Loaded {
                    reply: SyncApplicationNavigationReply::ResolveBlocks(rows),
                } => resolved.extend(rows),
                other => panic!("managed UUID batch did not load: {other:?}"),
            }
        }
        let backlinks = pages
            .iter()
            .map(|entry| {
                let result = match handle
                    .application_navigation(SyncApplicationNavigationRequest::Backlinks {
                        name: entry.name.clone(),
                        max_rows: MAX_SYNC_APPLICATION_RESULT_ROWS,
                        max_bytes: MAX_SYNC_APPLICATION_RESULT_BYTES,
                    })
                    .unwrap()
                {
                    SyncApplicationNavigationOutcome::Loaded {
                        reply: SyncApplicationNavigationReply::Backlinks(result),
                    } => result,
                    other => panic!("managed backlinks did not load: {other:?}"),
                };
                (
                    entry.name.clone(),
                    serde_json::to_value((result.groups, result.total, result.exceeded)).unwrap(),
                )
            })
            .collect::<Vec<_>>();
        (
            templates,
            serde_json::to_value(resolved).unwrap(),
            backlinks,
        )
    };
    let before_save = managed_snapshot();
    // Non-vacuity: a gate that resolves nothing on either side would compare
    // two empty results and pass while proving nothing.
    let resolved_groups = before_save
        .1
        .as_array()
        .expect("resolved reply is an array")
        .iter()
        .filter(|group| !group.is_null())
        .count();
    assert_eq!(
        resolved_groups,
        block_ids.len(),
        "every durable `id::` ref resolves in Managed mode"
    );
    assert_eq!(before_save.0, direct_templates);
    assert_eq!(
        without_session_block_ids(&before_save.1),
        without_session_block_ids(&direct_resolved)
    );
    assert_eq!(
        without_session_block_ids(&serde_json::to_value(&before_save.2).unwrap()),
        without_session_block_ids(&serde_json::to_value(&direct_backlinks).unwrap())
    );

    fn count_blocks(blocks: &[BlockDto]) -> usize {
        blocks
            .iter()
            .map(|block| 1 + count_blocks(&block.children))
            .sum()
    }

    // A whole-page Managed save is bounded by MAX_SYNC_EDITOR_BLOCKS (= 511:
    // two operations per retained block plus a preamble, inside
    // MAX_LOCAL_MUTATION_ROWS = 1024), while a Managed LOAD is bounded by
    // MAX_SYNC_APPLICATION_PAGE_BLOCKS (= 9_999). A page between the two
    // ceilings therefore opens and cannot be saved. That asymmetry is a real
    // pre-existing defect, not something C7a introduced — this corpus contains
    // exactly one such page — so the gate PINS it rather than crashing on it.
    // When the ceiling is raised or the save is chunked, this expectation flips,
    // and that flip must be a deliberate edit.
    let mut unchanged_saves = 0_usize;
    let mut refused_oversized_saves = 0_usize;
    for entry in &pages {
        let (page, revision) = load_application_exact(&handle, &entry.rel_path);
        if page.read_only || page.guide {
            continue;
        }
        let blocks = count_blocks(&page.blocks);
        let outcome = handle.save_application_page(SyncApplicationPageSaveRequest {
            target: SyncApplicationPageSaveTarget::Existing {
                path: page.path.clone(),
                revision,
            },
            page,
        });
        if blocks > MAX_SYNC_EDITOR_BLOCKS {
            assert!(
                matches!(
                    outcome,
                    Err(SyncApplicationPageRequestError::RequestTooLarge(_))
                ),
                "a {blocks}-block page is above the {MAX_SYNC_EDITOR_BLOCKS} whole-page save ceiling \
                 and must be refused as RequestTooLarge, not saved: {outcome:?}"
            );
            refused_oversized_saves += 1;
            continue;
        }
        assert!(matches!(
            outcome.unwrap(),
            SyncApplicationPageSaveOutcome::Unchanged { .. }
        ));
        unchanged_saves += 1;
    }
    drain_managed_local(&handle);
    assert_eq!(user_graph_bytes(&fixture.graph_root), original_bytes);
    assert_eq!(managed_snapshot(), before_save);
    eprintln!(
        "c7a_real_graph pages={} block_ids={} templates={} backlink_queries={} unchanged_saves={} refused_oversized_saves={} activation_ms={:.3}",
        pages.len(),
        block_ids.len(),
        direct_templates.as_array().map_or(0, Vec::len),
        direct_backlinks.len(),
        unchanged_saves,
        refused_oversized_saves,
        startup_ms(activation),
    );
}

/// A graph whose journals exercise every feed selection rule at once: a
/// run of ordinary days, a day owning two files, a nested journal, a
/// journal-kind file whose stem is not a date, a future day, and an
/// ordinary page. The fixture's configured journal filename format is
/// `dd-MM-yyyy`, so lexicographic path order is deliberately NOT date
/// order — a feed that leaned on the projection's path ordering would
/// return these days scrambled.
fn journal_feed_fixture(label: &str, seed: u128) -> ActivationFixture {
    let fixture = ActivationFixture::empty(label, seed);
    let journals = fixture.graph_root.join("diary");
    fs::create_dir_all(journals.join("nested")).unwrap();
    for day in 14..=24 {
        fs::write(
            journals.join(format!("{day}-07-2026.md")),
            format!("- july {day}\n"),
        )
        .unwrap();
    }
    // Two files for 2026-07-25: the feed shows the day once.
    fs::write(journals.join("25-07-2026.md"), b"- july 25 flat\n").unwrap();
    fs::write(
        journals.join("nested/25-07-2026.org"),
        b"* july 25 nested\n",
    )
    .unwrap();
    // Journal-kind by path, but no date in its stem: never a feed day.
    fs::write(journals.join("not-a-date.md"), b"- undated\n").unwrap();
    // A future day stays a reachable page but is not in the feed.
    fs::write(journals.join("01-01-2099.md"), b"- future\n").unwrap();
    fs::write(
        fixture.graph_root.join("notes/Ordinary.md"),
        b"- ordinary page\n",
    )
    .unwrap();
    fixture
}

/// The complete pre-2026-08-26 shell implementation of `journal_feed_page`
/// under managed storage, retained as the differential oracle: the whole
/// page inventory, the feed's dedup/cutoff rules, then `limit` exact page
/// loads. `SyncRuntimeHandle::journal_feed_page` must answer identically.
fn journal_feed_page_by_inventory_walk(
    handle: &SyncRuntimeHandle,
    request: SyncApplicationJournalFeedRequest,
) -> (Vec<String>, Option<i64>, bool) {
    let pages = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
        other => panic!("inventory walk did not load: {other:?}"),
    };
    let entries = crate::journal_feed::journal_feed_inventory(pages, request.as_of_day);
    let selection = crate::journal_feed::collect_journal_feed_page(
        entries.into_iter().filter(|entry| {
            crate::journal_feed::journal_feed_candidate_in_window(
                entry,
                request.as_of_day,
                request.before_day,
            )
        }),
        request.limit,
        |entry| match handle
            .load_application_page(SyncApplicationPageLoadRequest {
                page: SyncApplicationPageSelector::ExactPath {
                    path: entry.rel_path.clone(),
                },
            })
            .unwrap()
        {
            SyncApplicationPageLoadOutcome::Loaded { mut page, revision } => {
                page.rev = Some(revision);
                Ok(page)
            }
            SyncApplicationPageLoadOutcome::Missing { .. } => {
                Err(std::io::Error::from(std::io::ErrorKind::NotFound))
            }
            other => panic!("inventory-walk feed load did not load: {other:?}"),
        },
    )
    .unwrap();
    (
        selection
            .pages
            .iter()
            .map(|page| format!("{}|{}|{:?}", page.path, page.name, page.rev))
            .collect(),
        selection.next_before_day,
        selection.done,
    )
}

fn journal_feed_page_indexed(
    handle: &SyncRuntimeHandle,
    request: SyncApplicationJournalFeedRequest,
) -> (Vec<String>, Option<i64>, bool) {
    match handle.journal_feed_page(request).unwrap() {
        SyncApplicationJournalFeedOutcome::Loaded {
            pages,
            next_before_day,
            done,
        } => (
            pages
                .iter()
                .map(|page| format!("{}|{}|{:?}", page.path, page.name, page.rev))
                .collect(),
            next_before_day,
            done,
        ),
        other => panic!("indexed journal feed did not load: {other:?}"),
    }
}

/// Paginate the whole feed both ways and require the same days, in the
/// same order, with the same cursors — the correctness half of dropping
/// the inventory walk.
#[test]
fn journal_feed_page_matches_the_inventory_walk_across_pagination() {
    let fixture = journal_feed_fixture("journal-feed-differential", 0xfeed_0001);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed(&handle);

    // `20260726` is deliberately after the newest ordinary day and before
    // the future one, so the cutoff itself is under test.
    for as_of_day in [20_260_726, 20_260_723, 20_991_231] {
        for limit in [0, 1, 3, 100] {
            let mut cursor = None;
            let mut walked_days = Vec::new();
            let mut indexed_days = Vec::new();
            for _ in 0..16 {
                let request = SyncApplicationJournalFeedRequest {
                    limit,
                    before_day: cursor,
                    as_of_day,
                };
                let walked = journal_feed_page_by_inventory_walk(&handle, request);
                let indexed = journal_feed_page_indexed(&handle, request);
                assert_eq!(
                    walked, indexed,
                    "feed divergence at as_of_day={as_of_day} limit={limit} cursor={cursor:?}"
                );
                walked_days.extend(walked.0.clone());
                indexed_days.extend(indexed.0.clone());
                if walked.2 || limit == 0 {
                    break;
                }
                cursor = walked.1;
                assert!(cursor.is_some(), "an unfinished feed must advance");
            }
            assert_eq!(walked_days, indexed_days);
        }
    }

    // The whole feed, once, so the fixture's own selection rules are
    // pinned rather than only compared with themselves.
    let whole = journal_feed_page_indexed(
        &handle,
        SyncApplicationJournalFeedRequest {
            limit: 100,
            before_day: None,
            as_of_day: 20_260_726,
        },
    );
    let paths = whole
        .0
        .iter()
        .map(|row| row.split('|').next().unwrap().to_owned())
        .collect::<Vec<_>>();
    assert_eq!(
        paths,
        (14..=25)
            .rev()
            .map(|day| format!("diary/{day}-07-2026.md"))
            .collect::<Vec<_>>(),
        "one row per day, newest first, no undated or future rows"
    );
    assert!(whole.2);

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// Opening and scrolling the Journals feed must not be graph-sized work.
///
/// Budget: repeated feed pages against an unchanged accepted frontier
/// perform ONE whole-graph page-inventory scan in total, not one per
/// request (managed-storage cost-model audit 2026-08-26, D6). An accepted
/// change must still be visible, so the same test proves the index is
/// rebuilt after a save rather than serving stale days.
#[test]
fn journal_feed_open_is_not_graph_sized_and_refreshes_after_an_accepted_change() {
    let fixture = journal_feed_fixture("journal-feed-budget", 0xfeed_0002);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed(&handle);

    let as_of_day = 20_260_726;
    let feed_page = |cursor: Option<i64>| {
        journal_feed_page_indexed(
            &handle,
            SyncApplicationJournalFeedRequest {
                limit: 3,
                before_day: cursor,
                as_of_day,
            },
        )
    };

    // The shell's own shape: one open plus a scroll to the end of the feed.
    let baseline = handle.application_inventory_scans().unwrap();
    let mut cursor = None;
    let mut requests = 0;
    loop {
        let page = feed_page(cursor);
        requests += 1;
        if page.2 {
            break;
        }
        cursor = page.1;
    }
    assert!(requests >= 4, "the fixture must actually paginate");
    assert_eq!(
        handle.application_inventory_scans().unwrap() - baseline,
        1,
        "{requests} feed pages over an unchanged frontier must share one inventory scan"
    );

    // Reopening the feed from the top changes nothing, so it must not scan.
    let reopened = feed_page(None);
    assert_eq!(
        handle.application_inventory_scans().unwrap() - baseline,
        1,
        "reopening an unchanged feed must not walk the graph again"
    );

    // An accepted change is visible, and costs exactly one rebuild.
    let (page, revision) = load_application_exact(&handle, "diary/24-07-2026.md");
    let _ = save_application_block_text(&handle, page, revision, "- july 24 edited");
    drain_managed_local(&handle);
    let after = feed_page(None);
    assert_ne!(
        after.0, reopened.0,
        "the feed must show the accepted edit, not the retained index"
    );
    assert!(
        after
            .0
            .iter()
            .any(|row| row.contains("diary/24-07-2026.md")),
        "the edited day is still in the feed: {:?}",
        after.0
    );
    let scans = handle.application_inventory_scans().unwrap() - baseline;
    assert_eq!(scans, 2, "one accepted change costs one index rebuild");
    assert_eq!(
        feed_page(None).0,
        after.0,
        "the rebuilt index answers the next open without another scan"
    );
    assert_eq!(handle.application_inventory_scans().unwrap() - baseline, 2);

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// The same differential on a real graph copy: synthetic fixtures are
/// generated from our model of a graph, and that model is what produced
/// the code under test. Run with
/// `TINE_MANAGED_NAV_GRAPH_COPY=<copy> cargo test -p tine-core --release
/// journal_feed_matches_the_inventory_walk_on_a_real_graph_copy --
/// --ignored --nocapture`.
#[test]
#[ignore = "real-graph gate: journal feed differential on a supplied graph copy"]
fn journal_feed_matches_the_inventory_walk_on_a_real_graph_copy() {
    let source_root = real_graph_copy_source_from_env("TINE_MANAGED_NAV_GRAPH_COPY");
    let fixture =
        ActivationFixture::copied_graph("journal-feed-real-copy", 0xfeed_0004, &source_root);
    let source = user_graph_bytes(&fixture.graph_root);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed_with_turn_budget(&handle, 4096);

    // The anonymized corpus scrambles journal filenames, so its parseable
    // days land far in the future and today's feed is empty. Run the
    // differential at an as-of day past every one of them, which also
    // makes it the widest possible feed, and again at today's, which
    // exercises the empty-window boundary on the same graph.
    for as_of_day in [99_999_999, crate::date::JournalDate::today().ordinal_key()] {
        journal_feed_real_copy_differential(&handle, as_of_day, as_of_day == 99_999_999);
    }

    assert_eq!(user_graph_bytes(&fixture.graph_root), source);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

fn journal_feed_real_copy_differential(
    handle: &SyncRuntimeHandle,
    as_of_day: i64,
    require_days: bool,
) {
    let mut cursor = None;
    let mut days = 0usize;
    let mut pages = 0usize;
    let indexed_baseline = handle.application_inventory_scans().unwrap();
    let mut indexed_pages = Vec::new();
    // FEED_PAGE in src/components/Page.tsx.
    for _ in 0..4096 {
        let request = SyncApplicationJournalFeedRequest {
            limit: 3,
            before_day: cursor,
            as_of_day,
        };
        let indexed = journal_feed_page_indexed(handle, request);
        indexed_pages.push((request, indexed.clone()));
        pages += 1;
        days += indexed.0.len();
        if indexed.2 {
            break;
        }
        cursor = indexed.1;
        assert!(cursor.is_some(), "an unfinished feed must advance");
    }
    let indexed_scans = handle.application_inventory_scans().unwrap() - indexed_baseline;
    if require_days {
        assert!(pages >= 2 && days >= 2, "the corpus must have a real feed");
    }

    let walked_baseline = handle.application_inventory_scans().unwrap();
    for (request, indexed) in &indexed_pages {
        assert_eq!(
            journal_feed_page_by_inventory_walk(handle, *request),
            *indexed,
            "feed divergence on the real copy at as_of_day={as_of_day} cursor={:?}",
            request.before_day
        );
    }
    let walked_scans = handle.application_inventory_scans().unwrap() - walked_baseline;
    eprintln!(
            "journal_feed_real_copy as_of_day={as_of_day} pages={pages} days={days} indexed_scans={indexed_scans} walked_scans={walked_scans}"
        );
    assert!(
        indexed_scans <= 1,
        "the whole feed shares at most one inventory scan"
    );
    assert_eq!(walked_scans, pages, "the retired shape scans per feed page");
}

/// The pre-fix shape, kept as the necessity proof for the budget above:
/// answering the same feed pages from the complete page inventory walks
/// the graph once per request. This is what the assertion above rejects.
#[test]
fn inventory_walk_feed_is_graph_sized_per_request() {
    let fixture = journal_feed_fixture("journal-feed-necessity", 0xfeed_0003);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed(&handle);

    let baseline = handle.application_inventory_scans().unwrap();
    let mut cursor = None;
    let mut requests = 0;
    loop {
        let page = journal_feed_page_by_inventory_walk(
            &handle,
            SyncApplicationJournalFeedRequest {
                limit: 3,
                before_day: cursor,
                as_of_day: 20_260_726,
            },
        );
        requests += 1;
        if page.2 {
            break;
        }
        cursor = page.1;
    }
    assert!(requests >= 4);
    assert_eq!(
        handle.application_inventory_scans().unwrap() - baseline,
        requests,
        "the retired shell implementation scans the whole graph per feed page"
    );

    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

/// The Journals back-gesture, staged.
///
/// Martin reports that under managed storage on Android, opening a page
/// forward is fast while the back gesture to Journals — a feed loaded
/// seconds earlier, with nothing changed in between — takes 2–3 seconds.
/// The commands behind the two gestures were not the same shape:
/// `get_page` is ONE actor page load, while `journal_feed_page` used to be
/// a FULL page inventory followed by `limit` page loads. This receipt
/// separates those stages so the cost is attributed rather than guessed
/// at, times the current indexed feed beside the retired inventory-walk
/// shape, and prints the Direct Files analogue of each stage. It also
/// times the Logical forward open, which is what `get_page` actually
/// uses — the audit measured only the `ExactPath` leaf.
#[test]
#[ignore = "manual benchmark: the Journals back gesture, staged, on a supplied graph copy"]
fn managed_journals_back_navigation_manual_benchmark() {
    assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run with TINE_MANAGED_NAV_GRAPH_COPY=<copy> cargo test -p tine-core --release managed_journals_back_navigation_manual_benchmark -- --ignored --nocapture"
        );
    let source_root = real_graph_copy_source_from_env("TINE_MANAGED_NAV_GRAPH_COPY");
    let rounds = std::env::var("TINE_MANAGED_NAV_BENCH_ROUNDS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|rounds| *rounds > 0)
        .unwrap_or(12);
    // `FEED_PAGE` in src/components/Page.tsx.
    const FEED_LIMIT: usize = 3;

    let fixture =
        ActivationFixture::copied_graph("managed-journals-back-nav", 0xa1c0, &source_root);
    let source = user_graph_bytes(&fixture.graph_root);

    let direct_graph = Graph::open(&fixture.graph_root);
    let direct_list_cold = Instant::now();
    let direct_entries = direct_graph.list_pages();
    let direct_list_cold = direct_list_cold.elapsed();
    let direct_list_warm = Instant::now();
    let _ = direct_graph.list_pages();
    let direct_list_warm = direct_list_warm.elapsed();
    assert!(!direct_entries.is_empty());

    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let activation_handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed(&activation_handle);
    assert!(matches!(
        activation_handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(activation_handle);

    let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
    let handle = opened.handle.expect("managed reopen retains its actor");

    let today = crate::date::JournalDate::today().ordinal_key();
    let feed_paths = |pages: &[PageEntry]| -> Vec<String> {
        let mut journals = pages
            .iter()
            .filter(|entry| {
                entry.kind == PageKind::Journal && entry.date_key.is_some_and(|day| day <= today)
            })
            .cloned()
            .collect::<Vec<_>>();
        if journals.len() < FEED_LIMIT {
            journals = pages
                .iter()
                .filter(|entry| entry.kind == PageKind::Journal && entry.date_key.is_some())
                .cloned()
                .collect();
        }
        journals.sort_by_key(|entry| std::cmp::Reverse(entry.date_key.unwrap_or(0)));
        journals
            .into_iter()
            .take(FEED_LIMIT)
            .map(|entry| entry.rel_path)
            .collect()
    };

    let mut indexed_feed_samples = Vec::with_capacity(rounds);
    let mut forward_logical_samples = Vec::with_capacity(rounds);
    let mut inventory_samples = Vec::with_capacity(rounds);
    let mut feed_load_samples = Vec::with_capacity(rounds);
    let mut feed_total_samples = Vec::with_capacity(rounds);
    let mut forward_samples = Vec::with_capacity(rounds);
    let mut direct_feed_samples = Vec::with_capacity(rounds);
    let mut direct_forward_samples = Vec::with_capacity(rounds);

    // The forward gesture's target: an ordinary (non-journal) page, the
    // largest one, so the comparison is not flattered by a tiny file.
    let forward_entry = direct_entries
        .iter()
        .filter(|entry| entry.kind == PageKind::Page)
        .max_by_key(|entry| std::fs::metadata(&entry.path).map(|m| m.len()).unwrap_or(0))
        .cloned()
        .unwrap_or_else(|| direct_entries[0].clone());

    // An anonymized corpus can carry scrambled journal filenames whose
    // parseable days all sit in the future, so today's feed would be
    // empty and time nothing. Both legs below therefore use the newest
    // day the graph actually has when that is later than today, exactly
    // as `feed_paths` already falls back.
    let bench_as_of_day = match handle.application_page_inventory().unwrap() {
        SyncApplicationPageInventoryOutcome::Loaded { pages } => pages
            .iter()
            .filter(|entry| entry.kind == PageKind::Journal)
            .filter_map(|entry| entry.date_key)
            .max()
            .map_or(today, |newest| newest.max(today)),
        other => panic!("managed page inventory did not load: {other:?}"),
    };

    let mut inventory_len = 0usize;
    for _ in 0..rounds {
        // The same back gesture through the retained journal day index:
        // one actor turn, no whole-graph walk. It runs FIRST in each round
        // so it pays the cold page loads and the retired walk leg below
        // gets the warm ones — the conservative direction for this
        // comparison.
        let indexed_started = Instant::now();
        match handle
            .journal_feed_page(SyncApplicationJournalFeedRequest {
                limit: FEED_LIMIT,
                before_day: None,
                as_of_day: bench_as_of_day,
            })
            .unwrap()
        {
            SyncApplicationJournalFeedOutcome::Loaded { pages, .. } => {
                assert!(!pages.is_empty(), "the indexed feed answered nothing");
            }
            other => panic!("indexed journal feed did not load: {other:?}"),
        }
        indexed_feed_samples.push(indexed_started.elapsed());

        // Back gesture: journal_feed_page = inventory, then FEED_LIMIT loads.
        let feed_started = Instant::now();
        let inventory_started = Instant::now();
        let pages = match handle.application_page_inventory().unwrap() {
            SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
            other => panic!("managed page inventory did not load: {other:?}"),
        };
        let inventory_elapsed = inventory_started.elapsed();
        inventory_len = pages.len();
        let paths = feed_paths(&pages);
        let loads_started = Instant::now();
        for path in &paths {
            let _ = load_application_exact(&handle, path);
        }
        let loads_elapsed = loads_started.elapsed();
        let feed_elapsed = feed_started.elapsed();
        inventory_samples.push(inventory_elapsed);
        feed_load_samples.push(loads_elapsed);
        feed_total_samples.push(feed_elapsed);

        // Forward gesture: get_page = ONE actor page load. Production uses
        // the Logical selector; the ExactPath leg is the audit's probe.
        let forward_started = Instant::now();
        let _ = load_application_exact(&handle, &forward_entry.rel_path);
        forward_samples.push(forward_started.elapsed());

        let forward_logical_started = Instant::now();
        let _ = load_application_logical(&handle, &forward_entry.name, SyncPageKind::Page);
        forward_logical_samples.push(forward_logical_started.elapsed());

        // Direct Files analogues of the same two gestures.
        let direct_feed_started = Instant::now();
        let direct_pages = direct_graph.list_pages();
        let direct_paths = feed_paths(&direct_pages);
        for path in &direct_paths {
            let entry = direct_pages
                .iter()
                .find(|entry| &entry.rel_path == path)
                .expect("the direct feed path is in the direct inventory");
            let _ = direct_graph.load_page(entry).unwrap();
        }
        direct_feed_samples.push(direct_feed_started.elapsed());

        let direct_forward_started = Instant::now();
        let _ = direct_graph.load_page(&forward_entry).unwrap();
        direct_forward_samples.push(direct_forward_started.elapsed());
    }

    let report = |label: &str, samples: &[Duration]| {
        eprintln!(
            "managed_journals_back_nav stage={label} p50_ms={:.3} p95_ms={:.3} max_ms={:.3}",
            startup_ms(startup_median(samples)),
            startup_ms(startup_p95(samples)),
            startup_ms(samples.iter().copied().max().unwrap_or(Duration::ZERO)),
        );
    };
    eprintln!(
            "managed_journals_back_nav pages={inventory_len} direct_pages={} rounds={rounds} feed_limit={FEED_LIMIT} as_of_day={bench_as_of_day} direct_list_cold_ms={:.3} direct_list_warm_ms={:.3}",
            direct_entries.len(),
            startup_ms(direct_list_cold),
            startup_ms(direct_list_warm),
        );
    report("managed_back_total", &feed_total_samples);
    report("managed_back_inventory", &inventory_samples);
    report("managed_back_page_loads", &feed_load_samples);
    report("managed_back_indexed_total", &indexed_feed_samples);
    report("managed_forward_one_page", &forward_samples);
    report("managed_forward_one_page_logical", &forward_logical_samples);
    report("direct_back_total", &direct_feed_samples);
    report("direct_forward_one_page", &direct_forward_samples);

    assert_eq!(user_graph_bytes(&fixture.graph_root), source);
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
}

/// What one Android poll cycle costs the navigation lane.
///
/// `watch_mode` defaults to `"poll"` on Android
/// (src-tauri/src/watcher.rs:1797-1817) with a 3 s cycle. Every such cycle
/// pushes `RescanRequired`, and the actor answers it with `begin_full_scan`
/// followed by budgeted continuation turns, all of them holding the same
/// `operation` lane that `journal_feed_page` and `get_page` need. This
/// receipt drives exactly that loop and reports (a) how long the scan owns
/// the lane and (b) what a Journals back gesture and a forward page open
/// cost while it does.
#[test]
#[ignore = "manual benchmark: what an Android poll-cycle rescan costs the navigation lane"]
fn managed_poll_cycle_rescan_navigation_cost_manual_benchmark() {
    assert!(
            !cfg!(debug_assertions),
            "this receipt is release-only; run with TINE_MANAGED_NAV_GRAPH_COPY=<copy> cargo test -p tine-core --release managed_poll_cycle_rescan_navigation_cost_manual_benchmark -- --ignored --nocapture"
        );
    let source_root = real_graph_copy_source_from_env("TINE_MANAGED_NAV_GRAPH_COPY");
    let cycles = std::env::var("TINE_MANAGED_NAV_BENCH_SCAN_CYCLES")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|cycles| *cycles > 0)
        .unwrap_or(3);
    const FEED_LIMIT: usize = 3;
    // `RetryState::progressed` in src-tauri/src/watcher.rs re-arms a
    // continuing scan at 10 ms.
    const CONTINUATION_CADENCE: Duration = Duration::from_millis(10);

    let fixture =
        ActivationFixture::copied_graph("managed-poll-cycle-rescan-nav", 0xa1d0, &source_root);
    let source = user_graph_bytes(&fixture.graph_root);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let activation_handle = activated.handle.expect("activation retains its actor");
    drive_initial_feed(&activation_handle);
    assert!(matches!(
        activation_handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
    drop(activation_handle);

    let opened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(opened.status, SyncRuntimeOpenStatus::Active);
    let handle = std::sync::Arc::new(opened.handle.expect("managed reopen retains its actor"));

    let today = crate::date::JournalDate::today().ordinal_key();
    let inventory_of = |handle: &SyncRuntimeHandle| -> Vec<PageEntry> {
        match handle.application_page_inventory().unwrap() {
            SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
            other => panic!("managed page inventory did not load: {other:?}"),
        }
    };
    let baseline_inventory = inventory_of(&handle);
    let mut journals = baseline_inventory
        .iter()
        .filter(|entry| {
            entry.kind == PageKind::Journal && entry.date_key.is_some_and(|day| day <= today)
        })
        .cloned()
        .collect::<Vec<_>>();
    if journals.len() < FEED_LIMIT {
        journals = baseline_inventory
            .iter()
            .filter(|entry| entry.kind == PageKind::Journal && entry.date_key.is_some())
            .cloned()
            .collect();
    }
    journals.sort_by_key(|entry| std::cmp::Reverse(entry.date_key.unwrap_or(0)));
    let feed_paths = journals
        .iter()
        .take(FEED_LIMIT)
        .map(|entry| entry.rel_path.clone())
        .collect::<Vec<_>>();
    assert!(!feed_paths.is_empty());
    let forward_path = baseline_inventory
        .iter()
        .filter(|entry| entry.kind == PageKind::Page)
        .max_by_key(|entry| std::fs::metadata(&entry.path).map(|m| m.len()).unwrap_or(0))
        .map(|entry| entry.rel_path.clone())
        .unwrap_or_else(|| baseline_inventory[0].rel_path.clone());

    // Uncontended reference, on the same actor, before any rescan is armed.
    let idle_back = Instant::now();
    let _ = inventory_of(&handle);
    for path in &feed_paths {
        let _ = load_application_exact(&handle, path);
    }
    let idle_back = idle_back.elapsed();
    let idle_forward = Instant::now();
    let _ = load_application_exact(&handle, &forward_path);
    let idle_forward = idle_forward.elapsed();

    let scanning = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
    let scan_handle = std::sync::Arc::clone(&handle);
    let scan_running = std::sync::Arc::clone(&scanning);
    let scanner = std::thread::spawn(move || {
        // One poll cycle, exactly as src-tauri/src/watcher.rs drives it:
        // observe `RescanRequired`, then re-tick at the 10 ms continuation
        // cadence for as long as the actor reports it is still recovering.
        let mut receipts = Vec::new();
        for _ in 0..cycles {
            scan_handle
                .observe_watcher(vec![SyncWatcherObservation::RescanRequired])
                .expect("the watcher observation is accepted");
            let cycle_started = Instant::now();
            let mut turns = 0_usize;
            let mut first_turn = Duration::ZERO;
            let mut slowest_turn = Duration::ZERO;
            let mut lane_held = Duration::ZERO;
            loop {
                let turn_started = Instant::now();
                let tick = scan_handle.tick().expect("the actor answers a tick");
                let turn = turn_started.elapsed();
                lane_held = lane_held.saturating_add(turn);
                if turns == 0 {
                    first_turn = turn;
                }
                if turn > slowest_turn {
                    slowest_turn = turn;
                }
                turns += 1;
                match tick {
                    SyncRuntimeTick::Recovering | SyncRuntimeTick::RetryFull => {}
                    _ => {
                        if !scan_handle.status().unwrap().watcher.pending {
                            break;
                        }
                    }
                }
                if turns >= 4_000 {
                    break;
                }
                std::thread::sleep(CONTINUATION_CADENCE);
            }
            receipts.push((
                cycle_started.elapsed(),
                lane_held,
                turns,
                first_turn,
                slowest_turn,
            ));
        }
        scan_running.store(false, std::sync::atomic::Ordering::Release);
        receipts
    });

    // Meanwhile: the two gestures, on the lane the scan is holding.
    let mut back_samples = Vec::new();
    let mut forward_samples = Vec::new();
    while scanning.load(std::sync::atomic::Ordering::Acquire) {
        let back_started = Instant::now();
        let _ = inventory_of(&handle);
        for path in &feed_paths {
            let _ = load_application_exact(&handle, path);
        }
        back_samples.push(back_started.elapsed());
        let forward_started = Instant::now();
        let _ = load_application_exact(&handle, &forward_path);
        forward_samples.push(forward_started.elapsed());
    }
    let receipts = scanner.join().expect("the scan thread finishes");

    for (index, (wall, lane_held, turns, first_turn, slowest_turn)) in receipts.iter().enumerate() {
        eprintln!(
                "managed_poll_cycle_rescan cycle={index} wall_ms={:.3} lane_held_ms={:.3} turns={turns} first_turn_ms={:.3} slowest_turn_ms={:.3}",
                startup_ms(*wall),
                startup_ms(*lane_held),
                startup_ms(*first_turn),
                startup_ms(*slowest_turn),
            );
    }
    let report = |label: &str, samples: &[Duration]| {
        if samples.is_empty() {
            eprintln!("managed_poll_cycle_rescan stage={label} samples=0");
            return;
        }
        eprintln!(
            "managed_poll_cycle_rescan stage={label} n={} p50_ms={:.3} p95_ms={:.3} max_ms={:.3}",
            samples.len(),
            startup_ms(startup_median(samples)),
            startup_ms(startup_p95(samples)),
            startup_ms(samples.iter().copied().max().unwrap_or(Duration::ZERO)),
        );
    };
    eprintln!(
            "managed_poll_cycle_rescan pages={} feed_limit={FEED_LIMIT} idle_back_ms={:.3} idle_forward_ms={:.3}",
            baseline_inventory.len(),
            startup_ms(idle_back),
            startup_ms(idle_forward),
        );
    report("contended_back_total", &back_samples);
    report("contended_forward_one_page", &forward_samples);

    assert_eq!(user_graph_bytes(&fixture.graph_root), source);
    let handle = std::sync::Arc::try_unwrap(handle).expect("the scan thread released the handle");
    assert!(matches!(
        handle.clean_shutdown(),
        Ok(SyncShutdownOutcome::Safe(_))
    ));
}

#[test]
fn explicit_local_activation_preserves_nested_unicode_graph_bytes_without_retired_backup() {
    let fixture = ActivationFixture::nested_unicode("journey", 0xa100);
    let before = user_graph_bytes(&fixture.graph_root);

    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated
        .handle
        .expect("activation must retain the runtime handle");
    assert!(fixture.request.database_path.is_file());
    assert!(
        !fixture
            .request
            .enrollment_root
            .parent()
            .expect("private enrollment root has a parent")
            .join("migration-backup")
            .exists(),
        "clean activation must not recreate the retired migration-backup authority"
    );
    assert_eq!(
        user_graph_bytes(&fixture.graph_root),
        before,
        "activation may create only the shared .tine-sync/v2 namespace, never rewrite graph bytes"
    );
    drive_initial_feed(&handle);
    assert_eq!(
            user_graph_bytes(&fixture.graph_root),
            before,
            "aggregate bootstrap authority confirmation and the initial exact feed must remain read-only"
        );
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn fresh_activation_retains_one_bootstrap_authority_and_zero_ordinary_page_receipts() {
    let fixture = ActivationFixture::nested_unicode("aggregate-bootstrap-authority", 0xa180);
    let before = user_graph_bytes(&fixture.graph_root);

    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation must retain an actor");
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);

    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let endpoint = ProjectionEndpointBinding {
        endpoint_id: fixture.request.identities.endpoint_id,
        device_id: fixture.request.identities.device_id,
        graph_resource_id: graph.canonical_resource_id().unwrap(),
    };
    drop(graph);
    let receipts = ProjectionReceiptStore::open_for_endpoint(
        &fixture.request.receipt_root,
        fixture.request.identities.workspace_id,
        endpoint,
    )
    .unwrap();
    let ordinary_catalog = receipts.validated_catalog().unwrap();
    assert!(
            ordinary_catalog.is_empty(),
            "activation must create zero per-page intents, attempts, completions, or completed-path transitions: {ordinary_catalog:?}"
        );
    assert!(
        !fixture
            .request
            .application_runtime_root
            .join("bootstrap-projection-receipts-v1.json")
            .exists(),
        "aggregate authority replaces the eager-receipt completion marker"
    );
    drop(handle);
}

#[test]
fn first_own_endpoint_external_change_leaves_receipts_empty_after_restart() {
    const PATH: &str = "Root.md";
    let fixture = ActivationFixture::nested_unicode("bootstrap-supersession", 0xa1d0);
    let activated = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(activated.status, SyncLocalActivationStatus::Active);
    let handle = activated.handle.expect("activation must retain an actor");
    drive_initial_feed(&handle);

    let graph = Graph::open_checked(&fixture.graph_root).unwrap();
    let endpoint = ProjectionEndpointBinding {
        endpoint_id: fixture.request.identities.endpoint_id,
        device_id: fixture.request.identities.device_id,
        graph_resource_id: graph.canonical_resource_id().unwrap(),
    };
    drop(graph);
    let completion_count = || {
        ProjectionReceiptStore::open_for_endpoint(
            &fixture.request.receipt_root,
            fixture.request.identities.workspace_id,
            endpoint,
        )
        .unwrap()
        .validated_catalog()
        .unwrap()
        .into_iter()
        .filter(|entry| entry.completion.is_some())
        .count()
    };
    assert_eq!(completion_count(), 0);

    let edited = b"title:: Root logical\r\n\r\n- externally changed exact bytes\r\n";
    fs::write(fixture.graph_root.join(PATH), edited).unwrap();
    handle
        .observe_watcher(vec![SyncWatcherObservation::managed_path(PATH).unwrap()])
        .unwrap();
    let settled = drain_until_settled(&handle);
    assert!(
        settled
            .iter()
            .any(|tick| matches!(tick, SyncRuntimeTick::AdmittedComplete { .. })),
        "bootstrap-backed external edit did not complete: {settled:?}"
    );
    assert_eq!(fs::read(fixture.graph_root.join(PATH)).unwrap(), edited);
    let after_import = completion_count();
    assert_eq!(
        after_import, 0,
        "an own-endpoint external admission uses turn/local-completion authority, not receipts"
    );
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));

    let reopened = SyncRuntimeHandle::open(reopen_request(&fixture.request));
    assert_eq!(reopened.status, SyncRuntimeOpenStatus::Active);
    let reopened = reopened.handle.expect("promoted runtime must reopen");
    drive_initial_feed(&reopened);
    assert_eq!(completion_count(), after_import);
    assert_eq!(fs::read(fixture.graph_root.join(PATH)).unwrap(), edited);
    assert!(matches!(
        reopened.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

fn assert_public_activation_cut_resumes(
    label: &str,
    cut: ActivationTestCut,
    expected_stage: SyncLocalActivationStage,
    seed: u128,
) {
    let fixture = ActivationFixture::nested_unicode(label, seed);
    let before = user_graph_bytes(&fixture.graph_root);
    fail_once_at_activation_cut(cut);
    let mut interrupted_phases = Vec::new();
    let interrupted = SyncRuntimeHandle::activate_or_resume_local_with_progress(
        fixture.request.clone(),
        |phase| interrupted_phases.push(phase),
    );
    assert!(matches!(
        interrupted.status,
        SyncLocalActivationStatus::Retryable { durable_stage, .. }
            if durable_stage == expected_stage
    ));
    assert!(interrupted.handle.is_none());
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);
    assert!(interrupted_phases
        .first()
        .is_none_or(|phase| *phase == SyncLocalActivationPhase::PrivateSetup));

    let mut resumed_phases = Vec::new();
    let resumed = SyncRuntimeHandle::activate_or_resume_local_with_progress(
        fixture.request.clone(),
        |phase| resumed_phases.push(phase),
    );
    assert_eq!(resumed.status, SyncLocalActivationStatus::Active);
    let handle = resumed
        .handle
        .expect("resumed activation must become active");
    assert_eq!(
        resumed_phases.last(),
        Some(&SyncLocalActivationPhase::ReconciliationBaselineActorOpen)
    );
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);
    drop(handle);
}

/// H2 2c: once the marker has transferred authority to the sealed baseline,
/// a later activation failure must retain that complete state for the next
/// open. Reclaiming the archive at this point strands the marker and turns a
/// one-shot runtime-open failure into a permanent half-live store.
#[test]
fn failure_after_clean_activation_retain_completes_on_the_next_open() {
    let fixture = ActivationFixture::nested_unicode("post-retain-resume", 0xa1f5_c200);
    let before = user_graph_bytes(&fixture.graph_root);
    fail_once_after_clean_activation_retain();

    let interrupted = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert!(interrupted.handle.is_none());
    assert!(matches!(
        interrupted.status,
        SyncLocalActivationStatus::Retryable {
            durable_stage: SyncLocalActivationStage::LocalActive,
            ..
        }
    ));
    assert!(fixture
        .request
        .enrollment_root
        .join(crate::oplog::lazy_genesis::LAZY_GENESIS_ACTIVATION_MARKER_FILE)
        .is_file());
    assert!(clean_baseline_directory(&fixture.request.archive_root).is_dir());
    assert!(clean_operation_archive_directory(&fixture.request.archive_root).is_dir());
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);

    let resumed = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
    assert_eq!(resumed.status, SyncLocalActivationStatus::Active);
    let handle = resumed
        .handle
        .expect("the retained marker, baseline, and archive resume");
    drive_initial_feed(&handle);
    assert_eq!(user_graph_bytes(&fixture.graph_root), before);
    assert!(matches!(
        handle.clean_shutdown().unwrap(),
        SyncShutdownOutcome::Safe(_)
    ));
}

#[test]
fn managed_activation_abort_cuts_retire_unmarked_generation_and_retry() {
    const CUT_ENV: &str = "TINE_TEST_CLEAN_ACTIVATION_ABORT_CUT";
    const ROOT_ENV: &str = "TINE_TEST_CLEAN_ACTIVATION_ABORT_ROOT";
    const SEED: u128 = 0xa1f5_c2f0;

    if let (Ok(cut), Ok(root)) = (std::env::var(CUT_ENV), std::env::var(ROOT_ENV)) {
        let fixture = ActivationFixture::nested_unicode_at(PathBuf::from(root), SEED);
        let result = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        panic!("activation did not abort at {cut}: {:?}", result.status);
    }

    for cut in [
        "after-baseline-publication",
        "after-sqlite-publication",
        "after-final-source-verification",
    ] {
        let root = std::env::temp_dir().join(format!(
            "tine-managed-activation-abort-{cut}-{}",
            Uuid::new_v4()
        ));
        let status = std::process::Command::new(std::env::current_exe().unwrap())
            .arg("--exact")
            .arg("sync_runtime::tests::managed_activation_abort_cuts_retire_unmarked_generation_and_retry")
            .arg("--nocapture")
            .env(CUT_ENV, cut)
            .env(ROOT_ENV, &root)
            .status()
            .unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::process::ExitStatusExt as _;
            assert_eq!(status.signal(), Some(libc::SIGABRT), "{cut}");
        }
        #[cfg(not(unix))]
        assert!(
            !status.success(),
            "the activation child must abort at {cut}"
        );

        let fixture = ActivationFixture::reopen_at(root, SEED);
        let before = user_graph_bytes(&fixture.graph_root);
        assert!(
            clean_baseline_directory(&fixture.request.archive_root).is_dir(),
            "{cut} must retain the unmarked baseline generation"
        );
        assert_eq!(
            fixture.request.database_path.is_file(),
            cut != "after-baseline-publication",
            "{cut} SQLite publication state"
        );
        assert!(
            read_activation_marker(&fixture.request.enrollment_root)
                .unwrap()
                .is_none(),
            "{cut} must precede the marker commit"
        );

        let resumed = SyncRuntimeHandle::activate_or_resume_local(fixture.request.clone());
        assert_eq!(resumed.status, SyncLocalActivationStatus::Active, "{cut}");
        let handle = resumed.handle.expect("the crash retry must become active");
        assert_eq!(user_graph_bytes(&fixture.graph_root), before, "{cut}");
        let marker = read_activation_marker(&fixture.request.enrollment_root)
            .unwrap()
            .expect("the retry publishes one authority marker");
        let active =
            clean_authority_directories(&fixture.request.archive_root, marker.generation());
        assert!(active.baseline.is_dir(), "{cut}");
        assert!(active.operations.is_dir(), "{cut}");
        let authority_directories = fs::read_dir(&fixture.request.archive_root)
            .unwrap()
            .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
            .filter(|name| {
                clean_authority_generation(
                    name,
                    crate::oplog::lazy_genesis::LAZY_GENESIS_BASELINE_DIRECTORY,
                )
                .is_some()
                    || clean_authority_generation(name, CLEAN_OPERATION_ARCHIVE_DIRECTORY).is_some()
                    || name.starts_with(".clean-join-")
            })
            .collect::<Vec<_>>();
        assert_eq!(
            authority_directories.len(),
            2,
            "{cut}: {authority_directories:?}"
        );
        drop(handle);
    }
}

